import socket
import time
import signal
import sys
import threading
import logging

try:
    from gpiozero import DigitalOutputDevice, PWMOutputDevice
    from gpiozero.pins.native import NativeFactory
except ImportError:
    NativeFactory = None
    DigitalOutputDevice = None
    PWMOutputDevice = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

HOST = '0.0.0.0'
PORT = 12345

MOTOR_A_FORWARD_PIN = 27
MOTOR_A_BACKWARD_PIN = 22
MOTOR_B_CLOCKWISE_PIN = 24
MOTOR_B_COUNTERCLOCKWISE_PIN = 25
MOTOR_A_ENABLE_PIN = 17
MOTOR_B_ENABLE_PIN = 23

MOISTURE_SENSOR_1_CHANNEL = 0
MOISTURE_SENSOR_2_CHANNEL = 1

DEFAULT_THRESHOLD = 30
DEFAULT_WATERING_DURATION = 5

PWM_FREQUENCY = 1000

server_socket = None
motor_a_forward = None
motor_a_backward = None
motor_b_clockwise = None
motor_b_counterclockwise = None
motor_a_enable = None
motor_b_enable = None
mcp_adc_1 = None
mcp_adc_2 = None

shutdown_event = threading.Event()


def signal_handler(signum, frame):
    logging.info(f"Signal {signum} received, shutting down...")
    shutdown_event.set()


def initialize_gpio():
    global motor_a_forward, motor_a_backward, motor_b_clockwise, motor_b_counterclockwise
    global motor_a_enable, motor_b_enable
    if DigitalOutputDevice is None or PWMOutputDevice is None:
        logging.error("gpiozero library not available. Running in simulation mode.")
        return False
    try:
        motor_a_forward = DigitalOutputDevice(MOTOR_A_FORWARD_PIN)
        motor_a_backward = DigitalOutputDevice(MOTOR_A_BACKWARD_PIN)
        motor_b_clockwise = DigitalOutputDevice(MOTOR_B_CLOCKWISE_PIN)
        motor_b_counterclockwise = DigitalOutputDevice(MOTOR_B_COUNTERCLOCKWISE_PIN)
        motor_a_enable = PWMOutputDevice(MOTOR_A_ENABLE_PIN, frequency=PWM_FREQUENCY)
        motor_b_enable = PWMOutputDevice(MOTOR_B_ENABLE_PIN, frequency=PWM_FREQUENCY)
        motor_a_enable.value = 0.0
        motor_b_enable.value = 0.0
        logging.info("GPIO initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        return False


def initialize_mcp3008():
    global mcp_adc_1, mcp_adc_2
    if NativeFactory is None:
        logging.error("NativeFactory not available. Running in simulation mode.")
        return False
    try:
        mcp_adc_1 = MCP3008(channel=MOISTURE_SENSOR_1_CHANNEL, pin_factory=NativeFactory())
        mcp_adc_2 = MCP3008(channel=MOISTURE_SENSOR_2_CHANNEL, pin_factory=NativeFactory())
        logging.info("MCP3008 ADC initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"MCP3008 initialization failed: {e}")
        return False


def read_moisture_level(channel):
    if channel == MOISTURE_SENSOR_1_CHANNEL:
        adc = mcp_adc_1
    elif channel == MOISTURE_SENSOR_2_CHANNEL:
        adc = mcp_adc_2
    else:
        logging.error(f"Invalid channel: {channel}")
        return -1
    try:
        total = 0
        for _ in range(5):
            total += adc.value
            time.sleep(0.02)
        return total / 5
    except Exception as e:
        logging.error(f"Error reading moisture sensor on channel {channel}: {e}")
        return -1


def control_motor(motor_a_fwd, motor_a_bwd, motor_b_cw, motor_b_ccw, enable_a, enable_b, duration):
    try:
        enable_a.value = 0.5
        enable_b.value = 0.5
        motor_a_fwd.on()
        motor_a_bwd.off()
        motor_b_cw.on()
        motor_b_ccw.off()
        time.sleep(duration)
        enable_a.value = 0.0
        enable_b.value = 0.0
        motor_a_fwd.off()
        motor_b_cw.off()
    except Exception as e:
        logging.error(f"Error controlling motor: {e}")
        try:
            enable_a.value = 0.0
            enable_b.value = 0.0
            motor_a_fwd.off()
            motor_b_cw.off()
        except Exception:
            pass


def water_plant(plant_number, watering_duration):
    if plant_number == 1:
        control_motor(motor_a_forward, motor_a_backward, motor_b_clockwise, motor_b_counterclockwise, motor_a_enable, motor_b_enable, watering_duration)
    elif plant_number == 2:
        control_motor(motor_b_clockwise, motor_b_counterclockwise, motor_a_forward, motor_a_backward, motor_b_enable, motor_a_enable, watering_duration)
    else:
        logging.error(f"Invalid plant number: {plant_number}")


def get_sensor_data():
    level1 = read_moisture_level(MOISTURE_SENSOR_1_CHANNEL)
    level2 = read_moisture_level(MOISTURE_SENSOR_2_CHANNEL)
    return level1, level2


def handle_client(conn, addr, threshold, watering_duration):
    try:
        while not shutdown_event.is_set():
            data = conn.recv(1024).decode('utf-8').strip()
            if not data:
                break
            logging.info(f"Received from {addr}: {data}")
            if data == 'WATER_PLANT_1':
                water_plant(1, watering_duration)
            elif data == 'WATER_PLANT_2':
                water_plant(2, watering_duration)
            elif data == 'GET_SENSOR_DATA':
                level1, level2 = get_sensor_data()
                conn.sendall(f'SENSOR_DATA_1:{level1},SENSOR_DATA_2:{level2}\n'.encode('utf-8'))
            elif data.startswith('SET_THRESHOLD'):
                try:
                    new_threshold = int(data.split(' ')[1])
                    threshold = new_threshold
                    conn.sendall(f'THRESHOLD_SET:{threshold}\n'.encode('utf-8'))
                except (IndexError, ValueError):
                    conn.sendall('ERROR: Invalid threshold value\n'.encode('utf-8'))
            elif data.startswith('SET_WATERING_DURATION'):
                try:
                    new_duration = int(data.split(' ')[1])
                    watering_duration = new_duration
                    conn.sendall(f'WATERING_DURATION_SET:{watering_duration}\n'.encode('utf-8'))
                except (IndexError, ValueError):
                    conn.sendall('ERROR: Invalid watering duration value\n'.encode('utf-8'))
            else:
                conn.sendall('ERROR: Invalid command\n'.encode('utf-8'))
    except Exception as e:
        logging.error(f"Error handling client {addr}: {e}")
    finally:
        try:
            conn.close()
        except Exception:
            pass


def run_server(threshold, watering_duration):
    global server_socket
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((HOST, PORT))
        server_socket.listen(5)
        server_socket.settimeout(1.0)
        logging.info(f"Server listening on {HOST}:{PORT}")
        while not shutdown_event.is_set():
            try:
                conn, addr = server_socket.accept()
                client_thread = threading.Thread(target=handle_client, args=(conn, addr, threshold, watering_duration))
                client_thread.daemon = True
                client_thread.start()
            except socket.timeout:
                continue
            except Exception as e:
                if not shutdown_event.is_set():
                    logging.error(f"Error accepting connection: {e}")
    except Exception as e:
        logging.error(f"Server error: {e}")
    finally:
        if server_socket:
            server_socket.close()


def cleanup():
    logging.info("Cleaning up resources...")
    try:
        if motor_a_enable:
            motor_a_enable.value = 0.0
            motor_a_enable.close()
        if motor_b_enable:
            motor_b_enable.value = 0.0
            motor_b_enable.close()
        if motor_a_forward:
            motor_a_forward.close()
        if motor_a_backward:
            motor_a_backward.close()
        if motor_b_clockwise:
            motor_b_clockwise.close()
        if motor_b_counterclockwise:
            motor_b_counterclockwise.close()
    except Exception as e:
        logging.error(f"Error during GPIO cleanup: {e}")


def main():
    global server_socket
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    threshold = DEFAULT_THRESHOLD
    watering_duration = DEFAULT_WATERING_DURATION
    gpio_available = initialize_gpio()
    adc_available = initialize_mcp3008()
    if not gpio_available and not adc_available:
        logging.error("No hardware available. Exiting.")
        return
    server_thread = threading.Thread(target=run_server, args=(threshold, watering_duration))
    server_thread.daemon = True
    server_thread.start()
    last_health_check = time.time()
    try:
        while not shutdown_event.is_set():
            if time.time() - last_health_check >= 60:
                level1, level2 = get_sensor_data()
                if level1 != -1 and level2 != -1:
                    logging.info(f"Health check: Sensor 1: {level1:.2f}, Sensor 2: {level2:.2f}")
                else:
                    logging.warning("Health check: Sensor data unavailable.")
                last_health_check = time.time()
            time.sleep(1)
    except Exception as e:
        logging.error(f"Main loop error: {e}")
    finally:
        shutdown_event.set()
        if server_thread.is_alive():
            server_thread.join(timeout=5)
        cleanup()
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

