import time
import logging
import argparse
import threading
import queue
import spidev
import RPi.GPIO as GPIO


class SoundSensor:
    """
    Represents a sound sensor connected to a Raspberry Pi.
    Supports digital (KY-038-style) and analog (MCP3008) sensors.
    """

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate,
                 gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.stop_event = threading.Event()
        self.spi = None
        self._lock = threading.Lock()
        self._initialized = False

        if self.sensor_type == "digital":
            if not self.gpio_pins:
                self._log_error("No GPIO pins provided for digital sensor.")
                return
            try:
                GPIO.setmode(GPIO.BCM)
                for pin in self.gpio_pins:
                    GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
                self._initialized = True
            except Exception as e:
                self._log_error(f"Failed to initialize digital GPIO pins: {e}")
        elif self.sensor_type == "analog":
            if not self.channels:
                self._log_error("No MCP3008 channels provided for analog sensor.")
                return
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
                self._initialized = True
            except Exception as e:
                self._log_error(f"Failed to initialize SPI for MCP3008: {e}")
        else:
            self._log_error(f"Invalid sensor type: {self.sensor_type}")

    def _log_error(self, message):
        logging.error(f"Sensor {self.sensor_id}: {message}")
        if self.log_queue:
            try:
                self.log_queue.put(f"ERROR: {message}")
            except Exception:
                pass

    def read_digital(self):
        try:
            return GPIO.input(self.gpio_pins[0])
        except Exception as e:
            self._log_error(f"Error reading digital GPIO: {e}")
            return None

    def read_analog(self):
        if not self.spi:
            return None
        try:
            for ch in self.channels:
                if not 0 <= ch <= 7:
                    self._log_error(f"Invalid MCP3008 channel: {ch}")
                    return None
                adc = self.spi.xfer2([1, (8 + ch) << 4, 0])
                data = ((adc[1] & 3) << 8) + adc[2]
                return data
        except Exception as e:
            self._log_error(f"Error reading MCP3008: {e}")
            return None

    def detect_sound(self):
        if self.sensor_type == "digital":
            return self.read_digital() == 1
        elif self.sensor_type == "analog":
            return self.read_analog() >= self.threshold
        return False

    def run(self):
        if not self._initialized:
            self._log_error("Sensor not initialized.")
            return
        try:
            while not self.stop_event.is_set():
                if self.detect_sound():
                    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                    message = (f"Sound detected by {self.sensor_id} at {timestamp} "
                               f"(threshold={self.threshold})")
                    logging.info(message)
                    if self.log_queue:
                        try:
                            self.log_queue.put(message)
                        except Exception:
                            pass
                time.sleep(1 / self.sample_rate)
                time.sleep(0.1)
        except Exception as e:
            self._log_error(f"Error in sound detection loop: {e}")
        finally:
            if self.sensor_type == "digital":
                try:
                    GPIO.cleanup(self.gpio_pins)
                except Exception:
                    pass
            elif self.sensor_type == "analog":
                try:
                    self.spi.close()
                except Exception:
                    pass

    def stop(self):
        self.stop_event.set()


def main():
    parser = argparse.ArgumentParser(description="Raspberry Pi Sound Sensor System")
    parser.add_argument("--sensor_type", required=True,
                        choices=["digital", "analog"],
                        help="Type of sound sensor (digital or analog)")
    parser.add_argument("--threshold", type=int, required=True,
                        help="Sound level threshold (0-1023 for analog, 1 for digital)")
    parser.add_argument("--sample_rate", type=float, required=True,
                        help="Sampling rate in Hz")
    parser.add_argument("--log_file", default="sound_sensor.log",
                        help="Path to the log file")
    parser.add_argument("--gpio_pins", nargs="+", type=int,
                        help="GPIO pins for digital sound sensor (BCM numbering)")
    parser.add_argument("--channels", nargs="+", type=int,
                        help="MCP3008 channels for analog sound sensor")
    parser.add_argument("--spi_speed", type=int, default=1000000,
                        help="SPI speed in Hz")
    parser.add_argument("--sensor_ids", nargs="+", required=True,
                        help="Unique IDs for each sound sensor")

    args = parser.parse_args()

    logging.basicConfig(
        filename=args.log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )

    log_queue = queue.Queue()
    threads = []

    for i, sensor_id in enumerate(args.sensor_ids):
        sensor_type = args.sensor_type
        threshold = args.threshold
        sample_rate = args.sample_rate
        gpio_pins = args.gpio_pins
        channels = args.channels
        spi_speed = args.spi_speed

        if sensor_type == "digital" and gpio_pins is None:
            logging.error(f"GPIO pins required for digital sensor {sensor_id}")
            continue
        if sensor_type == "analog" and channels is None:
            logging.error(f"MCP3008 channels required for analog sensor {sensor_id}")
            continue

        sensor = SoundSensor(
            sensor_id, sensor_type, threshold, sample_rate,
