import spidev
import time
import signal
import sys

# MCP3008 channel for the gas sensor
GAS_SENSOR_CHANNEL = 0
# Thresholds for gas concentration in ppm
SAFE_LIMIT = 150
WARNING_LIMIT = 399

# Global SPI device handle for signal handler cleanup
_spi = None


def _cleanup(signum=None, frame=None):
    """Release SPI resources on exit or signal."""
    global _spi
    if _spi is not None:
        try:
            _spi.close()
        except Exception:
            pass
        _spi = None
    if signum is not None:
        sys.exit(0)


class GasSensor:
    """Reads analog values from an MQ-2 gas sensor via an MCP3008 ADC."""

    def __init__(self, spi_bus=0, spi_device=0, channel=GAS_SENSOR_CHANNEL):
        """Initialize SPI communication and the sensor channel."""
        self.spi_channel = spi_device
        self.channel = channel
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(spi_bus, spi_device)
            self.spi.max_speed_hz = 1350000
            self.spi.mode = 0
        except OSError as e:
            raise RuntimeError(f"Failed to open SPI bus {spi_bus}, device {spi_device}: {e}") from e

    def read_raw_data(self):
        """Read the raw 10-bit value from the MCP3008 ADC."""
        # MCP3008 single-ended read: start bit, config byte, padding
        try:
            adc = self.spi.xfer2([1, (8 + self.channel) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except OSError as e:
            raise RuntimeError(f"SPI read failed on channel {self.channel}: {e}") from e

    def estimate_concentration(self, raw_data):
        """Estimate gas concentration in ppm from the raw ADC value."""
        # Simplified linear conversion; real calibration would use a lookup table
        return int(raw_data * 100 / 1023)

    def close(self):
        """Release the SPI device."""
        try:
            self.spi.close()
        except Exception:
            pass


def get_alert_level(concentration):
    """Return an alert level based on the estimated gas concentration."""
    if concentration < SAFE_LIMIT:
        return "safe"
    if concentration < WARNING_LIMIT:
        return "warning"
    return "danger"


def main():
    """Main loop: sample the gas sensor and print alerts."""
    global _spi
    sensor = None
    try:
        sensor = GasSensor()
        _spi = sensor.spi
        for i in range(12):
            raw = sensor.read_raw_data()
            ppm = sensor.estimate_concentration(raw)
            alert = get_alert_level(ppm)
            print(f"Sample {i+1}/12: {ppm} ppm ({alert})")
            time.sleep(0.5)
    except RuntimeError as e:
        print(f"Error: {e}", file=sys.stderr)
    except KeyboardInterrupt:
        print("\nInterrupted by user.", file=sys.stderr)
    finally:
        if sensor is not None:
            sensor.close()
        _cleanup()


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)
    main()

