import time
import signal
import sys

# BCM pin assignments
GAS_SENSOR_PIN = 16
WARNING_LED_PIN = 12

# Timing constants (seconds)
SAMPLE_INTERVAL = 0.5
FLASH_ON_TIME = 0.2
FLASH_OFF_TIME = 0.2
ALARM_FLASHES = 3

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for clean shutdown."""
    global _running
    _running = False


def _cleanup():
    """Release GPIO resources by closing the file descriptors we opened."""
    for pin in (GAS_SENSOR_PIN, WARNING_LED_PIN):
        try:
            with open('/sys/class/gpio/unexport', 'w') as f:
                f.write(str(pin))
        except OSError:
            pass


def _setup_gpio(pin, mode, label):
    """Export a GPIO pin and set its direction. Returns the pin number."""
    try:
        with open('/sys/class/gpio/export', 'w') as f:
            f.write(str(pin))
    except OSError as e:
        raise RuntimeError(f"Failed to export GPIO{pin} ({label}): {e}")

    path = f'/sys/class/gpio/gpio{pin}/direction'
    try:
        with open(path, 'w') as f:
            f.write(mode)
    except OSError as e:
        raise RuntimeError(f"Failed to set direction for GPIO{pin} ({label}): {e}")

    return pin


def _read_gpio(pin):
    """Read the current logic level of a GPIO pin. Returns 0 or 1."""
    path = f'/sys/class/gpio/gpio{pin}/value'
    try:
        with open(path, 'r') as f:
            return int(f.read().strip())
    except OSError as e:
        raise RuntimeError(f"Failed to read GPIO{pin}: {e}")


def _write_gpio(pin, value):
    """Write a value (0 or 1) to a GPIO pin."""
    path = f'/sys/class/gpio/gpio{pin}/value'
    try:
        with open(path, 'w') as f:
            f.write(str(int(value)))
    except OSError as e:
        raise RuntimeError(f"Failed to write GPIO{pin}: {e}")


def _flash_led(pin, count, on_time, off_time):
    """Flash the warning LED a given number of times."""
    for _ in range(count):
        _write_gpio(pin, 1)
        time.sleep(on_time)
        _write_gpio(pin, 0)
        time.sleep(off_time)


def main():
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize GPIO pins
    try:
        gas_pin = _setup_gpio(GAS_SENSOR_PIN, 'in', 'gas_sensor')
        led_pin = _setup_gpio(WARNING_LED_PIN, 'out', 'warning_led')
    except RuntimeError as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # Ensure LED starts off
    try:
        _write_gpio(led_pin, 0)
    except RuntimeError as e:
        print(f"Failed to initialize LED: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    gas_detected_count = 0
    alarm_triggered = False

    print("Gas sensor monitoring started. Press Ctrl+C to stop.")

    try:
        while _running:
            try:
                gas_value = _read_gpio(gas_pin)
            except RuntimeError as e:
                print(f"Sensor read error: {e}", file=sys.stderr)
                time.sleep(SAMPLE_INTERVAL)
                continue

            if gas_value == 0:
                gas_detected_count += 1
                print(f"Gas detected (consecutive count: {gas_detected_count})")

                if gas_detected_count >= 3 and not alarm_triggered:
                    print("WARNING: Gas level too high! Triggering alarm.")
                    try:
                        _flash_led(led_pin, ALARM_FLASHES, FLASH_ON_TIME, FLASH_OFF_TIME)
                    except RuntimeError as e:
                        print(f"LED flash error: {e}", file=sys.stderr)
                    alarm_triggered = True
            else:
                if gas_detected_count > 0:
                    print(f"Gas level normal (count: {gas_detected_count})")
                gas_detected_count = 0
                alarm_triggered = False

            time.sleep(SAMPLE_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        print("Cleaning up GPIO resources...")
        _cleanup()
        print("Program terminated.")


if __name__ == "__main__":
    main()

