import json
import logging
import signal
import sys
import time
from pathlib import Path

import cv2
import numpy as np

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    OutputDevice = None
    GPIOZeroError = Exception

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

CONFIG_FILE = 'config.json'

running = True


def signal_handler(signum, frame):
    global running
    logging.info(f'Signal {signum} received, shutting down...')
    running = False


def load_config(config_file):
    try:
        with open(config_file, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        logging.error(f'Configuration file not found: {config_file}')
    except json.JSONDecodeError as e:
        logging.error(f'Invalid JSON in configuration file: {config_file}: {e}')
    return None


def detect_bird(frame, config):
    try:
        if config.get('bird_detector_type') == 'yolov5':
            return detect_bird_yolov5(frame, config)
        elif config.get('bird_detector_type') == 'tflite':
            return detect_bird_tflite(frame, config)
        else:
            logging.warning('Unknown bird_detector_type.')
            return False
    except Exception as e:
        logging.error(f'Error during bird detection: {e}')
        return False


def detect_bird_yolov5(frame, config):
    try:
        from models.common import DetectMultiBackend
        from utils.general import non_max_suppression, scale_boxes
        from utils.plots import Annotator
        from utils.torch_utils import select_device

        device = select_device('')
        model = DetectMultiBackend(config['yolov5_weights_path'], device=device)
        stride, names = model.stride, model.names
        im = cv2.resize(frame, (640, 640))
        im = cv2.cvtColor(im, cv2.COLOR_BGR2RGB)
        im = np.ascontiguousarray(im)
        im = torch.from_numpy(im).to(device)
        im = im.half() if model.fp16 else im.float()
        im /= 255
        if len(im.shape) == 3:
            im = im[None]
        pred = model(im, augment=False, visualize=False)
        pred = non_max_suppression(pred, 0.25, 0.45, None, False, max_det=1000)
        det = pred[0]
        if len(det):
            det[:, :4] = scale_boxes(im.shape[2:], det[:, :4], frame.shape).round()
            for *xyxy, conf, cls in reversed(det):
                if int(cls) == 0:
                    return True
        return False
    except Exception as e:
        logging.error(f'Error during YOLOv5 inference: {e}')
        return False


def detect_bird_tflite(frame, config):
    try:
        from tflite_runtime.interpreter import Interpreter
        import tflite_runtime.hacks as hacks
        hacks.apply_all()

        interpreter = Interpreter(model_path=config['tflite_weights_path'])
        interpreter.allocate_tensors()
        input_details = interpreter.get_input_details()
