import io
import time
import json
import signal
import logging
import threading
import queue
import sys

import cv2
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import FileOutput

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class MotionDetector:
    """
    Motion detector using the Raspberry Pi Camera Module via picamera2.
    Captures JPEG frames, detects motion via frame differencing, and triggers
    an LED alert via a threading.Timer.
    """

    def __init__(self, config_path):
        self.config = self._load_config(config_path)
        self.resolution = tuple(self.config['camera_resolution'])
        self.framerate = self.config['camera_framerate']
        self.queue_size = self.config['queue_size']
        self.gpio_pin = self.config.get('gpio_pin')
        self.led_duration = self.config['led_duration']
        self.motion_threshold = self.config['motion_threshold']
        self._running = True
        self._frame_queue = queue.Queue(maxsize=self.queue_size)
        self._picam2 = None
        self._led_timer = None
        self._led_lock = threading.Lock()
        self._lock = threading.Lock()
        self._last_frame = None
        self._last_frame_lock = threading.Lock()

        self._setup_gpio()
        self._initialize_camera()

    def _load_config(self, config_path):
        try:
            with open(config_path, 'r') as f:
                return json.load(f)
        except FileNotFoundError:
            logger.error(f"Configuration file not found: {config_path}")
            raise
        except json.JSONDecodeError as e:
            logger.error(f"Invalid JSON in configuration file: {config_path}: {e}")
            raise

    def _setup_gpio(self):
        if self.gpio_pin is not None:
            try:
                from gpiozero import LED
                self.led = LED(self.gpio_pin)
                self.led.off()
                logger.info(f"GPIO pin {self.gpio_pin} configured for LED output.")
            except Exception as e:
                logger.error(f"Failed to initialize GPIO pin {self.gpio_pin}: {e}")
                raise
        else:
            self.led = None

    def _initialize_camera(self):
        try:
            self._picam2 = Picamera2()
            config = self._picam2.create_video_configuration(
                main={"size": self.resolution, "format": "RGB888"},
                controls={"FrameRate": self.framerate}
            )
            self._picam2.configure(config)
            self._picam2.start()
            time.sleep(2)  # Camera warm-up time
            logger.info("Camera initialized successfully.")
        except Exception as e:
            logger.error(f"Failed to initialize camera: {e}")
            self.cleanup()
            raise

    def capture_frame(self):
        try:
            frame = self._picam2.capture_array()
            if frame is None or frame.size == 0:
                logger.warning("Captured empty frame.")
                return None
            return frame
        except Exception as e:
            logger.error(f"Error capturing frame: {e}")
            return None

    def detect_motion(self, frame):
        try:
            gray = cv2.cvtColor(frame, cv2.COLOR_RGB2GRAY)
            gray = cv2.GaussianBlur(gray, (21, 21), 0)
            with self._last_frame_lock:
                if self._last_frame is None:
                    self._last_frame = gray.copy().astype("float")
                    return False

                frame_delta = cv2.absdiff(self._last_frame, gray)
                thresh = cv2.threshold(frame_delta, self.motion_threshold, 255, cv2.THRESH_BINARY)[1]
                thresh = cv2.dilate(thresh, None, iterations=2)
                contours, _ = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

                self._last_frame = gray.copy().astype("float")

                for c in contours:
                    if cv2.contourArea(c) < 250:
                        continue
                    return True
                return False
        except Exception as e:
            logger.error(f"Error detecting motion: {e}")
            return False

    def trigger_alert(self):
        if self.led:
            with self._led_lock:
                if self._led_timer and self._led_timer.is_alive():
                    self._led_timer.cancel()
                self.led.on()
                self._led_timer = threading.Timer(self.led_duration, self._deactivate_led)
                self._led_timer.daemon = True
                self._led_timer.start()
            logger.info("LED activated.")

    def _deactivate_led(self):
        if self.led:
            with self._led_lock:
                self.led.off()
                self._led_timer = None
            logger.info("LED deactivated.")

    def capture_and_encode_frame(self):
        frame = self.capture_frame()
        if frame is None:
            return None

        try:
            ret, jpeg = cv2.imencode('.jpg', frame)
            if not ret:
                logger.error("Failed to encode frame to JPEG.")
                return None
            return jpeg.tobytes()
        except Exception as e:
            logger.error(f"Error encoding frame: {e}")
            return None

    def run(self):
        logger.info("Starting motion detection loop...")
        while self._running:
            frame_data = self.capture_and_encode_frame()
            if frame_data is None:
                time.sleep(0.1)
                continue

            try:
                self._frame_queue.put(frame_data, block=False)
            except queue.Full:
                logger.warning("Frame queue is full. Dropping frame.")

            if self.detect_motion(frame_data):
                logger.info("Motion detected!")
                self.trigger_alert()

            time.sleep(0.1)

    def stop(self):
        logger.info("Stopping motion detection loop...")
        self._running = False

    def cleanup(self):
        logger.info("Cleaning up resources...")
        if self._picam2:
            try:
                self._picam2.stop()
            except Exception as e:
                logger.error(f"Error stopping camera: {e}")
        if self.led:
            try:
                self.led.close()
            except Exception as e:
                logger.error(f"Error closing GPIO pin: {e}")
        logger.info("Cleanup complete.")


def main():
    detector = None
    def signal_handler(sig, frame):
        logger.info(f"Signal {sig} received. Shutting down...")
        if detector:
            detector.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        detector = MotionDetector("config.json")
        detector.run()
    except Exception as e:
        logger.error(f"An error occurred: {e}")
    finally:
        if detector:
            detector.cleanup()


if __name__ == "__main__":
    main()

