import cv2
import sys
import time
import signal
import logging

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

CAMERA_INDEX = 0
CASCADE_FILE = '/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml'
RESIZE_DIM = (32, 32)
WINDOW_NAME = 'Human Detection'

LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18
SERVO_FREQ = 50
SERVO_STEP = 20
SERVO_MIN = 0
SERVO_MAX = 180

running = True


def signal_handler(signum, frame):
    global running
    running = False


class HardwareController:
    def __init__(self):
        self.led = None
        self.button = None
        self.servo = None
        self._init_gpio()

    def _init_gpio(self):
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
            GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            GPIO.setup(SERVO_PIN, GPIO.OUT)
            self.led = GPIO
            self.button = GPIO
            self.servo = GPIO
            logging.info('GPIO initialized successfully.')
        except Exception as e:
            logging.error(f'GPIO initialization failed: {e}. Continuing without GPIO control.')

    def set_led(self, state):
        if self.led is None:
            return
        try:
            self.led.output(LED_PIN, state)
        except Exception as e:
            logging.error(f'Error setting LED: {e}')

    def get_button(self):
        if self.button is None:
            return False
        try:
            return self.button.input(BUTTON_PIN)
        except Exception as e:
            logging.error(f'Error reading button: {e}')
            return False

    def set_servo(self, angle):
        if self.servo is None:
            return
        try:
            pwm = self.servo.PWM(SERVO_PIN, SERVO_FREQ)
            pwm.start(0)
            duty = (angle / 18) + 2.5
            pwm.ChangeDutyCycle(duty)
            time.sleep(0.02)
            pwm.stop()
        except Exception as e:
            logging.error(f'Error setting servo: {e}')

    def cleanup(self):
        if self.led is not None:
            try:
                self.led.output(LED_PIN, False)
            except Exception:
                pass
        if self.servo is not None:
            try:
                self.servo.PWM(SERVO_PIN, SERVO_FREQ).stop()
            except Exception:
                pass


def detect_faces(img, cascade):
    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    resized = cv2.resize(gray, RESIZE_DIM)
    return cascade.detectMultiScale(resized, 1.3, 5)


def draw_rectangles(img, faces):
    for (x, y, w, h) in faces:
        cv2.rectangle(img, (x, y), (x + w, y + h), (255, 0, 0), 2)


