        if self.servo is None:
            return
        try:
            pwm = self.servo.PWM(SERVO_PIN, SERVO_FREQ)
            pwm.start(0)
            duty = (angle / 18) + 2.5
            pwm.ChangeDutyCycle(duty)
            time.sleep(0.02)
            pwm.stop()
        except Exception as e:
            logging.error(f'Error setting servo: {e}')

    def cleanup(self):
        if self.led is not None:
            try:
                self.led.output(LED_PIN, False)
            except Exception:
                pass
        if self.servo is not None:
