import time
import sqlite3
import logging
import signal
import sys
import os

# Configure logging
logging.basicConfig(
    filename='error.log',
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)

# Sensor configuration
SENSOR_CONFIG = {
    'BMP280': {'class': 'sensors.BMP280', 'id': 1, 'address': 0x76},
    'BME280': {'class': 'sensors.BME280', 'id': 2, 'address': 0x77},
    'MS8607': {'class': 'sensors.MS8607', 'id': 3, 'address': 0x76}
}

def load_config(config_file='config.txt'):
    """Loads configuration from a file."""
    config = {}
    try:
        with open(config_file, 'r') as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#'):
                    if '=' in line:
                        key, value = line.split('=', 1)
                        config[key.strip()] = value.strip()
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
    except Exception as e:
        logging.error(f"Error loading configuration: {e}")
    return config

def initialize_sensors(config):
    """Initializes sensors based on configuration."""
    sensors = []
    for i in range(1, 4):
        sensor_type = config.get(f'Sensor{i}_Type')
        if sensor_type:
            sensor_config = SENSOR_CONFIG.get(sensor_type)
            if sensor_config:
                try:
                    module_name, class_name = sensor_config['class'].rsplit('.', 1)
                    module = __import__(module_name, fromlist=[class_name])
                    sensor_class = getattr(module, class_name)
                    sensor = sensor_class(sensor_config['id'], sensor_config['address'])
                    sensors.append(sensor)
                    print(f"Initialized {sensor_type} sensor (ID: {sensor_config['id']}, Address: 0x{sensor_config['address']:02X})")
                except ImportError as e:
                    logging.error(f"Import error for {sensor_type}: {e}")
                except Exception as e:
                    logging.error(f"Error initializing {sensor_type}: {e}")
            else:
                logging.error(f"Invalid sensor type: {sensor_type}")
    return sensors

def read_sensor_data(sensor):
    """Reads data from a sensor."""
    try:
        data = sensor.read_data()
        if data:
            return data
        else:
            logging.warning(f"No data returned from sensor: {sensor.sensor_type}")
            return None
    except Exception as e:
        logging.error(f"Error reading data from sensor {sensor.sensor_type}: {e}")
        return None

def validate_data(data):
    """Validates sensor data."""
    if not data:
        return False
    if not (70000 <= data['pressure'] <= 110000):
        logging.warning(f"Invalid pressure value: {data['pressure']}")
        return False
    if not (-20 <= data['temperature'] <= 50):
        logging.warning(f"Invalid temperature value: {data['temperature']}")
        return False
    if 'humidity' in data and not (0 <= data['humidity'] <= 100):
        logging.warning(f"Invalid humidity value: {data['humidity']}")
        return False
    return True

def store_data(conn, data, sensor_type, sensor_id):
    """Stores sensor data in the database."""
    try:
        cursor = conn.cursor()
        cursor.execute('''
            INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent)
            VALUES (?, ?, ?, ?, ?, ?)
        ''', (data['timestamp'], sensor_type, sensor_id, data['pressure'], data['temperature'], data.get('humidity')))
        conn.commit()
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")

def main():
    """Main function to run the sensor monitoring."""
    config = load_config()
    sampling_interval = int(config.get('Sampling_Interval_Seconds', 60))
    sensors = initialize_sensors(config)

    if not sensors:
        print("No sensors initialized. Exiting.")
        return

    conn = None
    try:
        conn = sqlite3.connect('wildlife_data.db')
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT,
                sensor_type TEXT,
                sensor_id INTEGER,
                pressure_pa REAL,
                temperature_c REAL,
                humidity_percent REAL
            )
        ''')
        conn.commit()
    except sqlite3.Error as e:
        logging.error(f"Database connection error: {e}")
        return

    try:
        while running:
            for sensor in sensors:
                if not running:
                    break
                data = read_sensor_data(sensor)
                if data and validate_data(data):
                    store_data(conn, data, sensor.sensor_type, sensor.sensor_id)
            time.sleep(sampling_interval)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        if conn:
            conn.close()
            print("Database connection closed.")
        print("Program terminated.")

if __name__ == "__main__":
    main()

