import time
import random
import signal
import sys
import smbus
from gpiozero import Buzzer

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
AMG8833_ADDR = 0x69
BUZZER_PIN = 17
TEMP_THRESHOLD = 30.0          # °C
POLL_INTERVAL = 0.1            # seconds
BUZZER_DURATION = 1.0          # seconds
SIMULATE_ON_ERROR = True

# --- Globals for cleanup -----------------------------------------------------
buzzer = None
i2c_bus = None
running = True


def cleanup(signum=None, frame=None):
    """Release resources on exit or signal."""
    global running, buzzer, i2c_bus
    running = False
    if buzzer is not None:
        try:
            buzzer.close()
        except Exception:
            pass
        buzzer = None
    if i2c_bus is not None:
        try:
            i2c_bus.close()
        except Exception:
            pass
        i2c_bus = None
    if signum is not None:
        sys.exit(0)


def init_i2c():
    """Open the I2C bus and verify the AMG8833 is present."""
    global i2c_bus
    try:
        i2c_bus = smbus.SMBus(I2C_BUS)
    except FileNotFoundError:
        print("Error: I2C bus /dev/i2c-{} not found. Enable I2C with 'sudo raspi-config'.".format(I2C_BUS))
        return False
    except PermissionError:
        print("Error: Permission denied on /dev/i2c-{}. Run as root or add user to the 'i2c' group.".format(I2C_BUS))
        return False
    except OSError as e:
        print("Error: Cannot open I2C bus {}: {}".format(I2C_BUS, e))
        return False

    # Probe the AMG8833 by reading the manufacturer ID register (0x0C).
    try:
        # AMG8833 returns 0x54 when read; some breakers return 0x00 on power-up.
        # We accept both as a positive presence indication.
        mid = i2c_bus.read_byte_data(AMG8833_ADDR, 0x0C)
        if mid not in (0x54, 0x00):
            print("Warning: Unexpected manufacturer ID 0x{:02X} at 0x{:02X} (expected 0x54).".format(mid, AMG8833_ADDR))
    except OSError as e:
        print("Error: No AMG8833 detected at 0x{:02X} on bus {}: {}".format(AMG8833_ADDR, I2C_BUS, e))
        try:
            i2c_bus.close()
        except Exception:
            pass
        i2c_bus = None
        return False

    return True


def read_thermal_data():
    """Read 8×8 temperature data from the AMG8833.

    Returns a list of 64 floats in row-major order, or None on error.
    """
    global i2c_bus
    if i2c_bus is None:
        return None
    try:
        # Point to pixel 0 (register 0x80) and read 128 bytes (64 pixels × 2 bytes).
        data = i2c_bus.read_i2c_block_data(AMG8833_ADDR, 0x80, 128)
    except OSError as e:
        print("Error: I2C read failed: {}".format(e))
        return None

    if len(data) != 128:
        print("Error: Expected 128 bytes from AMG8833, got {}".format(len(data)))
        return None

    thermal_data = []
    for i in range(0, 128, 2):
        raw = (data[i] << 8) | data[i + 1]
        # Convert 13-bit two's complement to signed integer.
        if raw & 0x1000:
            raw -= 0x2000
        # Convert 10-bit resolution to °C.
        temp = raw * 0.25
        thermal_data.append(temp)
    return thermal_data


def detect_human(thermal_data):
    """Return True if any pixel exceeds TEMP_THRESHOLD °C."""
    if thermal_data is None:
        return False
    return any(temp > TEMP_THRESHOLD for temp in thermal_data)


def trigger_alert(buzzer):
    """Sound the buzzer for BUZZER_DURATION seconds."""
    if buzzer is None:
        return
    try:
        buzzer.on()
        time.sleep(BUZZER_DURATION)
        buzzer.off()
    except Exception as e:
        print("Error: Buzzer control failed: {}".format(e))


def simulate_thermal_data():
    """Return a simulated 8×8 thermal matrix for testing."""
    return [random.uniform(20.0, 45.0) for _ in range(64)]


def main():
    global buzzer

    # Register signal handlers for clean shutdown.
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize the buzzer.
    try:
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as e:
        print("Error: Failed to initialize buzzer on GPIO{}: {}".format(BUZZER_PIN, e))
        sys.exit(1)

    # Initialize I2C and verify the AMG8833.
    if not init_i2c():
        print("Warning: I2C init failed; will simulate thermal data.")

    print("Starting AMG8833 thermal monitoring. Press Ctrl+C to exit.")

    while running:
        thermal_data = read_thermal_data()
        if thermal_data is None:
            if SIMULATE_ON_ERROR:
                print("Sensor error detected; simulating thermal data...")
                thermal_data = simulate_thermal_data()
            else:
                print("Sensor error detected; skipping this cycle.")
        else:
            print("Thermal data received successfully.")

        if detect_human(thermal_data):
            print("Human detected! Triggering alert.")
            trigger_alert(buzzer)
        else:
            print("No human detected.")

        time.sleep(POLL_INTERVAL)

    cleanup()


if __name__ == "__main__":
    main()

