_bus = None
_running = True


def _cleanup():
    """Release GPIO and I2C resources."""
    global _bus
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if _bus is not None:
        try:
            _bus.close()
        except Exception:
            pass
        _bus = None


def _handle_sigint(signum, frame):
    """Graceful shutdown on Ctrl-C."""
    global _running
    _running = False


def _pcf8574_read_byte():
    """Read a single byte from the PCF8574 and return it, or None on error."""
    global _bus
    if _bus is None:
        return None
    try:
        return _bus.read_byte(PCF8574_ADDR)
    except OSError as exc:
        print(f"I2C read error from PCF8574 at 0x{PCF8574_ADDR:02X}: {exc}")
