import signal
import sys
import time
import board
import busio
import digitalio
from adafruit_bme280 import basic as adafruit_bme280
from adafruit_epd.il0373 import IL0373
from adafruit_epd import WHITE, BLACK

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _make_pin(pin_name):
    try:
        return digitalio.DigitalInOut(getattr(board, pin_name))
    except AttributeError:
        raise RuntimeError(f"Pin {pin_name} not available on this board")

def _init_bme280():
    spi = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
    cs = _make_pin("D5")
    try:
        sensor = adafruit_bme280.Adafruit_BME280_SPI(spi, cs)
    except (RuntimeError, ValueError) as exc:
        raise RuntimeError(f"BME280 not detected on SPI bus: {exc}")
    return sensor

def _init_epd():
    cs = _make_pin("D5")
    dc = _make_pin("D6")
    reset = _make_pin("D9")
    busy = _make_pin("D10")
    return IL0373(128, 296, spi=busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO),
                  cs=cs, dc=dc, reset=reset, busy=busy)

def _read_sensor(sensor):
    try:
        return sensor.temperature, sensor.humidity, sensor.pressure
    except (RuntimeError, ValueError) as exc:
        raise RuntimeError(f"Sensor read failed: {exc}")

def _format_text(temp, hum, pres):
    return f"Temp: {temp:.1f} C\nHum: {hum:.1f} %\nPres: {pres:.1f} hPa"

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = None
    display = None
    try:
        sensor = _init_bme280()
        display = _init_epd()
    except RuntimeError as exc:
        print(f"Initialization error: {exc}", file=sys.stderr)
        sys.exit(1)

    while _running:
        try:
            temp, hum, pres = _read_sensor(sensor)
            text = _format_text(temp, hum, pres)
            display.fill(WHITE)
            display.text(text, 0, 0, BLACK)
            display.display()
        except RuntimeError as exc:
            print(f"Sensor/display error: {exc}", file=sys.stderr)
        except Exception as exc:
            print(f"Unexpected display error: {exc}", file=sys.stderr)

        for _ in range(60):
            if not _running:
                break
            time.sleep(1)

if __name__ == "__main__":
    main()

