import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys
import time

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def find_serial_port():
    available = [p.device for p in serial.tools.list_ports.comports()]
    candidates = ['/dev/ttyACM0', '/dev/ttyUSB0']
    for port in candidates:
        if port in available:
            return port
    return None

def main():
    global running

    camera = None
    ser = None

    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise IOError("Cannot open USB webcam at index 0")

        ser_port = find_serial_port()
        if ser_port:
            try:
                ser = serial.Serial(ser_port, 9600, timeout=1)
                time.sleep(2)
                print(f"Serial port {ser_port} opened at 9600 baud.")
            except serial.SerialException as e:
                print(f"Warning: could not open serial port {ser_port}: {e}")
                ser = None
        else:
            print("Warning: no serial ports found; continuing without serial output.")

        min_hsv = np.array([0, 0, 0])
        max_hsv = np.array([255, 255, 255])
        is_tracking = False

        while running:
            ret, frame = camera.read()
            if not ret:
                print("Error: failed to read frame from camera.")
                break

            h_frame, w_frame, _ = frame.shape
            cx, cy = w_frame // 2, h_frame // 2
            roi = frame[cy - 5: cy + 5, cx - 5: cx + 5]

            hsv_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
            h_val = hsv_frame[:, :, 0]
            s_val = hsv_frame[:, :, 1]
            v_val = hsv_frame[:, :, 2]

            if is_tracking:
                mask = cv2.inRange(hsv_frame, min_hsv, max_hsv)
                contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

                for contour in contours:
                    area = cv2.contourArea(contour)
                    if area > 500:
                        x, y, b_w, b_h = cv2.boundingRect(contour)
                        cv2.rectangle(frame, (x, y), (x + b_w, y + b_h), (255, 0, 0), 2)

                        ball_x = x + b_w // 2
                        ball_y = y + b_h // 2

                        if ball_x > cx + 50 and ball_y > cy + 50:
                            position = '1'
                        elif ball_x > cx + 50 and ball_y < cy - 50:
                            position = '2'
                        elif ball_x < cx - 50 and ball_y > cy + 50:
                            position = '3'
                        elif ball_x < cx - 50 and ball_y < cy - 50:
                            position = '4'
                        else:
                            position = '5'

                        if ser:
                            try:
                                ser.write(position.encode('utf-8'))
                            except serial.SerialException as e:
                                print(f"Warning: failed to write to serial port: {e}")

            cv2.imshow("Frame", frame)
            cv2.imshow("ROI", roi)

            key = cv2.waitKey(1) & 0xFF
            if key == ord('s'):
                min_hsv = np.array([np.min(h_val), np.min(s_val), np.min(v_val)])
                max_hsv = np.array([np.max(h_val), np.max(s_val), np.max(v_val)])
                is_tracking = True
                print("Tracking enabled.")
            elif key == ord('o'):
                is_tracking = False
                print("Tracking disabled.")
            elif key == 27:
                running = False

    except IOError as e:
        print(f"IO Error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if camera is not None:
            camera.release()
        if ser is not None and ser.is_open:
            ser.close()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

