import time
import logging
import signal
import sys
import cv2
import numpy as np
import RPi.GPIO as GPIO
from functools import partial
from typing import Tuple, Optional

try:
    import serial
    from serial import SerialException
except ImportError:
    serial = None
    SerialException = Exception

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

BOARD = GPIO.BOARD


class ServoController:
    """Controls a single SG90 servo via PWM on a Raspberry Pi."""

    def __init__(self, pin: int, freq: int = 50, initial_duty: float = 7.0):
        self.pin = pin
        self.freq = freq
        self.initial_duty = initial_duty
        self.pwm = None
        self._setup_gpio()

    def _setup_gpio(self):
        GPIO.setmode(BOARD)
        GPIO.setup(self.pin, GPIO.OUT)
        self.pwm = GPIO.PWM(self.pin, self.freq)
        self.pwm.start(self.initial_duty)
        logger.info(f"Servo on pin {self.pin} initialized at {self.initial_duty}% duty.")

    def set_duty_cycle(self, duty_cycle: float):
        if self.pwm is None:
            raise RuntimeError("Servo not initialized.")
        self.pwm.ChangeDutyCycle(duty_cycle)
        logger.debug(f"Duty cycle set to {duty_cycle}% on pin {self.pin}.")

    def stop(self):
        if self.pwm is not None:
            self.pwm.stop()
            self.pwm = None
        GPIO.cleanup(self.pin)
        logger.info(f"Servo on pin {self.pin} stopped and GPIO cleaned.")


class ArduinoCommands:
    """Sends commands to an Arduino via serial communication."""

    def __init__(self, port: str = '/dev/ttyACM0', baudrate: int = 115200):
        self.port = port
        self.baudrate = baudrate
        self.arduino = None
        self._connect()

    def _connect(self):
        if serial is None:
            logger.error("pyserial not installed; cannot connect to Arduino.")
            return
        try:
            self.arduino = serial.Serial(self.port, self.baudrate, timeout=1)
            time.sleep(2)
            logger.info(f"Connected to Arduino on {self.port}.")
        except SerialException as e:
            logger.error(f"Failed to connect to Arduino on {self.port}: {e}")
            self.arduino = None

    def send(self, command: str):
        if self.arduino is None:
            logger.warning(f"Arduino not connected; skipping command: {command}")
            return
        try:
            self.arduino.write(command.encode('utf-8'))
            logger.debug(f"Sent command: {command}")
        except SerialException as e:
            logger.error(f"Failed to send command {command}: {e}")

    def close(self):
        if self.arduino is not None:
            try:
                self.arduino.close()
            except SerialException:
                pass
            self.arduino = None
            logger.info("Arduino connection closed.")


class ObjectTracker:
    """Tracks a red object using the CSI camera and controls servos via Arduino."""

    def __init__(self, arduino_port: str = '/dev/ttyACM0', arduino_baudrate: int = 115200,
                 servo_azimuth_pin: int = 7, servo_elevation_pin: int = 13,
                 servo_freq: int = 50, servo_initial_duty: float = 7.0):
        self.arduino_cmds = ArduinoCommands(arduino_port, arduino_baudrate)
        self.servo_azimuth = ServoController(servo_azimuth_pin, servo_freq, servo_initial_duty)
        self.servo_elevation = ServoController(servo_elevation_pin, servo_freq, servo_initial_duty)
        self.camera = cv2.VideoCapture(0)
        if not self.camera.isOpened():
            raise RuntimeError("Failed to open CSI camera.")
        self.is_tracking = False
        self.tracking_speed = 16
        self.tracking_time = 0
        self.servo_elevation_angle = servo_initial_duty
        self.servo_elevation_increment = 0.1
        self.servo_elevation_max = 12.0
        self.servo_elevation_min = servo_initial_duty

    def segment_color(self, frame: np.ndarray) -> Tuple[Optional[np.ndarray], Optional[Tuple[int, int, int, int]]]:
