import os
import time
import signal
import random
import logging
import threading
import wave
import struct
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

try:
    import smbus
    import RPi.GPIO as GPIO
    from picamera import Picamera
    from picamera.encoders import MJPEGEncoder
    from picamera.outputs import FileOutput
    try:
        from gpiozero import OutputDevice
        _GPIOZERO_AVAILABLE = True
    except ImportError:
        _GPIOZERO_AVAILABLE = False
except ImportError as e:
    logging.error(f"Missing required library: {e}")
    sys.exit(1)

DHT_PIN = 4
LIGHT_RELAY_PIN = 17
AUDIO_CHUNK_SIZE = 1024
AUDIO_FORMAT = None
AUDIO_CHANNELS = 1
AUDIO_RATE = 16000
GREENHOUSE_TEMPERATURE = 64

_running = True
_gpio_available = False

try:
    import pyaudio
    AUDIO_CHUNK_SIZE = 1024
    AUDIO_FORMAT = pyaudio.paInt16
    AUDIO_CHANNELS = 1
    AUDIO_RATE = 16000
except ImportError:
    logging.warning("pyaudio not found, falling back to simulated audio.")
    AUDIO_FORMAT = None

try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHT_RELAY_PIN, GPIO.OUT, initial=GPIO.LOW)
    _gpio_available = True
except Exception as e:
    logging.warning(f"GPIO initialization failed: {e}. Using simulated GPIO.")
    _gpio_available = False

if _GPIOZERO_AVAILABLE:
    try:
        light_relay = OutputDevice(LIGHT_RELAY_PIN, active_high=True, initial_value=False)
    except Exception:
        light_relay = None
else:
    light_relay = None

def signal_handler(sig, frame):
    global _running
    logging.info("Termination signal received. Shutting down...")
    _running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def cleanup():
    global _gpio_available
    if _gpio_available:
        try:
            GPIO.output(LIGHT_RELAY_PIN, GPIO.LOW)
            GPIO.cleanup()
            logging.info("GPIO cleanup completed.")
        except Exception as e:
            logging.error(f"GPIO cleanup error: {e}")
    if light_relay is not None:
        try:
            light_relay.off()
            light_relay.close()
        except Exception:
            pass

def read_temperature():
    try:
        bus = smbus.SMBus(1)
        try:
            bus.write_byte(0x5C, 0xF4)
            time.sleep(0.1)
            data = bus.read_i2c_block_data(0x5C, 0xF5, 5)
            if len(data) != 5:
                raise IOError("Incomplete data from DHT11")
            humidity = ((data[1] << 16) + (data[2] << 8) + data[3]) / 10544.0
            temperature = ((data[1] << 16) + (data[2] << 8) + data[3]) / 10544.0 - 50000.0
            if humidity < 0 or temperature < 0:
                raise IOError("Invalid data from DHT11")
            return temperature
        except Exception as e:
            logging.error(f"DHT11 read error: {e}")
            return None
    except Exception as e:
        logging.error(f"SMBus error: {e}")
        return None

def simulate_temperature():
    return random.uniform(15, 35)

def record_audio(filename, duration=5):
    if AUDIO_FORMAT is None:
        logging.warning("Simulating audio recording.")
        return
    try:
        p = pyaudio.PyAudio()
        stream = p.open(format=AUDIO_FORMAT, channels=AUDIO_CHANNELS, rate=AUDIO_RATE, input=True, frames_per_buffer=AUDIO_CHUNK_SIZE)
        logging.info(f"Recording audio to {filename} for {duration} seconds...")
        frames = []
        for _ in range(int(AUDIO_RATE / AUDIO_CHUNK_SIZE * duration)):
            data = stream.read(AUDIO_CHUNK_SIZE, exception_on_overflow=False)
            frames.append(data)
        stream.stop_stream()
        stream.close()
        p.terminate()
        logging.info("Audio recording complete.")
        wf = wave.open(filename, 'wb')
        wf.setnchannels(AUDIO_CHANNELS)
        wf.setsampwidth(pyaudio.PyAudio().get_sample_size(AUDIO_FORMAT))
        wf.setframerate(AUDIO_RATE)
        wf.writeframes(b''.join(frames))
        wf.close()
    except Exception as e:
        logging.error(f"Error recording audio: {e}")

def process_audio(filename):
    try:
        with wave.open(filename, 'rb') as wf:
            n_frames = wf.getnframes()
            sampwidth = wf.getsampwidth()
            data = wf.readframes(n_frames)
        if not data:
            logging.error("No audio data in file.")
            return None
        audio = struct.unpack(f"<{n_frames}h", data)
        energy = sum(abs(sample) for sample in audio)
        if energy < 1000:
            logging.warning("No voice detected in audio.")
            return None
        logging.info(f"Voice detected with energy: {energy}")
        return "Greenhouse"
    except Exception as e:
        logging.error(f"Error processing audio: {e}")
        return None

def control_lights(command):
    try:
        if "turn on the lights" in command:
            logging.info("Turning on lights.")
            if _gpio_available:
                GPIO.output(LIGHT_RELAY_PIN, GPIO.HIGH)
            if light_relay is not None:
                light_relay.on()
        elif "turn off the lights" in command:
            logging.info("Turning off lights.")
            if _gpio_available:
                GPIO.output(LIGHT_RELAY_PIN, GPIO.LOW)
            if light_relay is not None:
                light_relay.off()
    except Exception as e:
        logging.error(f"Error controlling lights: {e}")

def get_temperature(command, temperature):
    if "what is the temperature" in command:
        if temperature is not None:
            logging.info(f"Temperature: {temperature:.2f}°C")
        else:
            logging.warning("Temperature reading failed.")

def take_picture(command, camera):
    if "take a picture" in command:
        timestamp = int(time.time() * 1000)
        filename = f"greenhouse_{timestamp}.jpg"
        logging.info(f"Taking picture: {filename}")
        if camera is not None:
            try:
                camera.capture(filename)
                logging.info(f"Picture saved: {filename}")
            except Exception as e:
                logging.error(f"Error taking picture: {e}")
        else:
            logging.warning("Camera not available.")

def main():
    global _running
    camera = None
    try:
        camera = Picamera()
        camera.start()
        logging.info("Camera initialized.")
    except Exception as e:
        logging.warning(f"Camera initialization failed: {e}")
    temperature = read_temperature()
    if temperature is None:
        temperature = simulate_temperature()
        logging.warning("Using simulated temperature.")
    try:
        while _running:
            logging.info("Listening for wake word...")
            record_audio("audio.wav", duration=5)
            command = process_audio("audio.wav")
            if command:
                logging.info(f"Command received: {command}")
                control_lights(command)
                get_temperature(command, temperature)
                take_picture(command, camera)
            time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if camera is not None:
            try:
                camera.stop()
                logging.info("Camera stopped.")
            except Exception as e:
                logging.error(f"Error stopping camera: {e}")
        cleanup()

if __name__ == "__main__":
    main()

