#!/usr/bin/env python3
"""
Vibration monitoring system for Raspberry Pi.

Monitors three vibration sensors on GPIO pins, logs states to a CSV file,
and captures images from a CSI camera every picture_interval seconds.

Usage:
    python vibration_monitor.py -g 17,27,22 -l vibration_log.csv -i 0.5 -c 10 -p 5
"""

import argparse
import csv
import datetime
import os
import signal
import sys
import time

import RPi.GPIO as GPIO

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None


# ---------------------------------------------------------------------------
# Globals for clean shutdown
# ---------------------------------------------------------------------------
_running = True
_camera = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def parse_arguments():
    parser = argparse.ArgumentParser(
        description="Vibration monitoring system for Raspberry Pi."
    )
    parser.add_argument(
        "-g", "--gpio", required=True,
        help="Comma-separated list of GPIO pins (BCM numbering)."
    )
    parser.add_argument(
        "-l", "--log_file", required=True,
        help="Path to the CSV log file."
    )
    parser.add_argument(
        "-i", "--interval", type=float, required=True,
        help="Sampling interval in seconds."
    )
    parser.add_argument(
        "-c", "--calibrate", type=int, required=True,
        help="Calibration duration in seconds."
    )
    parser.add_argument(
        "-p", "--picture_interval", type=int, required=True,
        help="Picture interval in seconds."
    )
    return parser.parse_args()


def setup_gpio(sensor_pins):
    """Configure GPIO pins as inputs with pull-down resistors."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in sensor_pins:
        try:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        except Exception as exc:
            print(f"ERROR: Failed to configure GPIO {pin}: {exc}", file=sys.stderr)
            raise


def calibrate_sensors(sensor_pins, duration):
    """
    Sample each sensor for `duration` seconds and return a list of
    baseline percentages (HIGH readings / total samples).
    """
    print(f"Calibrating sensors for {duration} seconds...")
    readings = [0, 0, 0]
    total = 0
    start = time.time()
    while time.time() - start < duration and _running:
        for idx, pin in enumerate(sensor_pins):
            try:
                if GPIO.input(pin) == GPIO.HIGH:
                    readings[idx] += 1
            except Exception as exc:
                print(f"ERROR: GPIO read failed on pin {pin}: {exc}", file=sys.stderr)
                raise
        total += 1
        time.sleep(0.01)

    if total == 0:
        raise RuntimeError("Calibration produced zero samples.")

    baselines = [r / total * 100.0 for r in readings]
    thresholds = [b + 20.0 for b in baselines]
    print(f"Calibration complete. Baselines: {baselines:.2f}%, Thresholds: {thresholds:.2f}%")
    return thresholds


def log_data(log_file, timestamp, states):
    """Append a CSV row to the log file; fall back to console on I/O error."""
    try:
        with open(log_file, "a", newline="") as fh:
            writer = csv.writer(fh)
            writer.writerow([timestamp, *states])
            fh.flush()
    except OSError as exc:
        print(f"WARNING: Failed to write CSV row: {exc}", file=sys.stderr)


def capture_image(camera, timestamp):
    """Capture a JPEG image and save it in the 'images' subdirectory."""
    if camera is None:
        return
    try:
        os.makedirs("images", exist_ok=True)
        filename = os.path.join(
            "images",
            f"{timestamp.strftime('%Y-%m-%d_%H-%M-%S')}.jpg"
        )
        camera.capture_file(filename)
        print(f"Image saved: {filename}")
    except Exception as exc:
        print(f"WARNING: Image capture failed: {exc}", file=sys.stderr)


def main():
    global _camera

    args = parse_arguments()

    try:
        sensor_pins = [int(p) for p in args.gpio.split(",")]
    except ValueError:
        print("ERROR: --gpio must be a comma-separated list of integers.", file=sys.stderr)
        sys.exit(1)

    if len(sensor_pins) != 3:
        print("ERROR: Exactly three GPIO pins are required.", file=sys.stderr)
        sys.exit(1)

    if args.interval <= 0 or args.calibrate <= 0 or args.picture_interval <= 0:
        print("ERROR: Intervals must be positive.", file=sys.stderr)
        sys.exit(1)

    # --- Camera -------------------------------------------------------------
    if Picamera2 is not None:
        try:
            _camera = Picamera2()
            _camera.configure(
                _camera.create_still_configuration(
                    main={"size": (640, 480)}
                )
            )
            _camera.start()
            print("Camera initialized.")
        except Exception as exc:
            print(f"WARNING: Camera init failed ({exc}); continuing without imaging.", file=sys.stderr)
            _camera = None
    else:
        print("WARNING: picamera2 not installed; continuing without imaging.", file=sys.stderr)
        _camera = None

    # --- GPIO ---------------------------------------------------------------
    try:
        setup_gpio(sensor_pins)
    except Exception:
        print("ERROR: GPIO setup failed.", file=sys.stderr)
        if _camera is not None:
            try:
                _camera.close()
            except Exception:
                pass
        sys.exit(1)

    # --- Calibration --------------------------------------------------------
    try:
        thresholds = calibrate_sensors(sensor_pins, args.calibrate)
    except Exception as exc:
        print(f"ERROR: Calibration failed: {exc}", file=sys.stderr)
        GPIO.cleanup()
        if _camera is not None:
            try:
                _camera.close()
            except Exception:
                pass
        sys.exit(1)

    # --- Main loop ----------------------------------------------------------
    print("Monitoring started. Press Ctrl+C to stop.")
    last_picture = 0.0
    try:
        while _running:
            now = time.time()
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")

            states = []
            for idx, pin in enumerate(sensor_pins):
                try:
                    count = 0
                    window_start = time.time()
                    while time.time() - window_start < args.interval and _running:
                        if GPIO.input(pin) == GPIO.HIGH:
                            count += 1
                        time.sleep(0.001)
                    pct = count / (args.interval / 0.001) * 100.0
                    states.append(1 if pct > thresholds[idx] else 0)
                except Exception as exc:
                    print(f"ERROR: GPIO read failed on pin {pin}: {exc}", file=sys.stderr)
                    states.append(0)

            log_data(args.log_file, timestamp, states)

            if now - last_picture >= args.picture_interval:
                capture_image(_camera, datetime.datetime.now())
                last_picture = now

    except KeyboardInterrupt:
        print("\nKeyboardInterrupt received. Shutting down...")
    finally:
        GPIO.cleanup()
        if _camera is not None:
            try:
                _camera.close()
            except Exception:
                pass
        print("GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    main()

