import cv2
import time
import logging
import signal
import sys
from contextlib import contextmanager

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

CAMERA_INDEX = 0
ROI_START_POINT = (10, 40)
ROI_END_POINT = (150, 280)
FRAME_RATE = 10
GPIO_PIN = 17
WINDOW_NAME = "Output Image"

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio(pin):
    if GPIO is None:
        logging.warning("RPi.GPIO not available; GPIO setup skipped.")
        return
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        GPIO.output(pin, GPIO.HIGH)
        logging.info(f"GPIO pin {pin} set HIGH.")
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        raise

def cleanup_gpio(pin):
    if GPIO is None:
        return
    try:
        GPIO.output(pin, GPIO.LOW)
        GPIO.cleanup(pin)
        logging.info(f"GPIO pin {pin} cleaned up.")
    except Exception as e:
        logging.error(f"GPIO cleanup failed: {e}")

@contextmanager
def camera_manager(camera_index=CAMERA_INDEX, frame_rate=FRAME_RATE):
    cap = cv2.VideoCapture(camera_index)
    if not cap.isOpened():
        raise IOError(f"Cannot open camera at index {camera_index}")
    cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
    cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
    cap.set(cv2.CAP_PROP_FPS, frame_rate)
    time.sleep(0.5)
    try:
        yield cap
    finally:
        cap.release()
        cv2.destroyAllWindows()

def process_frame(frame, start_point, end_point):
    if frame is None or frame.size == 0:
        raise IOError("Empty frame received from camera.")
    roi = frame[start_point[1]:end_point[1], start_point[0]:end_point[0]]
    return roi

def display_image(image, window_name=WINDOW_NAME):
    cv2.imshow(window_name, image)
    if cv2.waitKey(1) & 0xFF == 10:
        return False
    return True

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        setup_gpio(GPIO_PIN)
        with camera_manager() as cap:
            for i in range(32):
                if not _running:
                    break
                ret, frame = cap.read()
                if not ret:
                    logging.error(f"Failed to capture frame {i}.")
                    continue
                try:
                    processed_frame = process_frame(frame, ROI_START_POINT, ROI_END_POINT)
                    if not display_image(processed_frame):
                        break
                except Exception as e:
                    logging.error(f"Error processing frame {i}: {e}")
                    break
    except IOError as e:
        logging.error(f"Camera error: {e}")
    except Exception as e:
        logging.exception(f"Unexpected error: {e}")
    finally:
        cv2.destroyAllWindows()
        cleanup_gpio(GPIO_PIN)
        logging.info("Program finished.")

if __name__ == "__main__":
    main()

