import time
import datetime
import threading
import queue
import signal
import sys
import logging
import RPi.GPIO as GPIO

# Configure logging
logging.basicConfig(
    filename='motion_detection.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Define GPIO pins for PIR sensors (BCM numbering)
PIR_PINS = {
    "Front Door": 17,
    "Back Door": 27,
    "Living Room": 22
}

# Debounce and persistence time in seconds
DEBOUNCE_TIME = 0.5
PERSISTENCE_TIME = 0.1

# Shared queue for motion events
motion_queue = queue.Queue()

# Event to signal shutdown
shutdown_event = threading.Event()


def signal_handler(signum, frame):
    """Handle SIGINT and SIGTERM for graceful shutdown."""
    logging.info(f"Received signal {signum}, initiating shutdown...")
    shutdown_event.set()


def initialize_gpio():
    """Initialize GPIO mode and set pins as inputs with pull-down resistors."""
    try:
        GPIO.setmode(GPIO.BCM)
        for zone, pin in PIR_PINS.items():
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            logging.info(f"Initialized GPIO pin {pin} for {zone}")
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        raise


def read_pir_sensor(pin):
    """Read the state of a PIR sensor with debounce."""
    time.sleep(DEBOUNCE_TIME)
