import sys
import time
import signal
import cv2
import numpy as np

import config
import face
import hardware


class DoorBox:
    """Face-recognition door box controller."""

    def __init__(self):
        self.camera = None
        self.box = None
        self.model = None
        self._running = True

        try:
            self.box = hardware.Box()
            self.box.lock()
        except Exception as exc:
            print(f"Error initializing box: {exc}", file=sys.stderr)
            sys.exit(1)

        try:
            self.camera = cv2.VideoCapture(0)
            if not self.camera.isOpened():
                raise RuntimeError("Could not open camera")
            self.camera.set(cv2.CAP_PROP_FRAME_WIDTH, 64)
            self.camera.set(cv2.CAP_PROP_FRAME_HEIGHT, 48)
            self.camera.set(cv2.CAP_PROP_FORMAT, 1)  # XRGB8888
        except Exception as exc:
            print(f"Error initializing camera: {exc}", file=sys.stderr)
            self._cleanup()
            sys.exit(1)

        try:
            self.model = cv2.face.EigenFaceRecognizer_create()
            self.model.read(config.TRAINING_FILE)
        except Exception as exc:
            print(f"Error loading training data: {exc}", file=sys.stderr)
            self._cleanup()
            sys.exit(1)

    def _cleanup(self):
        """Release camera and ensure the box is locked."""
        if self.camera is not None and self.camera.isOpened():
            self.camera.release()
        if self.box is not None:
            try:
                self.box.lock()
            except Exception:
                pass

    def _signal_handler(self, signum, frame):
        """Handle SIGINT for graceful shutdown."""
        print("\nExiting...")
        self._running = False

    def run(self):
        """Main loop: capture, detect, recognize, unlock on match."""
        signal.signal(signal.SIGINT, self._signal_handler)

        try:
            while self._running:
                try:
                    if self.box.is_button_up():
                        if not self.box.is_locked:
                            self.box.lock()

                        ret, image = self.camera.read()
                        if not ret or image is None:
                            print("Error capturing image", file=sys.stderr)
                            time.sleep(0.1)
                            continue

                        gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
                        face_coords = face.detect_single(gray)

                        if face_coords is None:
                            print("Could not detect single face!")
                            time.sleep(0.1)
                            continue

                        x, y, w, h = face_coords
                        cropped = face.crop(gray, x, y, w, h)
                        resized = face.resize(cropped)

                        label, confidence = self.model.predict(resized)

                        print(
                            f"Predicted {'POSITIVE' if label == config.POSITIVE_LABEL else 'NEGATIVE'} "
                            f"face with confidence {confidence}"
                        )

                        if label == config.POSITIVE_LABEL and config.POSITIVE_THRESHOLD > confidence > 1500:
                            print("Recognized face! Unlocking box...")
                            self.box.unlock()
                        else:
                            print("Face not recognized.")

                except Exception as exc:
                    print(f"Error during processing: {exc}", file=sys.stderr)

                time.sleep(0.1)

        finally:
            self._cleanup()


if __name__ == "__main__":
    DoorBox().run()

