import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.", file=sys.stderr)
    sys.exit(1)

INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in INPUT_PINS + OUTPUT_PINS:
        try:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        except Exception as e:
            print(f"Error: Failed to configure input pin {pin}: {e}", file=sys.stderr)
            GPIO.cleanup()
            sys.exit(1)
    for pin in OUTPUT_PINS:
        try:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        except Exception as e:
            print(f"Error: Failed to configure output pin {pin}: {e}", file=sys.stderr)
            GPIO.cleanup()
            sys.exit(1)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    setup_gpio()
    output_states = {23: False, 24: False}
    try:
        while _running:
            try:
                if GPIO.input(4) == GPIO.LOW:
                    GPIO.output(23, GPIO.HIGH)
                elif GPIO.input(5) == GPIO.LOW:
                    GPIO.output(23, GPIO.LOW)
                elif GPIO.input(6) == GPIO.LOW:
                    output_states[24] = not output_states[24]
                    GPIO.output(24, 1 if output_states[24] else 0)
            except Exception as e:
                print(f"Warning: GPIO read/write error: {e}", file=sys.stderr)
            time.sleep(POLL_INTERVAL)
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

