import cv2
import pyzbar.pyzbar as pyzbar
import time
import datetime
import threading
import queue
import os
import signal
import configparser
import logging
import argparse
import json
import random
import io
import numpy as np

# Constants
CONFIG_FILE = "config.ini"
LOG_FILE = "inventory.log"
BACKUP_LOG_FILE = "backup_inventory.log"

# Global variables
config = None
motion_thresholds = {}
frame_buffers = {}
last_scan_times = {}
last_cloud_upload_time = 0
inventory_data = []
camera_ids = []
running = True

# Custom Exception Classes
class CameraInitializationError(Exception):
    pass

class QRCodeDecodingError(Exception):
    pass

class CloudUploadError(Exception):
    pass

# Configuration Management Functions
def load_configuration(config_file):
    config = configparser.ConfigParser()
    if not config.read(config_file):
        raise FileNotFoundError(f"Configuration file not found: {config_file}")
    return config

def get_config_value(config, section, key, fallback=None, value_type=None):
    try:
        if value_type == int:
            return config.getint(section, key, fallback=fallback)
        elif value_type == float:
            return config.getfloat(section, key, fallback=fallback)
        elif value_type == bool:
            return config.getboolean(section, key, fallback=fallback)
        else:
            return config.get(section, key, fallback=fallback)
    except (configparser.NoSectionError, configparser.NoOptionError):
        return fallback

# Camera Management Functions
def initialize_camera(camera_id):
    try:
        cap = cv2.VideoCapture(camera_id)
        if not cap.isOpened():
            raise CameraInitializationError(f"Could not open camera at device node {camera_id}")
        return cap
    except Exception as e:
        raise CameraInitializationError(f"Error initializing camera {camera_id}: {e}")

def release_camera(camera_id, camera):
    if camera is not None:
        camera.release()
    logging.info(f"Camera {camera_id} released.")

# Motion Detection and QR Code Decoding Functions
def detect_motion(frame1, frame2, motion_threshold):
    try:
        diff = cv2.absdiff(frame1, frame2)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        blur = cv2.GaussianBlur(gray, (5, 5), 0)
        _, thresh = cv2.threshold(blur, motion_threshold, 255, cv2.THRESH_BINARY)
        dilated = cv2.dilate(thresh, None, iterations=3)
        contours, _ = cv2.findContours(dilated, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)
        motion_detected = False
        for contour in contours:
            if cv2.contourArea(contour) > 500:
                motion_detected = True
                break
        return motion_detected
    except Exception as e:
        logging.error(f"Error detecting motion: {e}")
        return False

def decode_qr_code(frame):
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        decoded_objects = pyzbar.decode(gray)
        return decoded_objects
    except Exception as e:
        logging.error(f"Error decoding QR code: {e}")
        return []

# Data Logging and Management Functions
def log_data(camera_id, qr_code_data):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_message = f"{timestamp} - Camera {camera_id}: QR Code - {qr_code_data}"
    try:
        with open(LOG_FILE, "a") as f:
            f.write(log_message + "\n")
        logging.info(log_message)
    except IOError as e:
        logging.error(f"Error writing to log file: {e}")
        try:
            with open(BACKUP_LOG_FILE, "a") as f:
                f.write(log_message + "\n")
            logging.warning(f"Data written to backup log file: {BACKUP_LOG_FILE}")
        except IOError as e2:
            logging.error(f"Error writing to backup log file: {e2}")

def add_to_inventory(qr_code_data):
    global inventory_data
    inventory_data.append({"timestamp": datetime.datetime.now().isoformat(), "qr_code_data": qr_code_data})

def simulate_cloud_upload(data):
    try:
        json_data = json.dumps(data)
        response = random.choice([200, 400, 500])
        if response == 200:
            logging.info(f"Simulated Cloud Upload Successful: {json_data}")
        else:
            raise CloudUploadError(f"Simulated Cloud Upload Failed with status code {response}")
    except Exception as e:
        logging.error(f"Error simulating cloud upload: {e}")
        raise CloudUploadError(f"Error simulating cloud upload: {e}")

def upload_data_to_cloud():
    global last_cloud_upload_time, inventory_data
    try:
        current_time = time.time()
        if current_time - last_cloud_upload_time >= get_config_value(config, "DEFAULT", "cloud_upload_interval", fallback=60, value_type=float):
            if inventory_data:
                data_to_upload = inventory_data
                inventory_data = []
                simulate_cloud_upload(data_to_upload)
                last_cloud_upload_time = current_time
            else:
                logging.info("No new data to upload to the cloud.")
        else:
            logging.info("Cloud upload interval not reached.")
    except CloudUploadError as e:
        logging.error(f"Cloud upload failed: {e}")
    except Exception as e:
        logging.error(f"Error in cloud upload process: {e}")

# Camera Processing Thread Function
def process_camera_frames(camera_id, camera):
    global running, last_scan_times
    reinit_delay = get_config_value(config, "DEFAULT", "reinit_delay", fallback=5, value_type=float)
    redundancy_time_window = get_config_value(config, "DEFAULT", "redundancy_time_window", fallback=60, value_type=float)
    frame_buffer_size = get_config_value(config, "DEFAULT", "frame_buffer_size", fallback=10, value_type=int)
    motion_threshold = motion_thresholds.get(camera_id, 20)

    frame_buffer = []
    last_frame = None
    last_scan_time = time.time()

    while running:
        try:
            ret, frame = camera.read()
            if not ret:
                logging.error(f"Failed to grab frame from camera {camera_id}. Reinitializing...")
                release_camera(camera_id, camera)
                time.sleep(reinit_delay)
                camera = initialize_camera(camera_id)
                motion_threshold = motion_thresholds.get(camera_id, 20)
                continue

            frame_buffer.append(frame.copy())
            if len(frame_buffer) > frame_buffer_size:
                frame_buffer.pop(0)

            if len(frame_buffer) >= 2:
                if last_frame is not None:
                    motion_detected = detect_motion(frame_buffer[-2], frame_buffer[-1], motion_threshold)
                    if motion_detected:
                        decoded_objects = decode_qr_code(frame_buffer[-1])
                        for obj in decoded_objects:
                            try:
                                qr_code_data = obj.data.decode("utf-8")
                                current_time = time.time()
                                if qr_code_data not in last_scan_times or current_time - last_scan_times[qr_code_data] > redundancy_time_window:
                                    log_data(camera_id, qr_code_data)
                                    add_to_qr_code_data(qr_code_data)
                                    last_scan_times[qr_code_data] = current_time
                                    last_scan_time = current_time
                                else:
                                    logging.info(f"Duplicate QR code detected: {qr_code_data}. Skipping.")
                            except Exception as e:
                                logging.error(f"Error processing QR code data: {e}")
                else:
                    last_frame = frame_buffer[-1].copy()
                    continue

            last_frame = frame_buffer[-1].copy()
            time.sleep(0.1)

        except CameraInitializationError as e:
            logging.error(f"Camera initialization error: {e}")
            break
        except Exception as e:
            logging.error(f"Error processing camera frames: {e}")
            break

# Helper Functions
def add_to_qr_code_data(qr_code_data):
    global camera_ids
    for camera_id in camera_ids:
        if get_config_value(config, "CAMERAS", f"camera_{camera_id}_enabled", fallback=True, value_type=bool):
            log_data(camera_id, qr_code_data)
            add_to_inventory(qr_code_data)

def cleanup(signum=None, frame=None):
    global running, camera_ids
    running = False
    logging.info("Cleaning up resources...")
    for camera_id in camera_ids:
        if camera_id in frame_buffers:
            release_camera(camera_id, frame_buffers[camera_id].get('camera'))
    logging.info("Cleanup complete. Exiting.")
    os._exit(0)

def watchdog():
    global running, last_scan_times
    watchdog_timeout = get_config_value(config, "DEFAULT", "watchdog_timeout", fallback=30, value_type=int)
    while running:
        current_time = time.time()
        for qr_code_data, last_scan_time in last_scan_times.items():
            if current_time - last_scan_time > watchdog_timeout:
                logging.critical(f"Watchdog timeout! No QR code detected for {watchdog_timeout} seconds. Restarting program.")
                cleanup()
                os.execv(sys.executable, [sys.executable] + sys.argv)
        time.sleep(1)

# Main Function
def main():
    global config, motion_thresholds, frame_buffers, last_scan_times, camera_ids, running

    parser = argparse.ArgumentParser(description="QR Code Scanner and Inventory Management System")
    parser.add_argument("--config", default=CONFIG_FILE, help="Path to the configuration file")
    args = parser.parse_args()

    try:
        config = load_configuration(args.config)
    except FileNotFoundError as e:
        print(f"Error: {e}")
        return

    logging.basicConfig(filename=LOG_FILE, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')

    try:
        motion_thresholds = {int(k.replace("motion_threshold_camera_", "")): int(v) for k, v in config.items("MOTION_THRESHOLD")}
        camera_ids = [int(k.replace("camera_", "").replace("_enabled", "")) for k, v in config.items("CAMERAS") if k.endswith("_enabled") and v == "True"]
    except (configparser.NoSectionError, configparser.NoOptionError) as e:
        print(f"Error: Missing configuration section or option: {e}")
        return

    for camera_id in camera_ids:
        try:
            camera = initialize_camera(camera_id)
            frame_buffers[camera_id] = {'camera': camera, 'frame_buffer': []}
            last_scan_times[camera_id] = time.time()
        except CameraInitializationError as e:
            logging.error(f"Error initializing camera {camera_id}: {e}")
            print(f"Error initializing camera {camera_id}: {e}")
            continue

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    threads = []
    for camera_id in camera_ids:
        thread = threading.Thread(target=process_camera_frames, args=(camera_id, frame_buffers[camera_id]['camera']))
        threads.append(thread)
        thread.start()

    watchdog_thread = threading.Thread(target=watchdog)
    watchdog_thread.daemon = True
    watchdog_thread.start()

    try:
        while running:
            upload_data_to_cloud()
            time.sleep(1)
    except KeyboardInterrupt:
        cleanup()

if __name__ == "__main__":
    main()

