import time
import signal
import logging
from datetime import datetime

try:
    from gpiozero import LED
    from picamera2 import Picamera2
except ImportError as exc:
    print(f"Missing required library: {exc}", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("countdown_capture")

LED_PIN = 17
COUNTDOWN_SECONDS = 2
IMAGE_DIR = "static/images"

_running = True

def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received, shutting down...", signum)
    _running = False

def setup_camera():
    try:
        cam = Picamera2()
        cam.configure("still")
        cam.start()
        log.info("Camera initialized successfully.")
        return cam
    except Exception as exc:
        log.error("Camera initialization failed: %s", exc)
        return None

def setup_led():
    try:
        led = LED(LED_PIN)
        log.info("LED on GPIO %d initialized.", LED_PIN)
        return led
    except Exception as exc:
        log.error("LED initialization failed: %s", exc)
        return None

def ensure_image_dir():
    try:
        os.makedirs(IMAGE_DIR, exist_ok=True)
        log.info("Image directory ready: %s", IMAGE_DIR)
    except OSError as exc:
        log.error("Cannot create image directory %s: %s", IMAGE_DIR, exc)
        return False
    return True

def blink_led(led, count=5, on_time=0.2, off_time=0.2):
    for _ in range(count):
        if not _running:
            return False
        led.on()
        time.sleep(on_time)
        led.off()
        time.sleep(off_time)
    return True

def countdown(seconds):
    for remaining in range(seconds, 0, -1):
        if not _running:
            return False
        log.info("Capturing image in %d seconds...", remaining)
        time.sleep(1)
    return True

def capture_image(cam, led):
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    image_path = os.path.join(IMAGE_DIR, f"{timestamp}.jpg")
    try:
        led.on()
        cam.capture_file(image_path)
        led.off()
        log.info("Image saved to %s", image_path)
        return True
    except Exception as exc:
        log.error("Image capture failed: %s", exc)
        led.off()
        return False

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    cam = setup_camera()
    if cam is None:
        sys.exit(1)

    led = setup_led()
    if led is None:
        cam.close()
        sys.exit(1)

    if not ensure_image_dir():
        cam.close()
        sys.exit(1)

    try:
        if not blink_led(led, count=5, on_time=0.2, off_time=0.2):
            log.error("Interrupted before countdown.")
            return

        if not countdown(COUNTDOWN_SECONDS):
            log.error("Countdown interrupted.")
            return

        if not capture_image(cam, led):
            if not blink_led(led, count=5, on_time=0.2, off_time=0.2):
                log.error("Failed to blink LED during capture error.")
            return

        log.info("Capture complete.")
    except Exception as exc:
        log.error("Unexpected error: %s", exc)
        try:
            blink_led(led, count=5, on_time=0.2, off_time=0.2)
        except Exception:
            pass
    finally:
        try:
            cam.close()
            log.info("Camera closed.")
        except Exception:
            pass
        try:
            led.close()
            log.info("LED released.")
        except Exception:
            pass

if __name__ == "__main__":
    main()

