import logging
import configparser
from datetime import datetime

import numpy as np
from PIL import Image

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Shutdown signal received.")

def load_config(config_file):
    config = configparser.ConfigParser()
    if not config.read(config_file):
        raise FileNotFoundError(f"Configuration file not found: {config_file}")
    return config

def get_roi(config):
    try:
        roi_x1 = config.getint('ROI', 'roi_x1')
        roi_y1 = config.getint('ROI', 'roi_y1')
        roi_x2 = config.getint('ROI', 'roi_x2')
        roi_y2 = config.getint('ROI', 'roi_y2')
        if not (0 <= roi_x1 < roi_x2 and 0 <= roi_y1 < roi_y2):
            raise ValueError("Invalid ROI coordinates.")
        return roi_x1, roi_y1, roi_x2, roi_y2
    except (configparser.Error, ValueError) as e:
        logging.error(f"Error loading ROI: {e}")
        raise

def get_motion_threshold(config):
    try:
        return config.getint('Motion', 'motion_threshold')
    except (configparser.Error, ValueError) as e:
        logging.error(f"Error loading motion threshold: {e}")
        raise

def get_snapshot_dir(config):
    try:
        return config.get('Snapshot', 'snapshot_dir')
    except (configparser.Error, ValueError) as e:
        logging.error(f"Error loading snapshot directory: {e}")
        raise

def get_confirmation_delay(config):
    try:
        return config.getint('Confirmation', 'confirmation_delay')
    except (configparser.Error, ValueError) as e:
        logging.error(f"Error loading confirmation delay: {e}")
        raise

def get_temperature_threshold(config):
    try:
        return config.getint('Temperature', 'temperature_threshold')
    except (configparser.Error, ValueError) as e:
        logging.error(f"Error loading temperature threshold: {e}")
        raise

def get_simulated_temperature(config):
    try:
        return config.getboolean('Temperature', 'simulated_temperature')
    except (configparser.Error, ValueError) as e:
        logging.error(f"Error loading simulated temperature flag: {e}")
        raise

def capture_frame(picam2):
    try:
        return picam2.capture_array()
    except Exception as e:
        logging.error(f"Error capturing frame: {e}")
        return None

def detect_motion(frame1, frame2, roi, motion_threshold):
    try:
        roi1 = frame1[roi[1]:roi[3], roi[0]:roi[2]]
        roi2 = frame2[roi[1]:roi[3], roi[0]:roi[2]]
        diff = np.abs(roi1.astype(np.int16) - roi2.astype(np.int16))
        changed_pixels = np.sum(np.any(diff > motion_threshold, axis=2))
        total_pixels = roi1.shape[0] * roi1.shape[1]
