import sys
import os
import time
import signal
import threading
import queue
import logging

import cv2
import numpy as np
import sounddevice as sd

import config
import face

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)


class GracefulKiller:
    def __init__(self):
        self.kill_now = False
        signal.signal(signal.SIGINT, self._exit_gracefully)
        signal.signal(signal.SIGTERM, self._exit_gracefully)

    def _exit_gracefully(self, signum, frame):
        logger.info('Signal %s received, shutting down...', signum)
        self.kill_now = True


class SoundPlayer:
    def __init__(self, channel=0):
        self.channel = channel
        self._lock = threading.Lock()
        self._queue = queue.Queue()
        self._thread = None
        self._stop_event = threading.Event()
        self._stop_event.set()

    def play(self, sound_path):
        if not os.path.isfile(sound_path):
            logger.error('Sound file not found: %s', sound_path)
            return
        self._queue.put(sound_path)
        if self._stop_event.is_set():
            self._stop_event.clear()
            self._thread = threading.Thread(target=self._worker, daemon=True)
            self._thread.start()

    def _worker(self):
        try:
            while not self._stop_event.is_set():
                try:
                    sound_path = self._queue.get(timeout=0.1)
                except queue.Empty:
                    continue
                try:
                    data = np.fromfile(sound_path, dtype=np.int16)
                    if data.size == 0:
                        logger.error('Empty sound file: %s', sound_path)
                        continue
                    if data.ndim == 1:
                        data = data.reshape(-1, 1)
                    sd.play(data, config.AUDIO_FREQUENCY, blocking=False)
                    self._stop_event.wait(timeout=0.5)
                except Exception as e:
                    logger.error('Error playing sound %s: %s', sound_path, e)
        except Exception as e:
            logger.error('Sound player error: %s', e)
        finally:
            self._stop_event.set()

    def stop(self):
        self._stop_event.set()
        if self._thread and self._thread.is_alive():
            self._thread.join(timeout=2.0)


class DoorController:
    def __init__(self, lock_pin=17, button_pin=5):
        self.lock_pin = lock_pin
        self.button_pin = button_pin
        self.lock_state = True
        self.lock_timeout = 10.0
        self.last_lock_time = 0.0
        self.lock_thread = None
        self.lock_event = threading.Event()
        self.lock_event.set()
        self._lock = threading.Lock()

    def set_lock(self, state):
        with self._lock:
            if state != self.lock_state:
                self.lock_state = state
                logger.info('Door %s', 'locked' if state else 'unlocked')

    def is_locked(self):
        with self._lock:
            return self.lock_state

    def lock_door(self):
        self.set_lock(True)
        self.last_lock_time = time.time()
        if self.lock_event.is_set():
            self.lock_event.clear()
            self.lock_thread = threading.Thread(target=self._lock_worker, daemon=True)
            self.lock_thread.start()

    def _lock_worker(self):
        try:
            while not self.lock_event.is_set():
                self.lock_event.wait(timeout=1.0)
                with self._lock:
                    if self.lock_state and (time.time() - self.last_lock_time) > self.lock_timeout:
                        logger.warning('Door auto-lock timeout reached')
                        self.set_lock(False)
                        break
        except Exception as e:
            logger.error('Lock worker error: %s', e)
        finally:
            self.lock_event.set()

    def unlock_door(self):
        self.set_lock(False)
        self.lock_event.set()
        if self.lock_thread and self.lock_thread.is_alive():
            self.lock_thread.join(timeout=2.0)


class FaceRecognizer:
    def __init__(self, camera_getter, sound_player, door_controller):
        self.camera_getter = camera_getter
        self.sound_player = sound_player
        self.door_controller = door_controller
        self.model = None
        self._lock = threading.Lock()
        self._running = True
        self._thread = None

    def load_model(self):
        if not os.path.isfile(config.TRAINING_FILE):
            logger.error('Training file not found: %s', config.TRAINING_FILE)
            return False
        try:
            self.model = face.Face()
            self.model.load_cascade(config.CASCADE_FILE)
            self.model.load_recognizer(config.TRAINING_FILE)
            logger.info('Model loaded from %s', config.TRAINING_FILE)
            return True
        except Exception as e:
            logger.error('Error loading model: %s', e)
            self.model = None
            return False

    def recognize(self):
        if not self.model:
            logger.error('Model not loaded')
            return
        with self._lock:
            if not self._running:
                return
        try:
            image = self.camera_getter()
            if image is None:
                logger.warning('Camera read failed')
                return
            gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
            face_coords = self.model.detect_single(gray)
            if face_coords is None:
                logger.info('No face detected')
                self.sound_player.play(config.SOUND_NO_FACE)
                return
            x, y, w, h = face_coords
            cropped = face.crop(gray, x, y, w, h)
            resized = face.resize(cropped)
            label, confidence = self.model.predict(resized)
            logger.info('Predicted label: %s, Confidence: %.2f', label, confidence)
            if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                logger.info('Recognized face')
                self.sound_player.play(config.SOUND_WELCOME)
                self.door_controller.unlock_door()
            else:
                logger.info('Face not recognized')
                self.sound_player.play(config.SOUND_NOT_RECOGNIZED)
                self.sound_player.play(config.SOUND_WAIT)
        except Exception as e:
            logger.error('Error during recognition: %s', e)

    def start(self):
        if self._thread and self._thread.is_alive():
            return
        self._running = True
        self._thread = threading.Thread(target=self._worker, daemon=True)
        self._thread.start()

    def stop(self):
        self._running = False
        if self._thread and self._thread.is_alive():
            self._thread.join(timeout=2.0)

    def _worker(self):
        while self._running:
            self.recognize()
            time.sleep(0.1)


def main():
    killer = GracefulKiller()

    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(config.BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(config.LOCK_PIN, GPIO.OUT)
        GPIO.output(config.LOCK_PIN, GPIO.HIGH)
    except Exception as e:
        logger.error('GPIO setup failed: %s', e)
        sys.exit(1)

    def camera_getter():
        try:
            ret, frame = config.CAMERA.read()
            if not ret or frame is None:
                logger.warning('Camera read returned no frame')
                return None
            return frame
        except Exception as e:
            logger.error('Camera read error: %s', e)
            return None

    sound_player = SoundPlayer(channel=0)
    door_controller = DoorController(lock_pin=config.LOCK_PIN, button_pin=config.BUTTON_PIN)
    recognizer = FaceRecognizer(camera_getter, sound_player, door_controller)

    if not recognizer.load_model():
        logger.error('Failed to load model, exiting')
        GPIO.cleanup()
        sys.exit(1)

    recognizer.start()

    try:
        while not killer.kill_now:
            try:
                cmd = sys.stdin.readline()
                if cmd.strip().lower() == 'l':
                    door_controller.lock_door()
            except KeyboardInterrupt:
                break
            except Exception:
                pass
            time.sleep(0.1)
    finally:
        logger.info('Shutting down...')
        recognizer.stop()
        sound_player.stop()
        try:
            config.CAMERA.release()
        except Exception:
            pass
        GPIO.cleanup()
        sd.quit()
        logger.info('Cleanup complete')


if __name__ == '__main__':
    main()

