import sys
import time

class FaceDetector:
    """
    Real-time face detection on Raspberry Pi using OpenCV with robust error handling
    and clean resource release on all exit paths.
    """

    def __init__(self, camera_index=0, cascade_path="haarcascade_frontalface_default.xml"):
        self.camera_index = camera_index
        self.cascade_path = cascade_path
        self.cap = None
        self.face_cascade = None
