import io
import logging
import signal
import threading
import time
from typing import Callable, Optional

from general import ws
from general.camera import CameraJpegStream

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Thread-safe buffer for capturing and streaming JPEG frames over WebSockets."""

    def __init__(self, camera_stream: CameraJpegStream,
                 ws_handler: ws.AbstractWebSocketHandler,
                 decode_frame: Callable[[io.BytesIO], object]) -> None:
        if not isinstance(camera_stream, CameraJpegStream):
            raise TypeError("camera_stream must be a CameraJpegStream instance")
        if not isinstance(ws_handler, ws.AbstractWebSocketHandler):
            raise TypeError("ws_handler must be an AbstractWebSocketHandler instance")
        if not callable(decode_frame):
            raise TypeError("decode_frame must be callable")

        self.camera_stream = camera_stream
        self.ws_handler = ws_handler
        self.decode_frame = decode_frame
        self.buffer = io.BytesIO()
        self.lock = threading.Lock()
        self._running = True

    def start(self) -> None:
        """Starts the camera capture loop in a background thread."""
        threading.Thread(target=self._capture_loop, daemon=True).start()

    def stop(self) -> None:
        """Signals the capture loop to stop and flushes any remaining buffered data."""
        self._running = False
        with self.lock:
            remaining = self.buffer.getvalue()
            if remaining:
                self._process_frame(remaining)
            self.buffer.close()
            self.buffer = io.BytesIO()

    def _capture_loop(self) -> None:
        """Continuously captures JPEG frames and broadcasts them over WebSockets."""
        while self._running:
            try:
                data = self.camera_stream.read(1024)
                if not data:
                    continue

                with self.lock:
                    self.buffer.write(data)
                    frame_data = self.buffer.getvalue()

                if frame_data:
                    self._process_frame(frame_data)

            except Exception as e:
                logger.error(f"Error in capture loop: {e}", exc_info=True)
                time.sleep(0.1)

    def _process_frame(self, frame_data: bytes) -> None:
        """Processes a frame of data, detecting JPEG boundaries and broadcasting frames."""
        try:
            if frame_data.startswith(b'\xff\xd8'):
                # New JPEG frame detected; flush the buffer and broadcast
                with self.lock:
                    self.buffer.seek(0)
                    frame_bytes = self.buffer.read()
                    self.buffer.seek(0)
                    self.buffer.truncate(0)

                if frame_bytes:
                    try:
                        frame = self.decode_frame(io.BytesIO(frame_bytes))
                        if frame is not None:
                            if self.ws_handler.has_connections():
                                self.ws_handler.broadcast(frame)
                    except Exception as e:
                        logger.error(f"Error decoding/broadcasting frame: {e}", exc_info=True)
        except Exception as e:
            logger.error(f"Error processing frame data: {e}", exc_info=True)


class MotionDetectionBuffer:
    """Thread-safe buffer for motion detection, storing previous and current frames."""

    def __init__(self, camera_stream: CameraJpegStream,
                 detect_motion: Callable[[object, object], None]) -> None:
        if not isinstance(camera_stream, CameraJpegStream):
