                if not data:
                    continue

                with self.lock:
                    self.buffer.write(data)
                    frame_data = self.buffer.getvalue()

                if frame_data:
                    self._process_frame(frame_data)

            except Exception as e:
                logger.error(f"Error in motion detection loop: {e}", exc_info=True)
                time.sleep(0.1)

    def _process_frame(self, frame_data: bytes) -> None:
        """Processes a frame of data, detecting JPEG boundaries and performing motion detection."""
        try:
            if frame_data.startswith(b'\xff\xd8'):
                with self.lock:
                    self.buffer.seek(0)
                    frame_bytes = self.buffer.read()
                    self.buffer.seek(0)
                    self.buffer.truncate(0)

                if frame_bytes:
                    try:
                        frame = self.camera_stream.decode_frame(io.BytesIO(frame_bytes))
                        if frame is not None:
                            self.prev_frame = self.curr_frame
                            self.curr_frame = frame
                            if self.prev_frame is not None:
                                self.detect_motion(self.prev_frame, self.curr_frame)
                    except Exception as e:
                        logger.error(f"Error decoding frame for motion detection: {e}", exc_info=True)
        except Exception as e:
            logger.error(f"Error processing motion frame data: {e}", exc_info=True)


def main() -> None:
    """Initializes and runs the camera stream and motion detection buffers."""
    try:
        from general.camera import CameraJpegStream  # Import locally to avoid circular dependency
        from general import ws
    except ImportError as e:
        logger.error(f"Failed to import required modules: {e}")
        return

    try:
        camera_stream = CameraJpegStream()
        ws_handler = ws.AbstractWebSocketHandler()

        def dummy_decode_frame(stream: io.BytesIO) -> Optional[object]:
            try:
                stream.seek(0)
                return stream.read()
            except Exception as e:
                logger.error(f"Error reading stream in dummy_decode_frame: {e}", exc_info=True)
                return None

        def dummy_detect_motion(prev_frame: object, curr_frame: object) -> None:
            logger.debug("Motion detection triggered")

        camera_stream_buffer = CameraStreamBuffer(camera_stream, ws_handler, dummy_decode_frame)
        motion_detection_buffer = MotionDetectionBuffer(camera_stream, dummy_detect_motion)

        def signal_handler(signum, frame):
            logger.info(f"Signal {signum} received, shutting down...")
            camera_stream_buffer.stop()
            motion_detection_buffer.stop()
            camera_stream.stop()
            ws_handler.close_all_connections()
            raise SystemExit(0)

        signal.signal(signal.SIGINT, signal_handler)
