import numpy as np
import logging

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Buffers an MJPEG stream and flushes complete non-I-frame frames to an output sink."""

    def __init__(self, c, output_sink=None):
        self.c = c
        self.buf = bytearray()
        self.output_sink = output_sink
        self.frame_start = 0
        self.frame_end = 0
        self.frame_type = None
        self.got_frame = False

    def write(self, d):
        """Append bytes d to the internal buffer and flush when a complete non-I frame is ready."""
        try:
            self.buf.extend(d)
            if self.c.encode_meta is not None:
                self.frame_start = self.c.encode_meta.get('frameStart', 0)
                self.frame_end = self.c.encode_meta.get('frameEnd', 0)
                self.frame_type = self.c.encode_meta.get('frameType', None)
                self.got_frame = self.c.encode_meta.get('gotFrame', False)
            else:
                self.frame_start = 0
                self.frame_end = 0
                self.frame_type = None
                self.got_frame = False

            if self.got_frame and self.frame_type != 1:
                frame_data = bytes(self.buf[self.frame_start:self.frame_end])
                if self.output_sink is not None:
                    self.output_sink.write(frame_data)
                self.buf = bytearray()
        except Exception as e:
            logger.error(f"Error in CameraStreamBuffer.write: {e}")


class MotionDetectionBuffer:
    """Buffers an MJPEG stream and invokes a motion-detection callback on each complete JPEG frame."""

    def __init__(self, f):
        self.f = f
        self.buf = bytearray()
        self.prev_frame = None
        self.current_frame = None
        self.got_frame = False

    def write(self, d):
        """Parse the stream for JPEG start markers and invoke the callback on each completed frame."""
        try:
            self.buf.extend(d)
            start_index = 0
            while start_index < len(self.buf) - 1:
                if self.buf[start_index] == 0xFF and self.buf[start_index + 1] == 0xD8:
                    if self.got_frame:
                        frame_data = bytes(self.buf[:start_index])
                        try:
                            self.current_frame = self.f.c.imdecode(np.frombuffer(frame_data, dtype=np.uint8), self.f.c.IMREAD_COLOR)
                            if self.prev_frame is not None and self.current_frame is not None:
                                self.f(self.prev_frame, self.current_frame)
                            self.prev_frame = self.current_frame
                        except Exception as e:
                            logger.error(f"Error decoding frame: {e}")
                        self.buf = self.buf[start_index:]
                        start_index = 0
                        self.got_frame = False
                    else:
                        self.got_frame = True
                start_index += 1
        except Exception as e:
            logger.error(f"Error in MotionDetectionBuffer.write: {e}")

