                            logger.error(f"Error decoding frame: {e}")
                        self.buf = self.buf[start_index:]
                        start_index = 0
                        self.got_frame = False
                    else:
                        self.got_frame = True
                start_index += 1
        except Exception as e:
            logger.error(f"Error in MotionDetectionBuffer.write: {e}")

