import sys
import signal
import time
import threading
import traceback

import cv2
import numpy as np
import config
from sound import Sound

try:
    import face_recognition
except ImportError:
    face_recognition = None

try:
    import audio
except ImportError:
    audio = None


class Door:
    """Minimal door-lock driver stub (BCM 18 output, BCM 17 input with pull-up)."""

    def __init__(self, lock_pin=18, button_pin=17):
        self.lock_pin = lock_pin
        self.button_pin = button_pin
        self._lock = threading.Lock()
        self._running = True

    def lock_door(self):
        pass

    def unlock_door(self):
        pass

    def is_button_up(self):
        return False

    def cleanup(self):
        self._running = False


class FaceRecognizer:
    """Wrapper around the EigenFaceRecognizer with error handling."""

    def __init__(self):
        self.model = None
        try:
            if face_recognition is None:
                raise RuntimeError("face_recognition module not available")
            self.model = face_recognition.load_model(config.TRAINING_FILE)
        except Exception as e:
            print(f"[ERROR] Failed to load face recognition model: {e}")
            traceback.print_exc()

    def recognize_face(self, image):
        if self.model is None:
            return None, None
        try:
            gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
            face_coords = self.model.detect_faces(gray)
            if not face_coords:
                return None, None
            x, y, w, h = face_coords[0]
            cropped = gray[y:y + h, x:x + w]
            label, confidence = self.model.predict_label(cropped)
            return label, float(confidence)
        except Exception as e:
            print(f"[ERROR] Face recognition failed: {e}")
            traceback.print_exc()
            return None, None


class SoundPlayer:
    """Threaded sound player with a bounded queue."""

    def __init__(self, mixer):
        self.mixer = mixer
        self.queue = []
        self.lock = threading.Lock()
        self.thread = None
        self._stop = threading.Event()

    def enqueue(self, sound):
        with self.lock:
            self.queue.append(sound)

    def _worker(self):
        while not self._stop.is_set():
            with self.lock:
                if self.queue:
                    sound = self.queue.pop(0)
                else:
                    sound = None
            if sound is not None:
                try:
                    sound.play(self.mixer)
                except Exception as e:
                    print(f"[ERROR] Sound playback failed: {e}")
                    traceback.print_exc()
            time.sleep(0.01)

    def start(self):
        self.thread = threading.Thread(target=self._worker, daemon=True)
        self.thread.start()

    def stop(self):
        self._stop.set()
        if self.thread is not None:
            self.thread.join(timeout=2.0)


class FaceRecognitionSystem:
    """Main system controller."""

    def __init__(self):
        self.door = Door()
        self.recognizer = FaceRecognizer()
        self.mixer = None
        self.player = None
        self.camera = None
        self._stop = threading.Event()
        self._lock = threading.Lock()
        self._shutting_down = False

        try:
            if audio is None:
                raise RuntimeError("audio module not available")
            self.mixer = audio.Mixer()
            self.player = SoundPlayer(self.mixer)
            self.player.start()
