            print(f"[ERROR] Failed to initialize audio: {e}")
            traceback.print_exc()
            self.mixer = None
            self.player = None

        try:
            self.camera = cv2.VideoCapture(0)
            if not self.camera.isOpened():
                raise RuntimeError("Could not open camera")
        except Exception as e:
            print(f"[ERROR] Failed to initialize camera: {e}")
            traceback.print_exc()
            self.camera = None

        self.sounds = {}
        for name, path in (
            ("welcome", "welcome.wav"),
            ("wait", "wait.wav"),
            ("later", "later.wav"),
        ):
            try:
                self.sounds[name] = Sound(path)
            except Exception as e:
                print(f"[ERROR] Failed to load sound {path}: {e}")
                self.sounds[name] = None

    def _play(self, name):
        if self.player is None or self.sounds.get(name) is None:
            return
        self.player.enqueue(self.sounds[name])

    def _cleanup(self):
        if self._shutting_down:
            return
        self._shutting_down = True
        print("[INFO] Cleaning up resources...")
        self._stop.set()
        if self.player is not None:
            self.player.stop()
        if self.mixer is not None:
            try:
                self.mixer.stop()
            except Exception:
                pass
        if self.camera is not None:
            try:
                self.camera.release()
            except Exception:
                pass
        self.door.cleanup()
        print("[INFO] Cleanup complete.")

    def _signal_handler(self, signum, frame):
        print(f"[INFO] Signal {signum} received, shutting down...")
        self._cleanup()
        sys.exit(0)

    def run(self):
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        if self.mixer is not None:
            try:
                self.mixer.start()
            except Exception as e:
                print(f"[ERROR] Failed to start audio mixer: {e}")
                traceback.print_exc()

        print("[INFO] Door-lock system running. Press Ctrl+C to exit.")
        try:
            while not self._stop.is_set():
                if self.camera is not None and self.camera.isOpened():
                    ret, frame = self.camera.read()
                    if ret and frame is not None:
                        label, confidence = self.recognizer.recognize_face(frame)
                        if label is not None:
                            print(
                                f"[INFO] Recognized: {label}, Confidence: {confidence}"
                            )
                            if (
                                label == config.POSITIVE_LABEL
                                and confidence < config.POSITIVE_THRESHOLD
                            ):
                                print("[INFO] Unlocking door...")
                                self.door.unlock_door()
                                self._play("welcome")
                            else:
                                self._play("wait")
                        else:
                            self._play("later")
                else:
                    print("[WARN] Camera unavailable; skipping frame.")

                if self.door.is_button_up():
                    print("[INFO] Button pressed; attempting face recognition...")

                time.sleep(0.1)
        except Exception as e:
            print(f"[ERROR] Unexpected error in main loop: {e}")
            traceback.print_exc()
        finally:
            self._cleanup()


if __name__ == "__main__":
    system = FaceRecognitionSystem()
    system.run()

