import cv2
import sys

WINDOW_NAME = "Face Detection"
CASCADE_FILE = "haarcascade_frontalface_default.xml"

def initialize_camera(resolution=(640, 480)):
    """Initialize the camera with the specified resolution."""
    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise IOError("Cannot open webcam")
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, resolution[0])
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, resolution[1])
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None

def detect_faces(image, face_cascade):
    """Detect faces in the given image using the provided cascade classifier."""
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    return face_cascade.detectMultiScale(gray, scaleFactor=1.3, minNeighbors=5)

def draw_rectangles(image, faces):
    """Draw rectangles around detected faces in the image."""
    for (x, y, w, h) in faces:
        cv2.rectangle(image, (x, y), (x + w, y + h), (0, 255, 0), 2)

def process_frame(frame, face_cascade):
    """Process a single frame: detect faces and draw rectangles."""
    faces = detect_faces(frame, face_cascade)
    draw_rectangles(frame, faces)
    return frame

def main():
    """Main function to run the face detection."""
    camera = initialize_camera()
    if camera is None:
        sys.exit(1)

    try:
        face_cascade = cv2.CascadeClassifier(CASCADE_FILE)
        if face_cascade.empty():
            raise IOError(f"Unable to load cascade file: {CASCADE_FILE}")

        cv2.namedWindow(WINDOW_NAME)

        while True:
            ret, frame = camera.read()
            if not ret:
                print("Failed to grab frame", file=sys.stderr)
                break

            processed_frame = process_frame(frame, face_cascade)
            cv2.imshow(WINDOW_NAME, processed_frame)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except KeyboardInterrupt:
        print("Program interrupted by user", file=sys.stderr)
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
    finally:
        camera.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

