import signal
import sys
import time

import smbus2
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306
from adafruit_bme280 import basic as adafruit_bme280
from adafruit_tsl2561 import TSL2561

I2C_BUS = 1
I2C_ADDR_OLED = 0x3C
I2C_ADDR_BME280 = 0x76
I2C_ADDR_TSL2561 = 0x29

running = True


def handle_sigint(signum, frame):
    global running
    running = False


def init_oled():
    try:
        return ssd1306(i2c(port=I2C_BUS, address=I2C_ADDR_OLED))
    except Exception as e:
        print(f"Error initializing OLED at 0x{I2C_ADDR_OLED:02X}: {e}", file=sys.stderr)
        return None


def init_bme280():
    try:
        bus = smbus2.SMBus(I2C_BUS)
        try:
            bus.read_byte(I2C_ADDR_BME280)
        finally:
            bus.close()
        return adafruit_bme280.Adafruit_BME280_I2C(smbus2.SMBus(I2C_BUS), address=I2C_ADDR_BME280)
    except Exception as e:
        print(f"Error initializing BME280 at 0x{I2C_ADDR_BME280:02X}: {e}", file=sys.stderr)
        return None


def init_tsl2561():
    try:
        bus = smbus2.SMBus(I2C_BUS)
        try:
            bus.read_byte(I2C_ADDR_TSL2561)
        finally:
            bus.close()
        return TSL2561(smbus2.SMBus(I2C_BUS), address=I2C_ADDR_TSL2561)
    except Exception as e:
        print(f"Error initializing TSL2561 at 0x{I2C_ADDR_TSL2561:02X}: {e}", file=sys.stderr)
        return None


def read_sensor_data(bme280, tsl2561):
    try:
        temp = bme280.temperature
    except Exception as e:
        print(f"Error reading temperature: {e}", file=sys.stderr)
        temp = None

    try:
        humidity = bme280.humidity
    except Exception as e:
        print(f"Error reading humidity: {e}", file=sys.stderr)
        humidity = None

    try:
        pressure = bme280.pressure
    except Exception as e:
        print(f"Error reading pressure: {e}", file=sys.stderr)
        pressure = None

    try:
        light = tsl2561.lux
    except Exception as e:
        print(f"Error reading light level: {e}", file=sys.stderr)
        light = None

    return temp, humidity, pressure, light


def display_data(oled, temp, humidity, pressure, light):
    try:
        with canvas(oled) as draw:
            draw.text((0, 0), f"Temp: {temp:.1f} C" if temp is not None else "Temp: N/A", fill="white")
            draw.text((0, 12), f"Humidity: {humidity:.1f} %" if humidity is not None else "Humidity: N/A", fill="white")
            draw.text((0, 24), f"Pressure: {pressure:.1f} hPa" if pressure is not None else "Pressure: N/A", fill="white")
            draw.text((0, 36), f"Light: {light:.1f} lux" if light is not None else "Light: N/A", fill="white")
    except Exception as e:
        print(f"Error displaying data: {e}", file=sys.stderr)


def main():
    global running
    signal.signal(signal.SIGINT, handle_sigint)

    oled = init_oled()
    if oled is None:
        sys.exit(1)

    bme280 = init_bme280()
    if bme280 is None:
        oled.clear()
        sys.exit(1)

    tsl2561 = init_tsl2561()
    if tsl2561 is None:
        oled.clear()
        sys.exit(1)

    try:
        while running:
            temp, humidity, pressure, light = read_sensor_data(bme280, tsl2561)
            display_data(oled, temp, humidity, pressure, light)
            time.sleep(1)
    finally:
        try:
            oled.clear()
        except Exception:
            pass
        print("Program terminated.")


if __name__ == "__main__":
    main()

