import os
import time
import signal
import logging
from typing import List, Optional, Tuple

import numpy as np
from PIL import Image, UnidentifiedImageError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class AnimatedGif:
    """
    A class to manage and play animated GIF files on a display.
    """

    def __init__(self, display, width: Optional[int] = None, height: Optional[int] = None, folder: Optional[str] = None):
        self.display = display
        self.width = width if width is not None else getattr(display, 'width', 320)
        self.height = height if height is not None else getattr(display, 'height', 240)
        self.gif_files: List[str] = []
        self.gif_data: List[Tuple[List[np.ndarray], int, int]] = []
        self.current_gif_index = 0
        self._is_running = False
        self._file_handle = None

        if folder:
            self.load_files(folder)

    def load_files(self, folder: str) -> None:
        if not os.path.isdir(folder):
            raise FileNotFoundError(f"Folder not found: {folder}")

        self.gif_files.clear()
        for fname in sorted(os.listdir(folder)):
            if fname.lower().endswith('.gif'):
                file_path = os.path.join(folder, fname)
                try:
                    with Image.open(file_path) as img:
                        if getattr(img, 'is_animated', False):
                            self.gif_files.append(file_path)
                            logger.info(f"Found animated GIF: {fname}")
                        else:
                            logger.warning(f"Skipping non-animated GIF: {fname}")
                except (UnidentifiedImageError, OSError) as e:
                    logger.error(f"Error processing GIF {fname}: {e}")
                except Exception as e:
                    logger.exception(f"Unexpected error processing GIF {fname}: {e}")

        if not self.gif_files:
            raise FileNotFoundError(f"No valid animated GIF files found in {folder}")

    def preload(self) -> None:
        self.gif_data.clear()
        for file_path in self.gif_files:
            try:
                with Image.open(file_path) as img:
                    duration = img.info.get('duration', 100)
                    loop_count = img.info.get('loop', 0)
                    frames = []
                    for frame_idx in range(img.n_frames):
                        img.seek(frame_idx)
                        frame_data = np.array(img.convert('RGB'))
                        padded_frame = self._pad_frame(frame_data)
                        frames.append(padded_frame)
                    self.gif_data.append((frames, duration, loop_count))
                    logger.info(f"Preloaded GIF: {file_path}, {len(frames)} frames")
            except (UnidentifiedImageError, OSError) as e:
                logger.error(f"Error preloading GIF {file_path}: {e}")
                self.gif_data.append(([], 0, 0))
            except Exception as e:
                logger.exception(f"Unexpected error preloading GIF {file_path}: {e}")
                self.gif_data.append(([], 0, 0))

    def _pad_frame(self, frame: np.ndarray) -> np.ndarray:
        orig_h, orig_w = frame.shape[:2]
        scale_x = self.width / orig_w
        scale_y = self.height / orig_h
        scale = min(scale_x, scale_y)
        new_w = max(1, int(orig_w * scale))
        new_h = max(1, int(orig_h * scale))
        resized = np.array(Image.fromarray(frame).resize((new_w, new_h), Image.Resampling.NEAREST))
        pad_x = (self.width - new_w) // 2
        pad_y = (self.height - new_h) // 2
        padded = np.zeros((self.height, self.width, 3), dtype=np.uint8)
        padded[pad_y:pad_y + new_h, pad_x:pad_x + new_w, :] = resized
        return padded

    def play(self) -> bool:
        if not self.gif_data:
            logger.error("No GIF data loaded. Call preload() first.")
            return False

        frames, duration, loop_count = self.gif_data[self.current_gif_index]
        if not frames:
            logger.error(f"No frames for GIF at index {self.current_gif_index}")
            return False

        try:
            for frame_data in frames:
                start_time = time.monotonic()
                self.display.display(frame_data)
                sleep_time = (duration / 1000.0) - (time.monotonic() - start_time)
                if sleep_time > 0:
                    time.sleep(sleep_time)

            if loop_count == 0:
                return True
            elif loop_count > 0:
                loop_count -= 1
                self.gif_data[self.current_gif_index] = (frames, duration, loop_count)
                if loop_count > 0:
                    return True
            return True
        except Exception as e:
            logger.exception(f"Error playing GIF: {e}")
            return False

    def run(self) -> None:
        self._is_running = True
        try:
            while self._is_running:
                if not self.play():
                    break
                self.current_gif_index = (self.current_gif_index + 1) % len(self.gif_files)
        except Exception as e:
            logger.exception(f"Error in animation loop: {e}")
        finally:
            self.stop()

    def stop(self) -> None:
        self._is_running = False
        if self._file_handle is not None:
            try:
                self._file_handle.close()
            except Exception as e:
                logger.error(f"Error closing file handle: {e}")
            self._file_handle = None

    def signal_handler(self, signum, frame) -> None:
        logger.info(f"Signal {signum} received, stopping animation.")
        self.stop()


def main():
    gif_folder = "./gifs"
    try:
        display = None  # Replace with actual display object
        anim = AnimatedGif(display, folder=gif_folder)
        anim.preload()

        signal.signal(signal.SIGINT, anim.signal_handler)
        signal.signal(signal.SIGTERM, anim.signal_handler)

        anim.run()
    except FileNotFoundError as e:
        logger.error(f"Initialization error: {e}")
    except Exception as e:
        logger.exception(f"Unexpected error: {e}")


if __name__ == "__main__":
    main()

