import time
import signal
import sys
import board
import busio
import adafruit_character_lcd.character_lcd_i2c as character_lcd
import adafruit_dht

# --- Configuration ---
DHT_PIN = board.D4          # GPIO4 (BCM)
I2C_SCL = board.SCL        # GPIO3 (BCM)
I2C_SDA = board.SDA        # GPIO2 (BCM)

# --- Globals for cleanup ---
lcd = None
dht_device = None
running = True

def cleanup():
    """Clear the LCD and release resources."""
    global lcd, dht_device
    if lcd is not None:
        try:
            lcd.clear()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False

def main():
    global lcd, dht_device

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # --- I2C Bus Initialization ---
    try:
        i2c_bus = busio.I2C(I2C_SCL, I2C_SDA)
    except Exception as e:
        print(f"Fatal: I2C bus initialization failed: {e}", file=sys.stderr)
        sys.exit(1)

    # --- LCD Initialization ---
    try:
        lcd = character_lcd.Character_LCD_I2C(i2c_bus, 16, 2)
    except Exception as e:
        print(f"Fatal: LCD initialization failed: {e}", file=sys.stderr)
        sys.exit(1)

    # --- DHT22 Sensor Initialization ---
    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Fatal: DHT22 initialization failed: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    # --- Main Loop ---
    try:
        while running:
            try:
                temperature = dht_device.temperature
                humidity = dht_device.humidity

                if temperature is None or humidity is None:
                    raise RuntimeError("Sensor returned None for temperature or humidity")

                lcd.message = f"Temp: {temperature:.1f} C\nHumidity: {humidity:.1f}%"
                print(f"Temp: {temperature:.1f} C, Humidity: {humidity:.1f}%")

            except RuntimeError as e:
                # DHT22 checksum errors, timing errors, or sensor absence
                print(f"Sensor read error: {e}", file=sys.stderr)
                try:
                    lcd.message = "Sensor Error\nCheck Wiring"
                except Exception:
                    pass

            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)
                try:
                    lcd.message = "Error\nCheck Logs"
                except Exception:
                    pass

            # Sleep in small increments to allow signal handler to interrupt promptly
            for _ in range(20):
                if not running:
                    break
                time.sleep(0.1)

    finally:
        cleanup()

if __name__ == "__main__":
    main()

