import os
import signal
import sys
import time
from typing import List, Optional

import gc
from PIL import Image

try:
    import libgpiod
    from libgpiod import LineSettings, LineInfo
except ImportError:
    libgpiod = None

try:
    from libgdfb import ST7789
except ImportError:
    ST7789 = None


class GifPlayer:
    """
    A class to manage the playback of GIF files on an ST7789 display.
    """

    def __init__(self, folder: str, display: Optional[object] = None):
        self.folder = folder
        self.gif_files: List[str] = []
        self.current_index = 0
        self.display = display
        self._running = True

        if self.display is None and ST7789 is not None:
            try:
                self.display = ST7789()
            except Exception as e:
                print(f"Error initializing display: {e}", file=sys.stderr)
                self.display = None

        if self.display is None:
            print("Display not initialized.", file=sys.stderr)
            return

        self._load_gif_files()

    def _load_gif_files(self) -> None:
        if not os.path.isdir(self.folder):
            print(f"Error: Folder not found: {self.folder}", file=sys.stderr)
            self.gif_files = []
            return

        try:
            self.gif_files = [
                f for f in os.listdir(self.folder)
                if f.lower().endswith('.gif')
            ]
        except OSError as e:
            print(f"Error accessing folder {self.folder}: {e}", file=sys.stderr)
            self.gif_files = []
            return

        if not self.gif_files:
            print(f"No GIF files found in {self.folder}", file=sys.stderr)

    def play(self, gif_file: str) -> bool:
        if not self.display:
            print("Display not initialized.", file=sys.stderr)
            return False

        file_path = os.path.join(self.folder, gif_file)
        try:
            with Image.open(file_path) as image:
                duration = 100
                for frame_index in range(image.n_frames):
                    if not self._running:
                        return False
                    image.seek(frame_index)
                    frame = image.convert('RGB')
                    width, height = frame.size
                    if width != 240 or height != 240:
                        padded = Image.new('RGB', (240, 240), (0, 0, 0))
                        padded.paste(frame, ((240 - width) // 2, (240 - height) // 2))
                        frame = padded
                    self.display.display_image(frame)
                    if image.info.get('duration'):
                        duration = image.info['duration']
                    time.sleep(duration / 1000.0)
                    gc.collect()
            return True
        except FileNotFoundError:
            print(f"Error: GIF file not found: {file_path}", file=sys.stderr)
            return False
        except (OSError, IOError) as e:
            print(f"Error reading GIF file {file_path}: {e}", file=sys.stderr)
            return False
        except Exception as e:
            print(f"Unexpected error playing GIF {file_path}: {e}", file=sys.stderr)
            return False

    def run(self) -> None:
        if not self.gif_files or not self.display:
            print("No GIF files loaded or display not initialized.", file=sys.stderr)
            return

        print(f"Playing {len(self.gif_files)} GIF files from {self.folder}...")
        while self._running:
            gif_file = self.gif_files[self.current_index]
            self.play(gif_file)
            self.current_index = (self.current_index + 1) % len(self.gif_files)

    def stop(self) -> None:
        self._running = False


def main() -> None:
    gif_folder = './gifs'
    player: Optional[GifPlayer] = None

    def signal_handler(signum, frame):
        print(f"\nReceived signal {signum}, exiting...")
        if player is not None:
            player.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        player = GifPlayer(gif_folder)
        player.run()
    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
    finally:
        if player is not None and player.display is not None:
            try:
                player.display.clear()
            except Exception:
                pass
            try:
                player.display.close()
            except Exception:
                pass
        print("Program finished.")


if __name__ == "__main__":
    main()

