import sys
import time
import logging
from typing import List, Optional, Tuple

import numpy as np
from PIL import Image, ImageOps

try:
    import smbus2
except ImportError:
    smbus2 = None

try:
    from libgpiod import Chip, Line
except ImportError:
    Chip = None
    Line = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class SSD1306:
    """Minimal SSD1306 128x64 OLED driver using smbus2."""

    def __init__(self, bus: int = 1, addr: int = 0x3C, width: int = 128, height: int = 64):
        if smbus2 is None:
            raise RuntimeError('smbus2 library is required for I2C communication.')
        self.width = width
        self.height = height
        self.bus_num = bus
        self.addr = addr
        self._bus = None
        self._running = True
        self._init_i2c()

    def _init_i2c(self):
        try:
            self._bus = smbus2.SMBus(self.bus_num)
        except FileNotFoundError:
            raise RuntimeError(f'I2C bus {self.bus_num} not found. Enable I2C and check /dev/i2c-{self.bus_num}.')
        except PermissionError:
            raise RuntimeError(f'Permission denied on /dev/i2c-{self.bus_num}. Add user to the i2c group.')
        except OSError as e:
            raise RuntimeError(f'Failed to open I2C bus {self.bus_num}: {e}')

        try:
            self._bus.read_byte(self.addr)
        except OSError as e:
            self._bus.close()
            self._bus = None
            raise RuntimeError(f'No device found at I2C address 0x{self.addr:02X} on bus {self.bus_num}: {e}')

        self._init_display()

    def _write_cmd(self, cmd: int):
        if self._bus is None:
            raise RuntimeError('I2C bus is not initialized.')
        try:
            self._bus.write_byte_data(self.addr, 0x00, cmd)
        except OSError as e:
            raise RuntimeError(f'I2C write command 0x{cmd:02X} failed: {e}')

    def _write_data(self, data: List[int]):
        if self._bus is None:
            raise RuntimeError('I2C bus is not initialized.')
        try:
            self._bus.write_i2c_block_data(self.addr, 0x40, data)
        except OSError as e:
            raise RuntimeError(f'I2C write data failed: {e}')

    def _init_display(self):
        cmds = [
            0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40, 0x8D, 0x14,
            0x20, 0x00, 0xA1, 0xC8, 0xDA, 0x12, 0x81, 0xCF, 0xD9, 0xF1,
            0xDB, 0x40, 0xA4, 0xA6, 0xAF,
        ]
        for cmd in cmds:
            self._write_cmd(cmd)

    def display_frame(self, image: Image.Image):
        if self._bus is None:
            raise RuntimeError('I2C bus is not initialized.')
        if image.size != (self.width, self.height):
            raise ValueError(f'Image must be exactly {self.width}x{self.height} pixels.')

        pixels = np.array(image.convert('1'), dtype=np.uint8)
        buffer = []
        for row in pixels:
            byte = 0
            for bit in row:
                byte = (byte << 1) | (1 if bit else 0)
            buffer.append(byte)

        self._write_cmd(0x21)
        self._write_cmd(0)
        self._write_cmd(self.width - 1)
        self._write_cmd(0x22)
        self._write_cmd(0)
        self._write_cmd(self.height - 1)
        self._write_data(list(buffer))

    def clear(self):
        self._write_cmd(0x01)
        self._write_data([0xFF] * (self.width * self.height))

    def close(self):
        if self._bus is not None:
            try:
                self.clear()
            except Exception:
                pass
            self._bus.close()
            self._bus = None


class GifPlayer:
    def __init__(self, display: SSD1306, folder: str):
        self.display = display
        self.folder = folder
        self.gif_files: List[str] = []
        self.current_gif_index = 0
        self._running = True
        self._load_gif_files()

    def _load_gif_files(self):
        if not os.path.isdir(self.folder):
            raise FileNotFoundError(f'Folder not found: {self.folder}')
        self.gif_files = sorted(
            f for f in os.listdir(self.folder) if f.lower().endswith('.gif')
        )
        if not self.gif_files:
            raise FileNotFoundError(f'No GIF files found in {self.folder}')
        logger.info(f'Found {len(self.gif_files)} GIF file(s).')

    def _signal_handler(self, signum, frame):
        logger.info('SIGINT received, shutting down...')
        self._running = False

    def play_gif(self, filename: str):
        filepath = os.path.join(self.folder, filename)
        try:
            with Image.open(filepath) as image:
                duration = image.info.get('duration', 100)
                width, height = image.size
                resized = ImageOps.fit(image, (self.display.width, self.display.height), method='lanczos')
                padded = Image.new('1', (self.display.width, self.display.height), 0)
                padded.paste(resized, (
                    (self.display.width - width) // 2,
                    (self.display.height - height) // 2
                ))
                self.display.display_frame(padded)
                time.sleep(duration / 1000.0)
        except FileNotFoundError:
            logger.error(f'File not found: {filepath}')
        except Exception as e:
            logger.error(f'Error processing {filepath}: {e}')

    def play_all_gifs(self, loop_count: int):
        if loop_count < 0:
            logger.warning('Invalid loop count.')
            return
        start_index = self.current_gif_index
        while self._running:
            for i in range(start_index, len(self.gif_files)):
                if not self._running:
                    break
                self.play_gif(self.gif_files[i])
            if loop_count == 0:
                start_index = 0
                continue
            loop_count -= 1
            if loop_count == 0:
                break
            start_index = 0

    def run(self):
        signal.signal(signal.SIGINT, self._signal_handler)
        try:
            self.play_all_gifs(0)
        except Exception as e:
            logger.error(f'Runtime error: {e}')
        finally:
            self.display.close()
            logger.info('Display closed.')


def main():
    folder = './gifs'
    display = None
    try:
        display = SSD1306(bus=1, addr=0x3C, width=128, height=64)
        player = GifPlayer(display, folder)
        player.run()
    except FileNotFoundError as e:
        logger.error(str(e))
        sys.exit(1)
    except RuntimeError as e:
        logger.error(f'I2C initialization failed: {e}')
        sys.exit(1)
    except Exception as e:
        logger.error(f'Unexpected error: {e}')
        sys.exit(1)
    finally:
        if display is not None:
            display.close()


if __name__ == '__main__':
    main()

