    global running
    running = False

def read_temperature(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        line = raw.decode('ascii', errors='replace').strip()
    except Exception as e:
        print(f"Error decoding data: {e}", file=sys.stderr)
        return None
    if not line:
        return None
    try:
        return float(line)
    except ValueError:
        print(f"Invalid data received (not a float): '{line}'", file=sys.stderr)
        return None

