import smbus2
import time
import logging

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class DHT20:
    """Driver for the DHT20 temperature/humidity sensor on a Raspberry Pi."""

    I2C_BUS = 1
    I2C_ADDR = 0x60
    POWER_ON_DELAY = 0.5
    STATUS_CHECK_DELAY = 0.1
    READ_TIMEOUT = 0.1
    MAX_RETRIES = 5
    RETRY_DELAY = 2.0

    def __init__(self, bus_number=I2C_BUS, address=I2C_ADDR):
        self.address = address
        self._bus = None
        self._open_bus(bus_number)
        time.sleep(self.POWER_ON_DELAY)
        if not self._check_status():
            logging.error("DHT20 status check failed after power-on delay.")
            self.cleanup()
            raise OSError("DHT20 sensor not responding or bus error.")

    def _open_bus(self, bus_number):
        try:
            self._bus = smbus2.SMBus(bus_number)
            logging.info(f"I2C bus {bus_number} opened successfully.")
        except OSError as e:
            logging.error(f"Failed to open I2C bus {bus_number}: {e}")
            raise

    def _check_status(self):
        if self._bus is None:
            return False
        try:
            status = self._bus.read_byte_data(self.address, 0x00)
            return (status & 0x80) == 0x80
        except OSError as e:
            logging.error(f"I2C read error during status check: {e}")
            return False

    def _crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def read_retry(self):
        for attempt in range(1, self.MAX_RETRIES + 1):
            try:
                if self._read_sensor():
                    return True
            except OSError as e:
                logging.error(f"I2C bus error on attempt {attempt}: {e}")
            if attempt < self.MAX_RETRIES:
                time.sleep(self.RETRY_DELAY)
        logging.error(f"Failed to read DHT20 after {self.MAX_RETRIES} attempts.")
        return False

    def _read_sensor(self):
        if self._bus is None:
            return False
        try:
            self._bus.write_byte(self.address, 0xAC)
            time.sleep(self.STATUS_CHECK_DELAY)
            status = self._bus.read_byte_data(self.address, 0x00)
            if (status & 0x80) != 0x80:
                logging.warning("DHT20 status bit 7 not set; retrying.")
                return False
            data = self._bus.read_i2c_block_data(self.address, 0x71, 7)
            if len(data) != 7:
                logging.error(f"Unexpected data length: {len(data)}")
                return False
            humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
            temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
            humidity = (humidity_raw / 0x100000) * 100.0
            temperature = (temperature_raw / 0x100000) * 200.0 - 50.0
            calculated_crc = self._crc8(data[:6])
            received_crc = data[6]
            crc_error = calculated_crc != received_crc
            logging.info(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%, CRC error: {crc_error}")
            self.temperature = temperature
            self.humidity = humidity
            self.crc_error = crc_error
            return True
        except OSError as e:
            logging.error(f"I2C read error: {e}")
            return False

    def read_and_process(self):
        if not self.read_retry():
            self.crc_error = True
            self.temperature = None
            self.humidity = None
            return False
        return True

    def cleanup(self):
        if self._bus is not None:
            try:
                self._bus.close()
                logging.info("I2C bus closed.")
            except OSError as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self._bus = None

