        if sensor.read_and_process():
            print(f"Temperature: {sensor.temperature:.2f}°C, Humidity: {sensor.humidity:.2f}%")
        else:
            print("Read failed.")
    except OSError as e:
        logging.error(f"Initialization failed: {e}")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")

