    I2C_ADDR = 0x60
    STATUS_REG = 0x00
    DATA_REG = 0x00
    MEASURE_CMD = 0xAC
    CMD_MSB = 0x33
    CRC_POLYNOMIAL = 0x31
    CRC_INITIAL = 0xFF
    MEASURE_DELAY = 0.01
    TIMEOUT = 0.1

    def __init__(self, bus_number=I2C_BUS):
        self.bus = None
        try:
            self.bus = smbus2.SMBus(bus_number)
            self._verify_sensor()
        except Exception as e:
            logging.error(f"Failed to initialize I2C bus {bus_number}: {e}")
            self.bus = None

    def _verify_sensor(self):
        if self.bus is None:
            raise RuntimeError("I2C bus is not initialized")
        status = self._read_register(self.STATUS_REG, 1)[0]
        if status != 0x08:
            raise RuntimeError(f"Sensor verification failed: status register is 0x{status:02X}, expected 0x08")
        logging.info("DHT20 sensor verified successfully.")

    def _read_register(self, register, length):
        return self.bus.read_i2c_block_data(self.I2C_ADDR, register, length)

    def _write_register(self, register, value):
        self.bus.write_i2c_block_data(self.I2C_ADDR, register, [value])

    @staticmethod
    def _calculate_crc(data):
        crc = DHT20.CRC_INITIAL
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ DHT20.CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def measure(self):
        if self.bus is None:
            logging.error("I2C bus is not initialized.")
            return None, None, True

        try:
            self._write_register(self.MEASURE_CMD, self.CMD_MSB)
        except Exception as e:
            logging.error(f"Failed to initiate measurement: {e}")
            return None, None, True

        start_time = time.time()
        while True:
            try:
                status = self._read_register(self.STATUS_REG, 1)[0]
            except Exception as e:
                logging.error(f"Failed to read status register: {e}")
                return None, None, True

            if status & 0x08:
                break

            if time.time() - start_time > self.TIMEOUT:
                logging.error("Measurement timed out.")
                return None, None, True

            time.sleep(self.MEASURE_DELAY)

        try:
            data = self._read_register(self.DATA_REG, 7)
        except Exception as e:
            logging.error(f"Failed to read measurement data: {e}")
            return None, None, True

        if len(data) != 7:
            logging.error(f"Unexpected data length: {len(data)}")
            return None, None, True

        calculated_crc = self._calculate_crc(data[:6])
        received_crc = data[6]

        if calculated_crc != received_crc:
            logging.error(f"CRC mismatch: calculated 0x{calculated_crc:02X}, received 0x{received_crc:02X}")
            return None, None, True

        humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

        humidity = (humidity_raw / 0x100000) * 100.0
        temperature = (temperature_raw / 0x100000) * 200.0 - 50.0

        return temperature, humidity, False

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self.bus = None


def main():
    sensor = DHT20()

    def signal_handler(signum, frame):
        logging.info(f"Signal {signum} received, shutting down.")
        sensor.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if sensor.bus is None:
        logging.error("Failed to initialize DHT20 sensor. Exiting.")
        return

    try:
        temperature, humidity, crc_error = sensor.measure()
        if crc_error:
            logging.error("CRC error detected.")
        else:
            logging.info(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        sensor.close()


if __name__ == "__main__":
    main()

