#!/usr/bin/env python3
"""Greenhouse Vent Controller for Raspberry Pi.

Controls a solenoid vent solenoid on BCM pin 17 based on temperature and
humidity readings from two DHT22 sensors on BCM pins 4 and 23, with a
normally-closed limit switch on BCM pin 5.  Pull-up inputs are configured
on BCM pins 5, 6, 12, 13, 16, 20, 21, and 26.
"""

import logging
import signal
import sys
import time

import gpiozero
from gpiozero import DigitalInputDevice, DigitalOutputDevice

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
SOLENOID_PIN = 17
LIMIT_SWITCH_PIN = 5
DHT22_PIN_1 = 4
DHT22_PIN_2 = 23

PULLUP_PINS = [5, 6, 12, 13, 16, 20, 21, 26]

MAX_TEMP = 30.0
MIN_HUMIDITY = 60.0
HYSTERESIS = 2.0

ACTUATION_DURATION = 5.0
POLL_INTERVAL = 60.0
TIMEOUT_INTERVAL = 10.0

LOG_FILE = "greenhouse.log"

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_solenoid: DigitalOutputDevice | None = None
_limit_switch: DigitalInputDevice | None = None
_dht1: gpiozero.DHT22 | None = None
_dht2: gpiozero.DHT22 | None = None
_pullups: list[DigitalInputDevice] = []
_running = True


def _cleanup() -> None:
    """Release every GPIO resource we hold."""
    global _solenoid, _limit_switch, _dht1, _dht2, _pullups
    for dev in (_solenoid, _limit_switch, _dht1, _dht2):
        if dev is not None:
            try:
                dev.close()
            except Exception:
                pass
    for dev in _pullups:
        if dev is not None:
            try:
                dev.close()
            except Exception:
                pass
    _solenoid = None
    _limit_switch = None
    _dht1 = None
    _dht2 = None
    _pullups.clear()


def _signal_handler(signum, frame) -> None:
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    global _running
    _running = False
    logging.info("Received signal %s, shutting down.", signum)


def _setup_gpio() -> None:
    """Initialize every GPIO device; raise on failure."""
    global _solenoid, _limit_switch, _dht1, _dht2, _pullups

    try:
        _solenoid = DigitalOutputDevice(SOLENOID_PIN, active_high=True, initial_value=False)
    except Exception as exc:
        logging.error("Failed to initialize solenoid on BCM %d: %s", SOLENOID_PIN, exc)
        raise

    try:
        _limit_switch = DigitalInputDevice(
            LIMIT_SWITCH_PIN, pull_up=True, bounce_time=0.05
        )
    except Exception as exc:
        logging.error("Failed to initialize limit switch on BCM %d: %s", LIMIT_SWITCH_PIN, exc)
        raise

    try:
        _dht1 = gpiozero.DHT22(DHT22_PIN_1)
    except Exception as exc:
        logging.error("Failed to initialize DHT22 on BCM %d: %s", DHT22_PIN_1, exc)
        raise

    try:
        _dht2 = gpiozero.DHT22(DHT22_PIN_2)
    except Exception as exc:
        logging.error("Failed to initialize DHT22 on BCM %d: %s", DHT22_PIN_2, exc)
        raise

    for pin in PULLUP_PINS:
        try:
            _pullups.append(DigitalInputDevice(pin, pull_up=True, bounce_time=0.05))
        except Exception as exc:
            logging.error("Failed to initialize pull-up on BCM %d: %s", pin, exc)
            raise


def _read_sensor(sensor: gpiozero.DHT22, name: str) -> tuple[float | None, float | None]:
    """Return (temperature_c, humidity) or (None, None) on failure."""
    try:
        if sensor.temperature is None or sensor.humidity is None:
            return None, None
        return float(sensor.temperature), float(sensor.humidity)
    except Exception as exc:
        logging.error("Error reading %s: %s", name, exc)
        return None, None


def _open_vent() -> None:
    """Energize the solenoid for ACTUATION_DURATION seconds, logging results."""
    logging.info("Actuating solenoid...")
    try:
        _solenoid.on()
    except Exception as exc:
        logging.error("Failed to energize solenoid: %s", exc)
        return

    start = time.monotonic()
    try:
        while _running and (time.monotonic() - start) < ACTUATION_DURATION:
            if _limit_switch.is_active:
                logging.info("Limit switch triggered before completion.")
                return
            time.sleep(0.1)
    finally:
        try:
            _solenoid.off()
        except Exception as exc:
            logging.error("Failed to de-energize solenoid: %s", exc)
        logging.info("Solenoid de-energized.")


def _check_vent_open() -> bool:
    """Return True if the limit switch is currently active (vent fully open)."""
    try:
        return bool(_limit_switch.is_active)
    except Exception as exc:
        logging.error("Error reading limit switch: %s", exc)
        return False


def _main_loop() -> None:
    """Poll sensors and actuate the vent when conditions are met."""
    global _running
    last_temp1 = 25.0
    last_hum1 = 50.0
    last_temp2 = 25.0
    last_hum2 = 50.0

    while _running:
        temp1, hum1 = _read_sensor(_dht1, "DHT22_1")
        if temp1 is not None and hum1 is not None:
            last_temp1, last_hum1 = temp1, hum1
        else:
            logging.warning("Using last known values for DHT22_1: %.1fC, %.1f%%", last_temp1, last_hum1)

        temp2, hum2 = _read_sensor(_dht2, "DHT22_2")
        if temp2 is not None and hum2 is not None:
            last_temp2, last_hum2 = temp2, hum2
        else:
            logging.warning("Using last known values for DHT22_2: %.1fC, %.1f%%", last_temp2, last_hum2)

        avg_temp = (last_temp1 + last_temp2) / 2.0
        avg_hum = (last_hum1 + last_hum2) / 2.0

        logging.info("Avg Temp: %.1fC, Avg Humidity: %.1f%%", avg_temp, avg_hum)

        if avg_temp > MAX_TEMP and avg_hum < MIN_HUMIDITY:
            logging.info("Conditions met for vent opening.")
            if _check_vent_open():
                logging.info("Vent already fully open.")
            else:
                _open_vent()
        else:
            logging.info("Conditions not met for vent opening.")

        # Sleep in small increments so signals are caught promptly
        slept = 0.0
        while _running and slept < POLL_INTERVAL:
            time.sleep(0.5)
            slept += 0.5


def main() -> int:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _setup_gpio()
    except Exception:
        logging.error("GPIO setup failed. Exiting.")
        _cleanup()
        return 1

    try:
        _main_loop()
    except Exception as exc:
        logging.error("Unexpected error in main loop: %s", exc)
    finally:
        _cleanup()
        logging.info("Program terminated.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

