        raise

    for pin in PULLUP_PINS:
        try:
            _pullups.append(DigitalInputDevice(pin, pull_up=True, bounce_time=0.05))
        except Exception as exc:
            logging.error("Failed to initialize pull-up on BCM %d: %s", pin, exc)
            raise


def _read_sensor(sensor: gpiozero.DHT22, name: str) -> tuple[float | None, float | None]:
    """Return (temperature_c, humidity) or (None, None) on failure."""
    try:
        if sensor.temperature is None or sensor.humidity is None:
            return None, None
        return float(sensor.temperature), float(sensor.humidity)
    except Exception as exc:
        logging.error("Error reading %s: %s", name, exc)
        return None, None


def _open_vent() -> None:
    """Energize the solenoid for ACTUATION_DURATION seconds, logging results."""
    logging.info("Actuating solenoid...")
    try:
        _solenoid.on()
    except Exception as exc:
        logging.error("Failed to energize solenoid: %s", exc)
        return

    start = time.monotonic()
    try:
        while _running and (time.monotonic() - start) < ACTUATION_DURATION:
            if _limit_switch.is_active:
                logging.info("Limit switch triggered before completion.")
                return
            time.sleep(0.1)
    finally:
        try:
            _solenoid.off()
        except Exception as exc:
            logging.error("Failed to de-energize solenoid: %s", exc)
        logging.info("Solenoid de-energized.")


def _check_vent_open() -> bool:
    """Return True if the limit switch is currently active (vent fully open)."""
    try:
        return bool(_limit_switch.is_active)
    except Exception as exc:
        logging.error("Error reading limit switch: %s", exc)
        return False


def _main_loop() -> None:
    """Poll sensors and actuate the vent when conditions are met."""
    global _running
    last_temp1 = 25.0
    last_hum1 = 50.0
    last_temp2 = 25.0
    last_hum2 = 50.0

    while _running:
        temp1, hum1 = _read_sensor(_dht1, "DHT22_1")
        if temp1 is not None and hum1 is not None:
            last_temp1, last_hum1 = temp1, hum1
        else:
            logging.warning("Using last known values for DHT22_1: %.1fC, %.1f%%", last_temp1, last_hum1)

        temp2, hum2 = _read_sensor(_dht2, "DHT22_2")
        if temp2 is not None and hum2 is not None:
            last_temp2, last_hum2 = temp2, hum2
        else:
            logging.warning("Using last known values for DHT22_2: %.1fC, %.1f%%", last_temp2, last_hum2)

        avg_temp = (last_temp1 + last_temp2) / 2.0
        avg_hum = (last_hum1 + last_hum2) / 2.0

        logging.info("Avg Temp: %.1fC, Avg Humidity: %.1f%%", avg_temp, avg_hum)

        if avg_temp > MAX_TEMP and avg_hum < MIN_HUMIDITY:
            logging.info("Conditions met for vent opening.")
            if _check_vent_open():
                logging.info("Vent already fully open.")
            else:
                _open_vent()
        else:
            logging.info("Conditions not met for vent opening.")

        # Sleep in small increments so signals are caught promptly
        slept = 0.0
        while _running and slept < POLL_INTERVAL:
            time.sleep(0.5)
            slept += 0.5


def main() -> int:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _setup_gpio()
    except Exception:
        logging.error("GPIO setup failed. Exiting.")
        _cleanup()
        return 1

    try:
        _main_loop()
    except Exception as exc:
        logging.error("Unexpected error in main loop: %s", exc)
    finally:
        _cleanup()
        logging.info("Program terminated.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

