import time
import random
import logging
import signal
import sys

try:
    from gpiozero import AngularServo, Device
    from gpiozero.pins.pigpio import PiGPIOFactory
    try:
        from gpiozero.pins.lgpio import LGPIOFactory
        _USE_LGPIO = True
    except Exception:
        _USE_LGPIO = False
    _GPIOZERO_AVAILABLE = True
except Exception:
    _GPIOZERO_AVAILABLE = False

# Constants
SERVO_PIN_1 = 17
SERVO_PIN_2 = 18
PWM_FREQUENCY = 50
TEMP_MIN = 15
TEMP_MAX = 35
FAILURE_RATE = 0.10
MAX_CONSECUTIVE_FAILURES = 3
MOVEMENT_STEP = 5
MOVEMENT_DELAY = 0.1
LOG_FILE = "greenhouse_vent.log"

# Configure logging
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global state
pwm_1 = None
pwm_2 = None
servo_1 = None
servo_2 = None
factory = None
consecutive_failures = 0
running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    running = False


def cleanup():
    """Stop PWM and release GPIO resources."""
    global pwm_1, pwm_2, servo_1, servo_2
    if servo_1 is not None:
        try:
            servo_1.detach()
        except Exception:
            pass
    if servo_2 is not None:
        try:
            servo_2.detach()
        except Exception:
            pass
    if pwm_1 is not None:
        try:
            pwm_1.close()
        except Exception:
            pass
    if pwm_2 is not None:
        try:
            pwm_2.close()
        except Exception:
            pass
    try:
        Device.close()
    except Exception:
        pass
    logging.info("GPIO cleanup completed.")


def init_gpio():
    """Initialize GPIO and servos using gpiozero."""
    global pwm_1, pwm_2, servo_1, servo_2, factory

    if not _GPIOZERO_AVAILABLE:
        raise RuntimeError("gpiozero library is not available.")

    # Try PiGPIO factory first; fall back to lgpio if available
    for factory_name in ("pigpio", "lgpio" if _USE_LGPIO else None):
        if factory_name is None:
            continue
        try:
            if factory_name == "pigpio":
                factory = PiGPIOFactory()
            else:
                factory = LGPIOFactory()
            break
        except Exception as e:
            logging.warning(f"Failed to initialize {factory_name} factory: {e}")
            factory = None

    if factory is None:
        raise RuntimeError("Failed to initialize any GPIO factory.")

    try:
        servo_1 = AngularServo(
            SERVO_PIN_1,
            initial_angle=0,
            min_angle=0,
            max_angle=180,
            min_pulse_width=0.0005,
            max_pulse_width=0.0025,
            pin_factory=factory,
        )
        servo_2 = AngularServo(
            SERVO_PIN_2,
            initial_angle=0,
            min_angle=0,
            max_angle=180,
            min_pulse_width=0.0005,
            max_pulse_width=0.0025,
            pin_factory=factory,
        )
        pwm_1 = servo_1.pin.pwm_output(frequency=PWM_FREQUENCY)
        pwm_2 = servo_2.pin.pwm_output(frequency=PWM_FREQUENCY)
        pwm_1.value = 0.0
        pwm_2.value = 0.0
        logging.info("GPIO and servos initialized successfully.")
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        cleanup()
        raise


def generate_temperature():
    """Simulate a temperature reading with random fluctuations."""
    base_temp = random.uniform(TEMP_MIN, TEMP_MAX)
    fluctuation = random.uniform(-2, 2)
    return round(base_temp + fluctuation, 1)


def temperature_to_angle(temperature):
    """Map temperature to servo angle."""
    if temperature < 20:
        return 0
    elif 20 <= temperature < 25:
        return 45
    elif 25 <= temperature < 30:
        return 90
    elif 20 <= temperature < 35:
        return 135
    else:
        return 180


def move_servo(servo, target_angle):
    """Move servo to target angle in 5-degree steps."""
    global consecutive_failures
    try:
        current_angle = servo.angle
        if current_angle is None:
            current_angle = 0
        step = MOVEMENT_STEP if target_angle > current_angle else -MOVEMENT_STEP
        angle = int(current_angle)
        target_angle = int(target_angle)
        while angle != target_angle:
            angle += step
            if step > 0 and angle > target_angle:
                angle = target_angle
            elif step < 0 and angle < target_angle:
                angle = target_angle
            servo.angle = angle
            time.sleep(MOVEMENT_DELAY)
        consecutive_failures = 0
        return True
    except Exception as e:
        logging.error(f"Error moving servo: {e}")
        consecutive_failures += 1
        return False


def simulate_library_call(temperature, servo_pin):
    """Simulate the library's API call with a failure rate."""
    global consecutive_failures
    if random.random() < FAILURE_RATE:
        logging.error(f"Simulated library failure on pin {servo_pin} for temperature {temperature}")
        consecutive_failures += 1
        return False
    consecutive_failures = 0
    return True


def main():
    """Main program loop."""
    global running, consecutive_failures

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        init_gpio()
    except Exception as e:
        logging.critical(f"Initialization failed: {e}")
        sys.exit(1)

    try:
        while running:
            temperature = generate_temperature()
            logging.info(f"Simulated Temperature: {temperature}°C")

            angle_1 = temperature_to_angle(temperature)
            angle_2 = temperature_to_angle(temperature)

            if consecutive_failures < MAX_CONSECUTIVE_FAILURES:
                if simulate_library_call(temperature, SERVO_PIN_1):
                    move_servo(servo_1, angle_1)
                if simulate_library_call(temperature, SERVO_PIN_2):
                    move_servo(servo_2, angle_2)
            else:
                logging.warning("Switching to library call due to consecutive failures.")
                if simulate_library_call(temperature, SERVO_PIN_1):
                    servo_1.angle = angle_1
                if simulate_library_call(temperature, SERVO_PIN_2):
                    servo_2.angle = angle_2

            time.sleep(5)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

