import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591


def main():
    # Initialize I2C bus on GPIO3 (SCL) and GPIO2 (SDA)
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return

    # Initialize TCA9548A multiplexer
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return

    # Initialize BME280 sensor on channel 0
    try:
        bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0], address=0x76)
    except Exception as e:
        print(f"Error initializing BME280 sensor on channel 0: {e}")
        bme280_sensor = None

    # Initialize TSL2591 sensor on channel 1
    try:
        tsl2591_sensor = adafruit_tsl2591.TSL2591(multiplexer[1])
    except Exception as e:
        print(f"Error initializing TSL2591 sensor on channel 1: {e}")
        tsl2591_sensor = None

    # Main loop for reading sensor data
    try:
        while True:
            # Read temperature, humidity, and pressure from BME280
            if bme280_sensor is not None:
                try:
                    temperature = bme280_sensor.temperature
                    humidity = bme280_sensor.humidity
                    pressure = bme280_sensor.pressure
                    print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Pressure: {pressure:.2f} hPa")
                except Exception as e:
                    print(f"Error reading BME280 sensor: {e}")
            else:
                print("BME280 sensor not available.")

            # Read light intensity from TSL2591
            if tsl2591_sensor is not None:
                try:
                    light_intensity = tsl2591_sensor.lux
                    print(f"Light Intensity: {light_intensity:.2f} lux")
                except Exception as e:
                    print(f"Error reading TSL2591 sensor: {e}")
            else:
                print("TSL2591 sensor not available.")

            # Wait for 2 seconds before the next reading
            time.sleep(2)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")


if __name__ == "__main__":
    main()

