import asyncio
import json
import logging
import random
import signal
import sys
import time
from collections import deque
from typing import Deque, Optional

import adafruit_dht
import board

CONFIG_FILE = "config.json"

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class GreenhouseMonitor:
    def __init__(self, config: dict) -> None:
        self.config = config
        self.dht_pin = board.D4
        self.dht_device: Optional[adafruit_dht.DHT22] = None
        self.temperature_readings: Deque[float] = deque(maxlen=5)
        self.humidity_readings: Deque[float] = deque(maxlen=5)
        self.last_webhook_failure_time: Optional[float] = None
        self._shutdown = False

    async def initialize(self) -> None:
        try:
            self.dht_device = adafruit_dht.DHT22(self.dht_pin, use_pulseio=False)
            logging.info("DHT22 sensor initialized on BCM pin 4.")
        except Exception as e:
            logging.error(f"Failed to initialize DHT22 sensor: {e}")
            raise

    async def read_sensor_data(self) -> tuple[Optional[float], Optional[float]]:
        if self.dht_device is None:
            return None, None
        try:
            temperature = self.dht_device.temperature
            humidity = self.dht_device.humidity
            if temperature is None or humidity is None:
                raise RuntimeError("Sensor returned None for temperature or humidity.")
            if not (-40.0 <= temperature <= 80.0):
                raise RuntimeError(f"Temperature out of range: {temperature}")
            if not (0.0 <= humidity <= 100.0):
                raise RuntimeError(f"Humidity out of range: {humidity}")
            return temperature, humidity
        except RuntimeError as e:
            logging.warning(f"Sensor read error: {e}. Generating simulated data.")
            return random.uniform(20.0, 30.0), random.uniform(60.0, 80.0)
        except Exception as e:
            logging.error(f"Unexpected error reading sensor: {e}")
            return None, None

    async def calculate_moving_average(self) -> tuple[Optional[float], Optional[float]]:
        if not self.temperature_readings or not self.humidity_readings:
            return None, None
        return (
            sum(self.temperature_readings) / len(self.temperature_readings),
            sum(self.humidity_readings) / len(self.humidity_readings),
        )

    async def send_webhook(self, temperature: float, humidity: float) -> bool:
        payload = {
            "temperature": temperature,
            "humidity": humidity,
            "timestamp": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        }
        data = json.dumps(payload).encode("utf-8")
        headers = {"Content-Type": "application/json"}
        retries = [1, 3, 9]

        for i, delay in enumerate(retries):
            try:
                import urllib.request
                req = urllib.request.Request(
                    self.config["webhook_url"],
                    data=data,
                    headers=headers,
                    method="POST",
                )
                with urllib.request.urlopen(req, timeout=10) as resp:
                    if 200 <= resp.status < 300:
                        logging.info("Webhook sent successfully.")
                        return True
                    else:
                        logging.error(f"Webhook returned status code: {resp.status}")
            except Exception as e:
                logging.error(f"Webhook request failed (attempt {i + 1}/{len(retries)}): {e}")
            if i < len(retries) - 1:
                await asyncio.sleep(delay)
        logging.error("Webhook failed after all retries.")
        return False

    async def cleanup(self) -> None:
        logging.info("Cleaning up resources.")
        if self.dht_device is not None:
            try:
                self.dht_device.exit()
            except Exception:
                pass
            self.dht_device = None

    async def run(self) -> None:
        try:
            await self.initialize()
        except Exception:
            logging.critical("Initialization failed. Exiting.")
            await self.cleanup()
            return

        while not self._shutdown:
            try:
                temperature, humidity = await self.read_sensor_data()

                if temperature is not None and humidity is not None:
                    self.temperature_readings.append(temperature)
                    self.humidity_readings.append(humidity)
                    avg_temp, avg_humidity = await self.calculate_moving_average()
                    if avg_temp is not None and avg_humidity is not None:
                        logging.info(
                            f"Temperature: {avg_temp:.2f}°C, Humidity: {avg_humidity:.2f}%"
                        )
                        await self.send_webhook(avg_temp, avg_humidity)
                    else:
                        logging.warning("Not enough data for moving average.")
                else:
                    logging.warning("Failed to read sensor data.")

                if self.last_webhook_failure_time is not None:
                    if time.time() - self.last_webhook_failure_time >= 300:
                        self.last_webhook_failure_time = None
                        logging.info("Resuming normal operation.")
                    else:
                        logging.warning("Pausing sensor acquisition due to webhook failure.")
                        await asyncio.sleep(60)
                        continue

                await asyncio.sleep(60)

            except asyncio.CancelledError:
                break
            except Exception as e:
                logging.error(f"Unexpected error in main loop: {e}")
                await asyncio.sleep(60)

        await self.cleanup()


def load_config(config_file: str) -> dict:
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
        sys.exit(1)
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in configuration file: {e}")
        sys.exit(1)


def main() -> None:
    config = load_config(CONFIG_FILE)
    monitor = GreenhouseMonitor(config)

    def signal_handler(signum, frame):
        logging.info(f"Received signal {signum}, shutting down.")
        monitor._shutdown = True

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        asyncio.run(monitor.run())
    except KeyboardInterrupt:
        pass


