running = True

def signal_handler(sig, frame):
    global running
    logger.info("Shutdown signal received.")
    running = False

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker.")
    else:
        logger.error(f"Failed to connect to MQTT broker. Reason code: {reason_code}")

def on_disconnect(client, userdata, flags, reason_code, properties):
    logger.warning(f"Disconnected from MQTT broker. Reason code: {reason_code}")

def configure_mqtt_client():
    try:
        client = mqtt.Client(
            callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
            protocol=mqtt.MQTTv5
        )
        if config.mqttusername and config.mqttpassword:
            client.username_pw_set(config.mqttusername, config.mqttpassword)
        if config.mqttssl:
            client.tls_set(cert_reqs=ssl.CERT_REQUIRED)
        client.on_connect = on_connect
        client.on_disconnect = on_disconnect
        return client
    except Exception as e:
        logger.error(f"Error configuring MQTT client: {e}")
        return None

def connect_to_mqtt_broker(client):
    try:
        client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
        client.loop_start()
        return True
    except Exception as e:
        logger.error(f"Error connecting to MQTT broker: {e}")
        return False

def send_homie_discovery(client):
    base_topic = f"homie/{config.homieclientid}"
    try:
        client.publish(f"{base_topic}/$homie", "4.0", qos=1, retain=True)
        client.publish(f"{base_topic}/$name", config.homieclientname, qos=1, retain=True)
        client.publish(f"{base_topic}/$nodes", config.homienodes, qos=1, retain=True)
        node_topic = f"{base_topic}/{config.homienodes}"
        client.publish(f"{node_topic}/$name", "DHT22 Sensor", qos=1, retain=True)
        client.publish(f"{node_topic}/$properties", "temperature,humidity", qos=1, retain=True)
        client.publish(f"{node_topic}/temperature/$name", "Temperature", qos=1, retain=True)
        client.publish(f"{node_topic}/temperature/$unit", "\u00B0C", qos=1, retain=True)
        client.publish(f"{node_topic}/humidity/$name", "Humidity", qos=1, retain=True)
        client.publish(f"{node_topic}/humidity/$unit", "%", qos=1, retain=True)
        logger.info("Homie discovery messages sent.")
    except Exception as e:
        logger.error(f"Error sending Homie discovery messages: {e}")

def read_dht22_sensor(sensor):
    for attempt in range(3):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                logger.warning(f"DHT22 returned None on attempt {attempt + 1}")
        except RuntimeError as e:
            logger.warning(f"DHT22 read error on attempt {attempt + 1}: {e}")
        except Exception as e:
            logger.error(f"Unexpected DHT22 error on attempt {attempt + 1}: {e}")
        if attempt < 2:
            time.sleep(2)
    return None, None

def publish_sensor_data(client, temperature, humidity):
    try:
        base_topic = f"homie/{config.homieclientid}/{config.homienodes}"
        client.publish(f"{base_topic}/temperature", f"{temperature:.1f}", qos=1, retain=True)
        client.publish(f"{base_topic}/humidity", f"{humidity:.1f}", qos=1, retain=True)
        logger.info(f"Published: Temperature={temperature:.1f}\u00B0C, Humidity={humidity:.1f}%")
    except Exception as e:
        logger.error(f"Error publishing sensor data: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        Device.pin_factory = LGPIOFactory()
    except Exception as e:
        logger.error(f"Failed to initialize GPIO factory: {e}")
        sys.exit(1)

    try:
        sensor = DHT22(D4, use_pulseio=False)
    except Exception as e:
        logger.error(f"Failed to initialize DHT22 sensor: {e}")
        sys.exit(1)

    mqtt_client = configure_mqtt_client()
    if not mqtt_client:
        sys.exit(1)

    if not connect_to_mqtt_broker(mqtt_client):
        sys.exit(1)

    send_homie_discovery(mqtt_client)
    time.sleep(2)

    try:
        while running:
            if not mqtt_client.is_connected():
                logger.warning("MQTT client is disconnected. Attempting to reconnect...")
                if not connect_to_mqtt_broker(mqtt_client):
                    time.sleep(5)
                    continue
            temperature, humidity = read_dht22_sensor(sensor)
            if temperature is not None and humidity is not None:
                publish_sensor_data(mqtt_client, temperature, humidity)
            else:
                logger.error("Failed to read sensor data after multiple attempts.")
            for _ in range(config.publishtime):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        logger.info("Cleaning up resources...")
        try:
            sensor.exit()
        except Exception:
            pass
        try:
            mqtt_client.loop_stop()
            mqtt_client.disconnect()
        except Exception:
            pass
        logger.info("Program terminated.")

if __name__ == "__main__":
    main()

