import time
import board
import busio
import adafruit_bmp280

# Constants
I2C_BUS = 1
I2C_SDA_PIN = board.D2
I2C_SCL_PIN = board.D3
BASELINE_DURATION = 10
BASELINE_INTERVAL = 1
READ_INTERVAL = 1
MAX_BASELINE_READS = 100  # Guard against infinite loop if sensor is unresponsive


def initialize_i2c():
    """Initializes the I2C bus using board.I2C()."""
    try:
        i2c_bus = busio.I2C(I2C_SCL_PIN, I2C_SDA_PIN)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_bmp280(i2c_bus):
    """Initializes the BMP280 sensor."""
    try:
        bmp280_sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=0x76)
        return bmp280_sensor
    except ValueError:
        print("Error: BMP280 sensor not found on the I2C bus.")
        return None
    except Exception as e:
        print(f"Error initializing BMP280 sensor: {e}")
        return None


def get_baseline_pressure(bmp280_sensor, duration=BASELINE_DURATION, interval=BASELINE_INTERVAL):
    """Gets the baseline pressure for a specified duration, excluding the first two readings."""
    print("Calibrating baseline pressure...")
    pressure_readings = []
    start_time = time.monotonic()

    while time.monotonic() - start_time < duration:
        try:
            pressure = bmp280_sensor.pressure
            pressure_readings.append(pressure)
            time.sleep(interval)
        except OSError as e:
            print(f"Error reading pressure during calibration: {e}")
            time.sleep(interval)
        except Exception as e:
            print(f"Unexpected error reading pressure during calibration: {e}")
            time.sleep(interval)

        if len(pressure_readings) > MAX_BASELINE_READS:
            print("Error: Maximum baseline reads reached. Exiting calibration.")
            return None

    if len(pressure_readings) < 3:
        print("Error: Not enough valid pressure readings for calibration.")
        return None

    # Exclude the first two readings to avoid early sensor instability
    valid_readings = pressure_readings[2:]
    if not valid_readings:
        print("Error: No valid pressure readings after filtering.")
        return None

    baseline_pressure = sum(valid_readings) / len(valid_readings)
    print(f"Baseline pressure: {baseline_pressure:.2f} hPa")
    return baseline_pressure


def read_altitude(bmp280_sensor):
    """Reads the altitude from the BMP280 sensor."""
    try:
        altitude = bmp280_sensor.altitude
        return altitude
    except OSError as e:
        print(f"Error reading altitude: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading altitude: {e}")
        return None


def main():
    """Main function to run the altitude monitoring program."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    bmp280_sensor = initialize_bmp280(i2c_bus)
    if bmp280_sensor is None:
        return

    baseline_pressure = get_baseline_pressure(bmp280_sensor)
    if baseline_pressure is None:
        return

    try:
        while True:
            altitude = read_altitude(bmp280_sensor)
            if altitude is not None:
                print(f"Relative altitude: {altitude:.2f} meters")
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("\nExiting program.")


if __name__ == "__main__":
    main()

