            print(f"Error reading pressure during calibration: {e}")
            time.sleep(interval)
        except Exception as e:
            print(f"Unexpected error reading pressure during calibration: {e}")
            time.sleep(interval)

        if len(pressure_readings) > MAX_BASELINE_READS:
            print("Error: Maximum baseline reads reached. Exiting calibration.")
            return None

    if len(pressure_readings) < 3:
        print("Error: Not enough valid pressure readings for calibration.")
        return None

    # Exclude the first two readings to avoid early sensor instability
    valid_readings = pressure_readings[2:]
    if not valid_readings:
        print("Error: No valid pressure readings after filtering.")
        return None

    baseline_pressure = sum(valid_readings) / len(valid_readings)
    print(f"Baseline pressure: {baseline_pressure:.2f} hPa")
    return baseline_pressure


