    """Reads the altitude from the BMP280 sensor."""
    try:
        altitude = bmp280_sensor.altitude
        return altitude
    except OSError as e:
        print(f"Error reading altitude: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading altitude: {e}")
        return None


def main():
    """Main function to run the altitude monitoring program."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

