    line = f"{timestamp} - Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%, Fan: {fan_state}\n"
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as fh:
            fh.write(line)
    except OSError as exc:
        print(f"[ERROR] Failed to write log: {exc}", file=sys.stderr)


def main():
