    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = gpiozero.DHT11(DHT_PIN, pull_up=False)
        fan = gpiozero.OutputDevice(FAN_PIN, active_high=True, initial_value=False)
    except Exception as exc:
        print(f"[ERROR] GPIO initialization failed: {exc}", file=sys.stderr)
