                print(f"[ERROR] Skipping reading {i + 1}/{NUM_READINGS}: sensor data unavailable.", file=sys.stderr)

            if i < NUM_READINGS - 1 and _running:
                time.sleep(READ_INTERVAL)
    finally:
        if fan is not None:
            try:
                fan.off()
                fan.close()
            except Exception:
                pass
        if sensor is not None:
            try:
                sensor.close()
            except Exception:
                pass
        print("[INFO] GPIO cleanup completed.")


if __name__ == "__main__":
    main()

