import time
import logging
import signal
import sys

try:
    from smbus2 import SMBus
except ImportError:
    from smbus import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class DHT20:
    """Driver for the Aosong DHT20 temperature/humidity sensor over I2C."""

    I2C_BUS = 1
    I2C_ADDR = 0x60
    STATUS_REG = 0x00
    DATA_REG = 0x00
    RESET_REG = 0x04
    RESET_CMD = 0x14
    POWER_ON_DELAY = 0.5
    STATUS_POLL_DELAY = 0.08
    STATUS_POLL_ATTEMPTS = 10
    MEASURE_ATTEMPTS = 5
    MEASURE_RETRY_DELAY = 0.01
    MIN_MEASUREMENT_INTERVAL = 2.0

    def __init__(self, i2c_bus=I2C_BUS, i2c_address=I2C_ADDR):
        self._i2c_bus = i2c_bus
        self._i2c_address = i2c_address
        self._last_measurement_time = 0.0
        self._bus = None
        self._closed = False

    def begin(self):
        try:
            self._bus = SMBus(self._i2c_bus)
        except OSError as e:
            logging.error(f"Failed to open I2C bus {self._i2c_bus}: {e}")
            return False

        try:
            self._bus.write_byte_data(self._i2c_address, self.RESET_REG, self.RESET_CMD)
        except OSError as e:
            logging.error(f"Failed to send reset command to DHT20: {e}")
            self.close()
            return False

        time.sleep(self.POWER_ON_DELAY)
        return True

    def _read_status(self):
        try:
            return self._bus.read_byte_data(self._i2c_address, self.STATUS_REG)
        except OSError as e:
            logging.error(f"I2C read error reading status: {e}")
            return None

    def _read_data(self):
        try:
            return self._bus.read_i2c_block_data(self._i2c_address, self.DATA_REG, 7)
        except OSError as e:
            logging.error(f"I2C read error reading data: {e}")
            return None

    def _write_data(self, data):
        try:
            self._bus.write_i2c_block_data(self._i2c_address, self.DATA_REG, data)
            return True
        except OSError as e:
            logging.error(f"I2C write error: {e}")
            return False

    def _calculate_crc8(self, data):
        crc = 0
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _wait_for_measurement_ready(self):
        for _ in range(self.STATUS_POLL_ATTEMPTS):
            status = self._read_status()
            if status is None:
                return False
            if (status & 0x80) == 0:
                return True
            time.sleep(self.STATUS_POLL_DELAY)
        logging.warning("DHT20 measurement not ready after timeout.")
        return False

    def get_temperature_and_humidity(self):
        if time.time() - self._last_measurement_time < self.MIN_MEASUREMENT_INTERVAL:
            logging.info("Returning cached temperature and humidity.")
            return self._last_temperature, self._last_humidity, False

        for attempt in range(self.MEASURE_ATTEMPTS):
            if not self._wait_for_measurement_ready():
                time.sleep(self.MEASURE_RETRY_DELAY)
                continue

            data = self._read_data()
            if data is None or len(data) < 7:
                time.sleep(self.MEASURE_RETRY_DELAY)
                continue

            if self._calculate_crc8(data[:6]) != data[6]:
                logging.warning("CRC mismatch. Retrying measurement.")
                time.sleep(self.MEASURE_RETRY_DELAY)
                continue

            humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
            temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

            humidity = (humidity_raw / 2**20) * 100.0
            temperature = (temperature_raw / 2**20) * 200.0 - 50.0

            self._last_temperature = temperature
            self._last_humidity = humidity
            self._last_measurement_time = time.time()
            return temperature, humidity, False

        logging.error("Failed to get valid temperature and humidity after multiple attempts.")
        return None, None, True

    def close(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self._bus = None
        self._closed = True

    def __enter__(self):
        if not self.begin():
            raise RuntimeError("Failed to initialize DHT20 sensor.")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()
        return False


def main():
    sensor = DHT20()
    running = True

    def signal_handler(signum, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        if not sensor.begin():
            print("Failed to initialize DHT20 sensor. Check I2C wiring and address.")
            sys.exit(0)

        while running:
            temperature, humidity, error = sensor.get_temperature_and_humidity()
            if error:
                print("Error reading sensor data.")
            else:
                print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
            time.sleep(2.0)
    except KeyboardInterrupt:
        pass
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        sensor.close()


if __name__ == "__main__":
    main()

