        logger.warning('Unexpected MQTT disconnect, reason code: %s', reason_code)
    else:
        logger.info('Disconnected from MQTT broker')


def connect_mqtt():
    global mqtt_client
    try:
        mqtt_client = mqtt.Client(
            mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
            protocol=mqtt.MQTTv5
        )
        if getattr(config, 'mqttusername', None) and getattr(config, 'mqttpassword', None):
            mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)
        mqtt_client.on_connect = on_connect
        mqtt_client.on_disconnect = on_disconnect
        mqtt_client.will_set(
            f'homie/{config.homieclientid}/$state', 'lost',
            retain=getattr(config, 'mqttretainmessage', True),
            qos=getattr(config, 'mqttqos', 1)
        )
        mqtt_client.connect(config.mqttbroker, port=config.mqttport, keepalive=30)
        mqtt_client.loop_start()
        time.sleep(1)
        if not mqtt_client.is_connected():
            raise ConnectionError('MQTT broker did not accept the connection')
    except Exception as e:
        logger.error('MQTT connection error: %s', e)
        raise


def publish_message(topic, payload):
    if mqtt_client is None or not mqtt_client.is_connected():
        logger.warning('MQTT client not connected, cannot publish to %s', topic)
        return
    full_topic = f'homie/{config.homieclientid}/{topic}'
    try:
        info = mqtt_client.publish(
            full_topic, str(payload),
            retain=getattr(config, 'mqttretainmessage', True),
            qos=getattr(config, 'mqttqos', 1)
        )
        info.wait_for_publish(timeout=5)
        logger.debug('Published to %s: %s', full_topic, payload)
    except Exception as e:
        logger.error('Error publishing to %s: %s', full_topic, e)


def read_dht22():
    global dht_sensor
    if dht_sensor is None:
        try:
            dht_sensor = DHT22(config.dhtgpiopin, use_pulseio=False)
        except Exception as e:
            logger.error('Failed to initialize DHT22 on pin %s: %s', config.dhtgpiopin, e)
            raise
    try:
        temperature = dht_sensor.temperature
        humidity = dht_sensor.humidity
        if temperature is None or humidity is None:
            raise RuntimeError('DHT22 returned None for temperature or humidity')
        return round(temperature, 1), round(humidity, 1)
    except RuntimeError as e:
        logger.warning('DHT22 read error (retrying): %s', e)
        try:
            dht_sensor.exit()
        except Exception:
            pass
        dht_sensor = None
        raise
    except Exception as e:
        logger.error('Unexpected DHT22 error: %s', e)
        try:
            dht_sensor.exit()
        except Exception:
            pass
        dht_sensor = None
        raise


def cleanup():
    global mqtt_client, dht_sensor
    logger.info('Cleaning up resources...')
    if mqtt_client is not None:
        try:
            mqtt_client.loop_stop()
            if mqtt_client.is_connected():
                mqtt_client.publish(f'homie/{config.homieclientid}/$state', 'lost', retain=True, qos=1)
                mqtt_client.disconnect()
        except Exception as e:
            logger.error('Error during MQTT cleanup: %s', e)
    if dht_sensor is not None:
        try:
            dht_sensor.exit()
        except Exception as e:
            logger.error('Error during DHT22 cleanup: %s', e)
    try:
        Device.pin_factory.close()
    except Exception:
        pass
    logger.info('Cleanup complete.')


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        connect_mqtt()
        last_read_time = 0
        while running:
            current_time = time.time()
            if current_time - last_read_time >= config.publishtime:
                try:
                    temperature, humidity = read_dht22()
                    publish_message(f'{config.homienodes}/temperature', temperature)
                    publish_message(f'{config.homienodes}/humidity', humidity)
                    last_read_time = current_time
                except RuntimeError:
                    logger.warning('DHT22 read failed, will retry next cycle')
                except Exception as e:
                    logger.error('Error in main loop: %s', e)
            time.sleep(0.5)
    except Exception as e:
        logger.error('Fatal error: %s', e)
    finally:
        cleanup()


if __name__ == '__main__':
    main()

