import serial
import time
import signal
import sys
import logging
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
LOG_FILE = '/home/pi/sensor_log.txt'
TEMP_THRESHOLD = 28.0
HUMIDITY_THRESHOLD = 65.0
ALERT_DURATION = 5

running = True

def signal_handler(signum, frame):
    global running
    running = False

def parse_reading(line):
    line = line.strip()
    if not line:
        return None, None
    parts = line.split(',')
    if len(parts) != 2:
        return None, None
    try:
        temperature = float(parts[0])
        humidity = float(parts[1])
    except ValueError:
        return None, None
    return temperature, humidity

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        alert_pin = OutputDevice(17)
    except Exception as e:
        print(f"Failed to initialize GPIO17: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        alert_pin.close()
        sys.exit(1)

    logging.basicConfig(
        filename=LOG_FILE,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s'
    )

    try:
        while running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                logging.error(f"Serial read error: {e}")
                time.sleep(1)
                continue

            if not raw:
                continue

            try:
                line = raw.decode('ascii', errors='replace')
            except Exception as e:
                logging.error(f"Decode error: {e}")
                continue

            temperature, humidity = parse_reading(line)
            if temperature is None or humidity is None:
                logging.warning(f"Malformed data: {line!r}")
                continue

            logging.info(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")

            if temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
                alert_pin.on()
                logging.warning(
                    f"Threshold exceeded! Temp: {temperature:.2f}°C, "
                    f"Humidity: {humidity:.2f}%"
                )
                time.sleep(ALERT_DURATION)
                alert_pin.off()
    finally:
        try:
            alert_pin.off()
            alert_pin.close()
        except Exception:
            pass
        try:
            ser.close()
        except Exception:
            pass
        print("Resources cleaned up. Exiting.")

if __name__ == '__main__':
    main()

