import signal
import sys
import time
import logging

from ina219 import INA219, DeviceRangeError
from ups import UPS

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

_running = True


def _signal_handler(signum, frame):
    global _running
    logging.info(f"Received signal {signum}; shutting down.")
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ina_supply = None
    ina_battery = None
    ups = None

    try:
        ina_supply = INA219(shunt_resistor=0.00725, busnum=1, address=0x40)
        ina_supply.configure()
        logging.info("Supply INA219 initialised at 0x40.")
    except Exception as exc:
        logging.error(f"Failed to initialise supply INA219 at 0x40: {exc}")

    try:
        ina_battery = INA219(shunt_resistor=0.005, busnum=1, address=0x41)
        ina_battery.configure()
        logging.info("Battery INA219 initialised at 0x41.")
    except Exception as exc:
        logging.error(f"Failed to initialise battery INA219 at 0x41: {exc}")

    try:
        ups = UPS()
        logging.info("UPS controller initialised.")
    except Exception as exc:
        logging.error(f"Failed to initialise UPS controller: {exc}")

    while _running:
        if ina_supply is not None:
            try:
                voltage = ina_supply.voltage()
                current = ina_supply.current()
                print(f"Supply: {voltage:.3f} V, {current:.3f} mA")
            except DeviceRangeError:
                logging.error("Supply INA219 current out of range.")
            except Exception as exc:
                logging.error(f"Error reading supply INA219: {exc}")

        if ina_battery is not None:
            try:
                voltage = ina_battery.voltage()
                current = ina_battery.current()
                print(f"Battery: {voltage:.3f} V, {current:.3f} mA")
            except DeviceRangeError:
                logging.error("Battery INA219 current out of range.")
            except Exception as exc:
                logging.error(f"Error reading battery INA219: {exc}")

        if ups is not None:
            try:
                proc_mV = ups.get_proc_voltage()
                battery_port_mV = ups.get_battery_port_voltage()
                temp_c = ups.get_temperature()
                capacity_percent = ups.get_battery_capacity()
                print(
                    f"UPS: Proc {proc_mV}mV, Battery Port {battery_port_mV}mV, "
                    f"Temp {temp_c}C, Capacity {capacity_percent}%"
                )
            except Exception as exc:
                logging.error(f"Error reading UPS controller: {exc}")

        time.sleep(2)

    logging.info("Clean exit.")


if __name__ == "__main__":
    main()

