import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1

TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

running = True

def signal_handler(sig, frame):
    global running
    running = False

def read_sensor_data(serial_connection):
    try:
        raw = serial_connection.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        parts = line.split(',')
        if len(parts) != 2:
            return None
        temperature = float(parts[0])
        humidity = float(parts[1])
        return temperature, humidity
    except ValueError:
        return None
    except serial.SerialException:
        return None

def send_data_to_serial(serial_connection, temperature, humidity):
    try:
        message = f'{temperature},{humidity}\n'
        serial_connection.write(message.encode('ascii'))
        serial_connection.flush()
    except serial.SerialException:
        pass

def check_thresholds(temperature, humidity):
    if temperature > TEMPERATURE_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
        print('Alert: Temperature or humidity exceeded threshold!')

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_connection = None
    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            timeout=READ_TIMEOUT
        )
        print(f'Connected to {SERIAL_PORT} at {BAUD_RATE} baud.')

        while running:
            data = read_sensor_data(serial_connection)
            if data is not None:
                temperature, humidity = data
                print(f'Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%')
                send_data_to_serial(serial_connection, temperature, humidity)
                check_thresholds(temperature, humidity)
            time.sleep(1)

    except serial.SerialException as e:
        print(f'Serial port error: {e}', file=sys.stderr)
    except Exception as e:
        print(f'Unexpected error: {e}', file=sys.stderr)
    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print('Serial port closed.')

if __name__ == '__main__':
    main()

