#!/usr/bin/env python3
"""
Raspberry Pi LED toggle program.

Hardware:
  - LED + 330 ohm resistor on GPIO17 (BCM)

Behavior:
  - Initial state: False
  - 'y'  → toggle → print current state
  - 'n'  → toggle → print current state
  - 'q'  → exit   → print "Exiting program."
  - any other input → print "Invalid input"
  - Ctrl-C / SIGINT → clean shutdown
  - any GPIO setup / runtime error → clean shutdown
"""

import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.", file=sys.stderr)
    sys.exit(1)

LED_PIN = 17
led_state = False


def cleanup_gpio() -> None:
    """Drive the LED low and release GPIO resources."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass


def main() -> None:
    global led_state

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as exc:
        print(f"Error: Failed to initialize GPIO: {exc}", file=sys.stderr)
        cleanup_gpio()
        sys.exit(1)

    try:
        while True:
            try:
                user_input = input("Press 'y' to turn the light on, 'n' to turn it off, or 'q' to quit: ").strip().lower()
            except EOFError:
                print("\nExiting program.")
                break

            if user_input == 'y':
                led_state = not led_state
                GPIO.output(LED_PIN, GPIO.HIGH if led_state else GPIO.LOW)
                print(f"The light is now {'on' if led_state else 'off'}")
            elif user_input == 'n':
                led_state = not led_state
                GPIO.output(LED_PIN, GPIO.HIGH if led_state else GPIO.LOW)
                print(f"The light is now {'on' if led_state else 'off'}")
            elif user_input == 'q':
                print("Exiting program.")
                break
            else:
                print("Invalid input")

            time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as exc:
        print(f"\nError: {exc}", file=sys.stderr)
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

