    global _running
    _running = False


def _init_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in SENSOR_PINS:
        try:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        except Exception as exc:
            print(f"Error: failed to initialize GPIO{pin} as input: {exc}")
            GPIO.cleanup()
            sys.exit(1)


