    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _init_gpio()

    print(f"Monitoring sensors on GPIO pins {SENSOR_PINS} (active-high, pull-up).")
    print(f"Polling interval: {POLL_INTERVAL_S}s. Press Ctrl+C to exit.")

