import logging
import signal
import sys
import time

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PIN = 17
HIGH_DURATION = 0.2
LOW_DURATION = 0.2

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _write(pin, value):
    try:
        import RPi.GPIO as GPIO
    except ImportError:
        logging.error("RPi.GPIO is not available; cannot write to GPIO %d.", pin)
        raise
    try:
        GPIO.output(pin, value)
    except Exception as exc:
        logging.error("Failed to write GPIO %d: %s", pin, exc)
        raise


def main():
    global _running
    _running = True

    try:
        import RPi.GPIO as GPIO
    except ImportError:
        logging.error("RPi.GPIO is not available on this platform.")
        sys.exit(1)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIN, GPIO.OUT, initial=GPIO.LOW)
        logging.info("GPIO %d configured as output (initial LOW).", PIN)
    except Exception as exc:
        logging.error("GPIO setup failed on pin %d: %s", PIN, exc)
        sys.exit(1)

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        while _running:
            _write(PIN, GPIO.HIGH)
            logging.info("GPIO %d HIGH", PIN)
            time.sleep(HIGH_DURATION)
            if not _running:
                break
            _write(PIN, GPIO.LOW)
            logging.info("GPIO %d LOW", PIN)
            time.sleep(LOW_DURATION)
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received; shutting down.")
    except Exception as exc:
        logging.error("Runtime error: %s", exc)
    finally:
        try:
            _write(PIN, GPIO.LOW)
            logging.info("GPIO %d set to LOW before cleanup.", PIN)
        except Exception:
            pass
        try:
            GPIO.cleanup()
            logging.info("GPIO cleanup completed.")
        except Exception as exc:
            logging.error("GPIO cleanup failed: %s", exc)


if __name__ == "__main__":
    main()

