import sys
import time
import signal
import threading
import traceback

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

try:
    import DOG
except ImportError:
    DOG = None

DEFAULT_LOG_FILE = "data.log"


class DataLogger:
    """
    A class to manage data logging and interaction with the DOG device.
    """

    def __init__(self, log_file_path=DEFAULT_LOG_FILE):
        self.log_file_path = log_file_path
        self.is_running = False
        self.receive_thread = None
        self._shutdown_requested = False
        self._lock = threading.Lock()

        if GPIO is not None:
            try:
                GPIO.setmode(GPIO.BCM)
                GPIO.setwarnings(False)
            except Exception as e:
                print(f"Warning: GPIO initialization failed: {e}", file=sys.stderr)
                GPIO = None

    def _signal_handler(self, signum, frame):
        print(f"\nSignal {signum} received. Shutting down...")
        self._shutdown_requested = True
        self.stop()
        self.cleanup()
        sys.exit(0)

    def start(self, filename):
        """Starts the data logging process."""
        try:
            with self._lock:
                if self.is_running:
                    print("Data logging is already running.")
                    return

                self.log_file_path = filename
                self.is_running = True
                self._shutdown_requested = False

            try:
                with open(self.log_file_path, "w") as log_file:
                    pass
            except IOError as e:
                print(f"Error creating log file '{self.log_file_path}': {e}", file=sys.stderr)
                self.is_running = False
                return

            self.receive_thread = threading.Thread(target=self._receive_and_log, daemon=True)
            self.receive_thread.start()
            print(f"Data logging started. Logging to: {self.log_file_path}")

        except Exception as e:
            print(f"Error starting data logging: {e}", file=sys.stderr)
            traceback.print_exc()
            self.is_running = False

    def _receive_and_log(self):
        """Receives data from the DOG device and logs it to a file."""
        while self.is_running and not self._shutdown_requested:
            try:
                if DOG is not None:
                    data = DOG.receive()
                    if data is not None:
                        try:
                            with open(self.log_file_path, "a") as log_file:
                                log_file.write(str(data) + "\n")
                                log_file.flush()
                        except IOError as e:
                            print(f"Error writing to log file: {e}", file=sys.stderr)
                time.sleep(0.1)
            except Exception as e:
                print(f"Error in data reception loop: {e}", file=sys.stderr)
                traceback.print_exc()
                self.is_running = False
                break

    def stop(self):
        """Stops the data logging process."""
        with self._lock:
            if not self.is_running:
                return
            self.is_running = False

        if self.receive_thread and self.receive_thread.is_alive():
            self.receive_thread.join(timeout=2.0)
            if self.receive_thread.is_alive():
                print("Warning: receive thread did not terminate cleanly.", file=sys.stderr)
        self.receive_thread = None

        if DOG is not None:
            try:
                DOG.stop()
            except Exception as e:
                print(f"Error stopping DOG device: {e}", file=sys.stderr)

        print("Data logging stopped.")

    def send_data(self, data):
        """Sends data using the DOG device."""
        if DOG is None:
            print("Error: DOG library not available.", file=sys.stderr)
            return
        try:
            DOG.send(data)
            print(f"Sent data: {data}")
        except Exception as e:
            print(f"Error sending data: {e}", file=sys.stderr)

    def write_to_log(self, data):
        """Writes data directly to the log file."""
        try:
            with open(self.log_file_path, "a") as log_file:
                log_file.write(str(data) + "\n")
                log_file.flush()
            print(f"Wrote to log: {data}")
        except IOError as e:
            print(f"Error writing to log file: {e}", file=sys.stderr)

    def display_log(self):
        """Displays the contents of the log file."""
        try:
            with open(self.log_file_path, "r") as log_file:
                print(log_file.read())
        except FileNotFoundError:
            print(f"Log file '{self.log_file_path}' not found.")
        except IOError as e:
            print(f"Error reading log file: {e}", file=sys.stderr)

    def cleanup(self):
        """Cleans up resources."""
        self.stop()
        if GPIO is not None:
            try:
                GPIO.cleanup()
            except Exception as e:
                print(f"Error during GPIO cleanup: {e}", file=sys.stderr)

    def help(self, command=None):
        """Provides help information."""
        commands = {
            "start": "Start data logging: start <filename>",
            "stop": "Stop data logging: stop",
            "display": "Display log contents: display",
            "send": "Send data: send <data>",
            "write": "Write to log: write <data>",
            "help": "Get help: help [command]",
            "exit": "Exit the program: exit"
        }

        if command and command in commands:
            print(commands[command])
        else:
            print("Available commands:")
            for cmd, desc in commands.items():
                print(f"  {desc}")
            if not command:
                print("\nUse 'help <command>' for more information.")


def main():
    """Main function to run the data logging program."""
    data_logger = DataLogger()
    data_logger._signal_handler = signal.signal(signal.SIGINT, data_logger._signal_handler)
    signal.signal(signal.SIGTERM, data_logger._signal_handler)

    print("Data Logger started. Type 'help' for available commands.")

    try:
        while True:
            try:
                command = input("Enter command: ").strip()
            except EOFError:
                print("\nEOF received. Exiting.")
                break

            if not command:
                continue

            args = command.split()
            action = args[0].lower()

            if action == "start":
                if len(args) != 2:
                    print("Usage: start <filename>")
                else:
                    data_logger.start(args[1])

            elif action == "stop":
                data_logger.stop()

            elif action == "display":
                data_logger.display_log()

            elif action == "send":
                if len(args) < 2:
                    print("Usage: send <data>")
                else:
                    data_logger.send_data(" ".join(args[1:]))

            elif action == "write":
                if len(args) < 2:
                    print("Usage: write <data>")
                else:
                    data_logger.write_to_log(" ".join(args[1:]))

            elif action == "help":
                if len(args) == 1:
                    data_logger.help()
                elif len(args) == 2:
                    data_logger.help(args[1])
                else:
                    print("Usage: help [command]")

            elif action == "exit":
                data_logger.stop()
                data_logger.cleanup()
                print("Exiting program.")
                break

            else:
                print(f"Unknown command: {action}. Type 'help' for available commands.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
        traceback.print_exc()
    finally:
        data_logger.cleanup()


if __name__ == "__main__":
    main()

