        commands = {
            "start": "Start data logging: start <filename>",
            "stop": "Stop data logging: stop",
            "display": "Display log contents: display",
            "send": "Send data: send <data>",
            "write": "Write to log: write <data>",
            "help": "Get help: help [command]",
            "exit": "Exit the program: exit"
        }

        if command and command in commands:
            print(commands[command])
        else:
            print("Available commands:")
            for cmd, desc in commands.items():
                print(f"  {desc}")
            if not command:
                print("\nUse 'help <command>' for more information.")


def main():
    """Main function to run the data logging program."""
    data_logger = DataLogger()
    data_logger._signal_handler = signal.signal(signal.SIGINT, data_logger._signal_handler)
    signal.signal(signal.SIGTERM, data_logger._signal_handler)

    print("Data Logger started. Type 'help' for available commands.")

    try:
        while True:
            try:
                command = input("Enter command: ").strip()
            except EOFError:
                print("\nEOF received. Exiting.")
                break

            if not command:
                continue

            args = command.split()
            action = args[0].lower()

            if action == "start":
                if len(args) != 2:
                    print("Usage: start <filename>")
                else:
                    data_logger.start(args[1])

            elif action == "stop":
                data_logger.stop()

            elif action == "display":
                data_logger.display_log()

            elif action == "send":
                if len(args) < 2:
                    print("Usage: send <data>")
                else:
                    data_logger.send_data(" ".join(args[1:]))

            elif action == "write":
                if len(args) < 2:
                    print("Usage: write <data>")
                else:
                    data_logger.write_to_log(" ".join(args[1:]))

            elif action == "help":
                if len(args) == 1:
                    data_logger.help()
                elif len(args) == 2:
                    data_logger.help(args[1])
                else:
                    print("Usage: help [command]")

            elif action == "exit":
                data_logger.stop()
                data_logger.cleanup()
                print("Exiting program.")
                break

            else:
                print(f"Unknown command: {action}. Type 'help' for available commands.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
        traceback.print_exc()
    finally:
        data_logger.cleanup()


if __name__ == "__main__":
    main()

