import asyncio
import json
import logging
import os
import signal
import sys
import time
from collections import deque
from datetime import datetime
from pathlib import Path

import psutil
import speech_recognition as sr
from google.cloud import firestore
from google.cloud.firestore import Client

try:
    import tflite_runtime.interpreter as tflite
except ImportError:
    import tensorflow.lite as tflite

try:
    from gpiozero import LED
except ImportError:
    LED = None

try:
    import paho.mqtt.client as mqtt
except ImportError:
    mqtt = None

CONFIG_FILE = "config.json"

class Config:
    def __init__(self, config_file=CONFIG_FILE):
        self.config_file = config_file
        self.config = self._load_config()

    def _load_config(self):
        try:
            with open(self.config_file, "r") as f:
                return json.load(f)
        except FileNotFoundError:
            logging.error(f"Configuration file not found: {self.config_file}")
            return None
        except json.JSONDecodeError as e:
            logging.error(f"Error decoding JSON from {self.config_file}: {e}")
            return None

    def get(self, key, default=None):
        return self.config.get(key, default) if self.config else default

    def update(self):
        self.config = self._load_config()

class AudioProcessor:
    def __init__(self, config):
        self.config = config
        self.sensitivity = config.get("sensitivity", 0.3)
        self.keywords = config.get("keywords", [])
        self.sentiment_threshold = config.get("sentiment_threshold", 0.5)
        self.sentiment_history_size = config.get("sentiment_history_size", 5)
        self.sentiment_history = deque(maxlen=self.sentiment_history_size)
        self.interpreter = self._load_interpreter()

    def _load_interpreter(self):
        model_path = self.config.get("sentiment_model_path")
        if not model_path:
            logging.error("Sentiment model path not specified in config.")
            return None
        try:
            if tflite.Interpreter:
                return tflite.Interpreter(model_path=model_path)
            else:
                return tflite.Interpreter(model_path=model_path)
        except Exception as e:
            logging.error(f"Error loading TensorFlow Lite model: {e}")
            return None

    def process_audio(self, audio_data):
        try:
            recognizer = sr.Recognizer()
            with sr.AudioData(audio_data) as audio_data_obj:
                recognizer.adjust_for_ambient_noise(audio_data_obj, duration=0.5)
                text = recognizer.recognize_google(audio_data_obj)
                logging.info(f"Recognized speech: {text}")

                if self.sensitivity > 0 and len(text.split()) > self.sensitivity * 2:
                    logging.info("Speech detected below sensitivity threshold.")
                    return

                if any(keyword.lower() in text.lower() for keyword in self.keywords):
                    logging.info("Keyword detected!")

                if self.interpreter:
                    try:
                        sentiment = self._analyze_sentiment(text)
                        self.sentiment_history.append(sentiment)
                        average_sentiment = sum(self.sentiment_history) / len(self.sentiment_history)
                        logging.info(f"Average sentiment: {average_sentiment}")

                        if average_sentiment > self.sentiment_threshold:
                            logging.warning("High positive sentiment detected!")
                        elif average_sentiment < -self.sentiment_threshold:
                            logging.warning("High negative sentiment detected!")
                    except Exception as e:
                        logging.error(f"Error during sentiment analysis: {e}")
        except sr.UnknownValueError:
            logging.warning("Could not understand audio")
        except sr.RequestError as e:
            logging.error(f"Could not request results from Google Web Speech API; {e}")
        except Exception as e:
            logging.error(f"An unexpected error occurred during audio processing: {e}")

    def _analyze_sentiment(self, text):
        try:
            input_data = [text]
            input_details = self.interpreter.get_input_details()
            output_details = self.interpreter.get_output_details()
            self.interpreter.set_tensor(input_details[0]['index'], input_data)
            self.interpreter.invoke()
            output_data = self.interpreter.get_tensor(output_details[0]['index'])
            return output_data[0][0]
        except Exception as e:
            logging.error(f"Error during sentiment analysis: {e}")
            return 0.0

class AlertSystem:
    def __init__(self, config):
        self.config = config
        self.led_pin = config.get("led_pin", 17)
        self.led = None
        if LED:
            try:
                self.led = LED(self.led_pin)
                logging.info(f"LED initialized on GPIO {self.led_pin}")
            except Exception as e:
                logging.error(f"Error initializing LED on GPIO {self.led_pin}: {e}")
        self.mqtt_client = None
        if mqtt:
            try:
                self.mqtt_client = mqtt.Client()
                self.mqtt_client.connect("localhost", 1883, 60)
                self.mqtt_client.loop_start()
                logging.info("Connected to local MQTT broker.")
            except Exception as e:
                logging.error(f"Error connecting to MQTT broker: {e}")
                self.mqtt_client = None

    def trigger_alert(self, message):
        logging.warning(f"ALERT: {message}")
        if self.led:
            self.led.on()
            time.sleep(1)
            self.led.off()
        if self.mqtt_client:
            try:
                self.mqtt_client.publish("home/alerts", message)
            except Exception as e:
                logging.error(f"Error publishing MQTT message: {e}")

    def shutdown(self):
        if self.led:
            self.led.close()
        if self.mqtt_client:
            self.mqtt_client.loop_stop()
            self.mqtt_client.disconnect()

class ResourceMonitor:
    def __init__(self, config):
        self.config = config
        self.interval = config.get("resource_monitoring_interval", 60)
        self.running = True

    async def run(self):
        while self.running:
            try:
                memory = psutil.virtual_memory()
                cpu_percent = psutil.cpu_percent(interval=1)
                disk_usage = psutil.disk_usage("/")
                logging.info(f"Memory: {memory.percent}%, CPU: {cpu_percent}%, Disk: {disk_usage.percent}%")
            except Exception as e:
                logging.error(f"Error monitoring resources: {e}")
            await asyncio.sleep(self.interval)

    def stop(self):
        self.running = False

class Heartbeat:
    def __init__(self, config):
        self.config = config
        self.interval = config.get("heartbeat_interval", 60)
        self.running = True

    async def run(self):
        while self.running:
            try:
                logging.info("Heartbeat: System is running.")
            except Exception as e:
                logging.error(f"Error sending heartbeat: {e}")
            await asyncio.sleep(self.interval)

    def stop(self):
        self.running = False

class RemoteConfiguration:
    def __init__(self, config):
        self.config = config
        self.interval = config.get("remote_configuration_interval", 300)
        self.running = True
        self.firestore_client = Client()

    async def run(self):
        while self.running:
            try:
                doc_ref = self.firestore_client.document("config/default")
                doc = doc_ref.get()
                if doc.exists:
                    new_config = doc.to_dict()
                    self.config.config = new_config
                    logging.info("Remote configuration updated.")
                else:
                    logging.warning("No configuration document found in Firestore.")
            except Exception as e:
                logging.error(f"Error fetching remote configuration: {e}")
            await asyncio.sleep(self.interval)

    def stop(self):
        self.running = False

class AudioCapture:
    def __init__(self, config, audio_processor, alert_system):
        self.config = config
        self.audio_processor = audio_processor
        self.alert_system = alert_system
        self.running = True

    async def run(self):
        recognizer = sr.Recognizer()
        try:
            with sr.Microphone() as source:
                logging.info("Adjusting for ambient noise...")
                recognizer.adjust_for_ambient_noise(source, duration=1)
                logging.info("Listening for speech...")
                while self.running:
                    try:
                        audio = source.listen(sr.Recognizer(), timeout=None, phrase_time_limit=5)
                        self.audio_processor.process_audio(audio)
                    except sr.WaitTimeoutError:
                        pass
                    except Exception as e:
                        logging.error(f"Error during audio capture: {e}")
                    await asyncio.sleep(0.1)
        except Exception as e:
            logging.error(f"Error initializing microphone: {e}")
            self.alert_system.trigger_alert("Microphone initialization failed.")

    def stop(self):
        self.running = False

async def main():
    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
    config = Config()
    if not config.config:
        logging.error("Failed to load configuration. Exiting.")
        return

    audio_processor = AudioProcessor(config)
    alert_system = AlertSystem(config)
    resource_monitor = ResourceMonitor(config)
    heartbeat = Heartbeat(config)
    remote_config = RemoteConfiguration(config)
    audio_capture = AudioCapture(config, audio_processor, alert_system)

    tasks = [
        asyncio.create_task(resource_monitor.run()),
        asyncio.create_task(heartbeat.run()),
        asyncio.create_task(remote_config.run()),
        asyncio.create_task(audio_capture.run())
    ]

    def shutdown_handler(signum, frame):
        logging.info(f"Signal {signum} received, shutting down...")
        for task in tasks:
            task.cancel()
        resource_monitor.stop()
        heartbeat.stop()
        remote_config.stop()
        audio_capture.stop()
        alert_system.shutdown()

    loop = asyncio.get_running_loop()
    for sig in (signal.SIGINT, signal.SIGTERM):
        loop.add_signal_handler(sig, shutdown_handler, sig, None)

    try:
        await asyncio.gather(*tasks, return_exceptions=True)
    except asyncio.CancelledError:
        pass
    finally:
        alert_system.shutdown()
        logging.info("Shutdown complete.")

if __name__ == "__main__":
    asyncio.run(main())

