import signal
import sys
import time

from gpiozero import DigitalOutputDevice, DigitalInputDevice
from gpiozero.pins.lgpio import LGPIOFactory

try:
    from lib_tft144 import TFT144
except ImportError:
    print("Error: lib_tft144 not found. Please install or check the library path.", file=sys.stderr)
    sys.exit(1)

