CS_PIN = 0       # CE0
DC_PIN = 22
RESET_PIN = 18
LED_PIN = 23

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def main():
    global _running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize GPIO devices using the lgpio backend (modern, no root required)
    try:
        cs = DigitalOutputDevice(CS_PIN, active_high=False, initial_value=True)
        dc = DigitalOutputDevice(DC_PIN, initial_value=False)
        reset = DigitalOutputDevice(RESET_PIN, initial_value=True)
        led = DigitalOutputDevice(LED_PIN, initial_value=True)
    except Exception as e:
        print(f"Error: Failed to initialize GPIO pins: {e}", file=sys.stderr)
        sys.exit(1)

    tft = None
    try:
        # Initialize the TFT144 display in 90-degree orientation
        try:
            tft = TFT144(cs, dc, reset, led, TFT144.ORIENTATION90, isRedBoard=False)
        except Exception as e:
            print(f"Error: Failed to initialize TFT144 display: {e}", file=sys.stderr)
            sys.exit(1)

        # Verify SPI communication by writing a test pattern
        try:
            tft.clear_display(tft.BLACK)
        except Exception as e:
            print(f"Error: SPI communication failed (check wiring/display presence): {e}", file=sys.stderr)
            sys.exit(1)

        colors = [
            (tft.BLUE, "BLUE"),
            (tft.RED, "RED"),
            (tft.GREEN, "GREEN"),
            (tft.PINK, "PINK"),
            (tft.LIGHTBLUE, "LIGHTBLUE"),
            (tft.LIGHTGREEN, "LIGHTGREEN"),
            (tft.YELLOW, "YELLOW"),
            (tft.MAGENTA, "MAGENTA"),
            (tft.CYAN, "CYAN"),
        ]

        while _running:
            for color, name in colors:
                if not _running:
                    break

                try:
                    tft.clear_display(color)
                    tft.put_string("Hello", 0, 0, tft.WHITE, tft.BLACK)
                except Exception as e:
                    print(f"Error writing to display: {e}", file=sys.stderr)
                    break

                # Hold each color for 2 seconds, but allow early exit
                for _ in range(20):
                    if not _running:
                        break
                    time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        # Clean resource release on every exit path
        try:
            if tft is not None:
                try:
                    tft.clear_display(tft.BLACK)
                except Exception:
                    pass
        except Exception:
            pass

        # Close GPIO devices to release pins
        for dev in (cs, dc, reset, led):
            try:
                dev.close()
            except Exception:
                pass

        print("Resources released. Exiting.")

if __name__ == "__main__":
