import signal
import sys
import time
import logging
from typing import List, Optional

import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21
START_SIGNAL = [1, 0, 1, 1, 1, 1, 1, 1]
END_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1, 1]
TRANSMIT_DELAY = 0.0005
RECEPTION_TIMEOUT = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    logging.info(f"Signal {signum} received, shutting down...")
    _running = False

def char_to_bits(char: str) -> List[int]:
    if not isinstance(char, str) or len(char) != 1:
        raise ValueError("Input must be a single character.")
    return [0, 0, 0, 0, 0, 0, 0, 0] + [int(bit) for bit in bin(ord(char))[2:].zfill(7)]

def bits_to_char(bits: List[int]) -> Optional[str]:
    if not isinstance(bits, list) or len(bits) != 8:
        logging.error("Invalid bit sequence length.")
        return None
    try:
        return chr(int("".join(map(str, bits[7:])), 2))
    except ValueError:
        logging.error("Invalid character code.")
        return None

def send_data(data: str) -> None:
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DATA_OUT_PIN, GPIO.OUT)
        GPIO.setup(TIMER_OUT_PIN, GPIO.OUT)
        GPIO.output(DATA_OUT_PIN, GPIO.LOW)
        GPIO.output(TIMER_OUT_PIN, GPIO.LOW)

        for bit in START_SIGNAL:
            GPIO.output(TIMER_OUT_PIN, GPIO.HIGH)
            if not _running:
                break
            time.sleep(TRANSMIT_DELAY)
            GPIO.output(DATA_OUT_PIN, GPIO.HIGH if bit else GPIO.LOW)
            time.sleep(TRANSMIT_DELAY)
            GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
            time.sleep(TRANSMIT_DELAY)

        if not _running:
            return

        for char in data:
            for bit in char_to_bits(char):
                if not _running:
                    break
                GPIO.output(TIMER_OUT_PIN, GPIO.HIGH)
                time.sleep(TRANSMIT_DELAY)
                GPIO.output(DATA_OUT_PIN, GPIO.HIGH if bit else GPIO.LOW)
                time.sleep(TRANSMIT_DELAY)
                GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
                time.sleep(TRANSMIT_DELAY)

        if not _running:
            return

        for bit in END_SIGNAL:
            GPIO.output(TIMER_OUT_PIN, GPIO.HIGH)
            time.sleep(TRANSMIT_DELAY)
            GPIO.output(DATA_OUT_PIN, GPIO.HIGH if bit else GPIO.LOW)
            time.sleep(TRANSMIT_DELAY)
            GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
            time.sleep(TRANSMIT_DELAY)

        logging.info(f"Sent data: {data}")
    except Exception as e:
        logging.error(f"Error during data transmission: {e}")
    finally:
        GPIO.cleanup()

def receive_data() -> Optional[str]:
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DATA_IN_PIN, GPIO.IN)
        GPIO.setup(TIMER_IN_PIN, GPIO.IN)

        start_time = time.time()
        received_bits = []
        received_chars = []

        while _running and time.time() - start_time < RECEPTION_TIMEOUT:
            if GPIO.input(TIMER_IN_PIN):
                received_bits.append(GPIO.input(DATA_IN_PIN))
                if len(received_bits) == 8:
                    if received_bits == START_SIGNAL:
                        received_bits = []
                    elif received_bits == END_SIGNAL:
                        break
                    else:
                        char = bits_to_char(received_bits)
                        if char:
                            received_chars.append(char)
                            received_bits = []
            time.sleep(0.00005)

        if not _running:
            return None

        if time.time() - start_time >= RECEPTION_TIMEOUT:
            logging.warning("Reception timeout reached.")
            return None

        return "".join(received_chars)
    except Exception as e:
        logging.error(f"Error during data reception: {e}")
        return None
    finally:
        GPIO.cleanup()

def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        message = "Hello"
        send_data(message)
        if _running:
            received = receive_data()
            if received is not None:
                logging.info(f"Received data: {received}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

