import signal
import threading
import time

try:
    from gpiozero import OutputDevice, InputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    raise ImportError("gpiozero is required. Install with: sudo apt install python3-gpiozero")


class OutputPin:
    """Represents a generic GPIO output pin."""

    ALLOWED_VALUES = (0, 1)

    def __init__(self, name, pin_number, initial_value=0):
        if not isinstance(pin_number, int) or not (0 <= pin_number <= 27):
            raise ValueError(f"Invalid BCM pin number: {pin_number}")
        if initial_value not in self.ALLOWED_VALUES:
            raise ValueError(f"Invalid initial value: {initial_value}. Must be one of {self.ALLOWED_VALUES}")

        self.name = name
        self.pin_number = pin_number
        self._value = initial_value
        self._device = None
        self._closed = False

        try:
            self._device = OutputDevice(pin_number, active_high=True, initial_value=bool(initial_value))
        except GPIOZeroError as e:
            raise RuntimeError(f"Failed to initialize output pin {pin_number} for '{name}': {e}") from e

        print(f"{self.name} (GPIO {self.pin_number}) set to {self._value}")

    def set_value(self, value):
        if self._closed:
            raise RuntimeError(f"Pin {self.name} is closed; cannot set value.")
        if value not in self.ALLOWED_VALUES:
            raise ValueError(f"Invalid value: {value}. Must be one of {self.ALLOWED_VALUES}")
        if value != self._value:
            try:
                self._device.value = bool(value)
            except DeviceClosed:
                raise RuntimeError(f"Pin {self.name} device closed; cannot set value.")
            self._value = value
            print(f"{self.name} (GPIO {self.pin_number}) set to {self._value}")

    def get_value(self):
        return self._value

    def shutdown(self):
        if self._closed:
            return
        if self._device is not None:
            try:
                self._device.close()
            except Exception:
                pass
        self._closed = True
        print(f"{self.name} (GPIO {self.pin_number}) shutdown")


class TriggerPin(OutputPin):
    """Represents a GPIO output pin used for triggering an output."""

    def __init__(self, name, pin_number, pulse_high=True, initial_value=0):
        super().__init__(name, pin_number, initial_value)
        self.pulse_high = pulse_high
        self._lock = threading.Lock()

    def trigger(self):
        if self._closed:
            raise RuntimeError(f"Pin {self.name} is closed; cannot trigger.")
        with self._lock:
            if self.pulse_high:
                self.set_value(1)
                time.sleep(100e-6)
                self.set_value(0)
            else:
                self.set_value(0)
                time.sleep(100e-6)
                self.set_value(1)


def main():
    output_pin = OutputPin("ExampleOutput", 21, initial_value=0)
    trigger_pin = TriggerPin("ExampleTrigger", 20, pulse_high=True, initial_value=0)

    def signal_handler(signum, frame):
        print(f"\nSignal {signum} received. Shutting down...")
        output_pin.shutdown()
        trigger_pin.shutdown()
        raise SystemExit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        trigger_pin.trigger()
        time.sleep(1)
        trigger_pin.trigger()
    except RuntimeError as e:
        print(f"Runtime error: {e}")
    finally:
        output_pin.shutdown()
        trigger_pin.shutdown()


if __name__ == "__main__":
    main()

