def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup(pwm):
    try:
        if pwm is not None:
            pwm.stop()
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(PWM_PIN, GPIO.OUT, initial=GPIO.LOW)

    pwm = None
    try:
        try:
            pwm = GPIO.PWM(PWM_PIN, PWM_FREQ)
            pwm.start(0)
        except Exception:
            print("Warning: Hardware PWM unavailable; falling back to software PWM.")
            pwm = GPIO.PWM(PWM_PIN, PWM_FREQ)
            pwm.start(0)

        while _running:
            try:
                raw = input("Enter fan speed (0-100, or 'q' to quit): ").strip()
            except EOFError:
                break

            if raw.lower() == 'q':
                break

            try:
                speed = float(raw)
            except ValueError:
                print("Invalid input. Please enter a number between 0 and 100, or 'q' to quit.")
                continue

            if not 0 <= speed <= 100:
                print("Fan speed must be between 0 and 100.")
                continue

            try:
                pwm.ChangeDutyCycle(speed)
            except Exception as e:
                print(f"Error setting duty cycle: {e}")
                continue

            print(f"Fan speed set to {speed:.1f}%")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        _cleanup(pwm)

if __name__ == "__main__":
    main()

