import http.server
import socketserver
import signal
import sys
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

LED_PIN = 18
PORT = 8000

led = None
httpd = None


def handle_led(state):
    """Turn the LED on or off and return the appropriate response."""
    if led is None:
        return (400, "LED not initialized")
    try:
        if state == 'on':
            led.on()
            return (200, 'LED is ON')
        elif state == 'off':
            led.off()
            return (200, 'LED is OFF')
        else:
            return (400, 'Invalid state')
    except GPIOZeroError as e:
        return (500, f"GPIO error: {e}")
    except Exception as e:
        return (500, f"Unexpected error: {e}")


class LEDHandler(http.server.BaseHTTPRequestHandler):
    """HTTP request handler for LED control."""

    def do_GET(self):
        """Handle GET requests for /led/on or /led/off."""
        if self.path == '/led/on':
            status, message = handle_led('on')
        elif self.path == '/led/off':
            status, message = handle_led('off')
        else:
            status, message = (404, 'Not Found')

        self.send_response(status)
        self.send_header('Content-type', 'text/plain; charset=utf-8')
        self.end_headers()
        self.wfile.write(message.encode('utf-8'))

    def log_message(self, format, *args):
        """Suppress default stderr logging; messages are logged to stdout."""
        print(f"{self.client_address[0]} - {format % args}")


def cleanup(signum=None, frame=None):
    """Clean up resources on exit."""
    global led, httpd
    if httpd is not None:
        try:
            httpd.shutdown()
        except Exception:
            pass
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    global led, httpd

    # Initialize LED
    try:
        led = LED(LED_PIN)
    except GPIOZeroError as e:
        print(f"Failed to initialize LED on GPIO{LED_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing LED: {e}", file=sys.stderr)
        sys.exit(1)

    # Set up signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Create HTTP server
    try:
        httpd = socketserver.TCPServer(("", PORT), LEDHandler)
    except OSError as e:
        print(f"Failed to bind to port {PORT}: {e}", file=sys.stderr)
        cleanup()
