import signal
import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)


class LEDController:
    """
    Controls an LED connected to a Raspberry Pi GPIO pin via gpiozero.
    Provides on(), off(), and blink() methods with validation and robust error handling.
    """

    def __init__(self, pin: int):
        """
        Initializes the LEDController.

        Args:
            pin: The BCM GPIO pin number connected to the LED (e.g., 25 for physical pin 22).

        Raises:
            ValueError: If the pin number is invalid.
            GPIOZeroError: If there is an error initializing the GPIO pin.
        """
        if not isinstance(pin, int) or not (0 <= pin <= 27):
            raise ValueError(f"Invalid GPIO pin number: {pin}. Must be an integer between 0 and 27.")

        try:
            self.led = LED(pin)
            self.pin = pin
        except BadPinFactory:
            raise RuntimeError("No GPIO pin factory available. Are you running on a Raspberry Pi?")
        except GPIOZeroError as e:
            raise RuntimeError(f"Error initializing GPIO pin {pin}: {e}")

    def on(self) -> None:
        """Turns the LED on."""
        try:
            self.led.on()
        except GPIOZeroError as e:
            print(f"Error turning LED on: {e}")

    def off(self) -> None:
        """Turns the LED off."""
        try:
            self.led.off()
        except GPIOZeroError as e:
            print(f"Error turning LED off: {e}")

    def blink(self, on_duration: float, off_duration: float) -> None:
        """
        Blinks the LED with specified on and off durations.

        Args:
            on_duration: The duration (in seconds) for which the LED stays on.
            off_duration: The duration (in seconds) for which the LED stays off.

        Raises:
            ValueError: If on_duration or off_duration is negative.
        """
        if on_duration < 0 or off_duration < 0:
            raise ValueError("Durations must be non-negative.")

        self.on()
        time.sleep(on_duration)
        self.off()
        time.sleep(off_duration)

    def cleanup(self) -> None:
        """Releases the GPIO resource."""
        try:
            self.off()
            self.led.close()
        except Exception as e:
            print(f"Error during cleanup: {e}")


def main():
    """Main function to demonstrate LED blinking with graceful shutdown."""
    led_pin = 25
    led_controller = None

    def signal_handler(signum, frame):
        print(f"\nReceived signal {signum}. Shutting down gracefully...")
        if led_controller:
            led_controller.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        led_controller = LEDController(led_pin)
        print(f"LEDController initialized on GPIO{led_pin}. Starting blink loop (1s on, 0.5s off).")
        while True:
            led_controller.blink(1.0, 0.5)

    except ValueError as e:
        print(f"Configuration error: {e}")
    except RuntimeError as e:
        print(f"Runtime error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if led_controller:
            led_controller.cleanup()


if __name__ == "__main__":
    main()

