import json
import random
import sys

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None


def generate_audio_frame():
    """Generate a simulated audio frame with a random energy level."""
    return random.randint(0, 9)


def transcribe_audio(audio_frame):
    """Transcribe the simulated audio frame to a keyword."""
    keywords = ["water", "stop", "status"]
    return random.choice(keywords)


def map_keyword_to_action(keyword):
    """Map a keyword to a farm action."""
    action_map = {
        "water": "open_valve",
        "stop": "close_valve",
        "status": "report",
    }
    return action_map.get(keyword, "unknown")


def main():
    """Run the voice recognition simulation and save actions to JSON."""
    actions_chosen = []
    try:
        for frame_index in range(6):
            audio_energy = generate_audio_frame()
            recognized_keyword = transcribe_audio(audio_energy)
            chosen_action = map_keyword_to_action(recognized_keyword)
            actions_chosen.append(chosen_action)
            print(
                f"Frame {frame_index}: Keyword '{recognized_keyword}' -> Action '{chosen_action}'"
            )
    except Exception as e:
        print(f"An error occurred during simulation: {e}", file=sys.stderr)
    finally:
        try:
            with open("voice_actions.json", "w") as f:
                json.dump(actions_chosen, f, indent=2)
            print(f"Actions saved to voice_actions.json ({len(actions_chosen)} total)")
        except IOError as e:
            print(f"Failed to write JSON file: {e}", file=sys.stderr)
        except Exception as e:
            print(f"Unexpected error saving JSON: {e}", file=sys.stderr)


if __name__ == "__main__":
    main()

