import logging
import signal
import sys
import time
from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)


class MotionSensor:
    """HC-SR501 PIR motion sensor wrapper with debouncing and error handling."""

    def __init__(self, pin: int, debounce_ms: int = 200):
        self.pin = pin
        self.debounce_s = debounce_ms / 1000.0
        self._last_motion_time: float | None = None
        self._sensor: DigitalInputDevice | None = None
        self._closed = False

        try:
            self._sensor = DigitalInputDevice(pin, pull_up=False, bounce_time=self.debounce_s)
            logging.info("Motion sensor initialized on GPIO%d (debounce=%.0fms).", pin, debounce_ms)
        except GPIOZeroError as exc:
            logging.error("Failed to initialize GPIO%d: %s", pin, exc)
            raise

    def read(self) -> bool:
        """Return True only if a debounced motion pulse was detected since last call."""
        if self._closed or self._sensor is None:
            return False
        try:
            if not self._sensor.is_active:
                self._last_motion_time = None
                return False
        except DeviceClosed:
            self._closed = True
            return False
        except GPIOZeroError as exc:
            logging.error("Error reading GPIO%d: %s", self.pin, exc)
            return False

        now = time.monotonic()
        if self._last_motion_time is None:
            self._last_motion_time = now
            return True
        if now - self._last_motion_time >= self.debounce_s:
            self._last_motion_time = now
            return True
        return False

    def close(self) -> None:
        if self._closed:
            return
        self._closed = True
        if self._sensor is not None:
            try:
                self._sensor.close()
            except GPIOZeroError as exc:
                logging.error("Error closing GPIO%d: %s", self.pin, exc)
            finally:
                self._sensor = None


class VisitorCounter:
    """Counts motion events and logs visitor statistics."""

    def __init__(self, sensor: MotionSensor, interval_s: int = 10, run_seconds: int = 60):
        self.sensor = sensor
        self.interval_s = interval_s
        self.run_seconds = run_seconds
        self.visitor_count = 0
        self._last_log_time: float | None = None
        self._start_time: float | None = None
        self._running = False

    def start(self) -> None:
        self._start_time = time.monotonic()
        self._last_log_time = self._start_time
        self._running = True
        logging.info("Visitor counter started for %d seconds.", self.run_seconds)

    def stop(self) -> None:
        self._running = False

    def _elapsed(self) -> float:
        if self._start_time is None:
            return 0.0
        return time.monotonic() - self._start_time

    def _remaining(self) -> float:
        return max(0.0, self.run_seconds - self._elapsed())

    def _log_interval(self) -> None:
        if self._last_log_time is None:
            return
        elapsed = time.monotonic() - self._last_log_time
        if elapsed >= self.interval_s:
            logging.info("Visitors in the last %.0fs: %d", elapsed, self.visitor_count)
            self.visitor_count = 0
            self._last_log_time = time.monotonic()

    def run(self) -> None:
        self.start()
        try:
            while self._running and self._remaining() > 0:
                if self.sensor.read():
                    self.visitor_count += 1
                self._log_interval()
                time.sleep(0.05)
        except Exception as exc:
            logging.error("Unexpected error in main loop: %s", exc)
        finally:
            self._final_report()
            self.sensor.close()

    def _final_report(self) -> None:
        total_visitors = self.visitor_count
        elapsed = self._elapsed()
        if elapsed > 0:
            visitors_per_minute = (total_visitors / elapsed) * 60
        else:
            visitors_per_minute = 0.0
        logging.info("Total visitors counted: %d", total_visitors)
        logging.info("Visitors per minute: %.2f", visitors_per_minute)


def main() -> None:
    PIR_PIN = 23
    DEBOUNCE_MS = 200
    INTERVAL_S = 10
    RUN_SECONDS = 60

    sensor = MotionSensor(PIR_PIN, debounce_ms=DEBOUNCE_MS)
    counter = VisitorCounter(sensor, interval_s=INTERVAL_S, run_seconds=RUN_SECONDS)

    def _signal_handler(signum, frame):
        logging.info("Received signal %d, shutting down...", signum)
        counter.stop()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    counter.run()


if __name__ == "__main__":
    main()

