import time
from collections import deque

import numpy as np
import requests
import tflite_runtime.interpreter as tflite

try:
    import smbus2
except ImportError:
    smbus2 = None

try:
    from ina219 import INA219, DeviceRangeError
except ImportError:
    INA219 = None
    DeviceRangeError = Exception

DEFAULT_CONFIG = {
    "i2c_bus": 1,
    "vibration_address": 0x5D,
    "ina219_address": 0x40,
    "scale_factor": 0.001,
    "shunt_resistance": 0.1,
    "moving_average_window": 5,
    "failure_threshold": 0.8,
    "endpoint": "http://example.com/alerts",
    "model_path": "model.tflite",
    "log_file": "vibration_monitor.log",
}


class SensorReadError(Exception):
    pass


class VibrationSensor:
    def __init__(self, bus_num, address, scale_factor):
        self.bus_num = bus_num
        self.address = address
        self.scale_factor = scale_factor
        self.bus = None
        self._open_bus()

    def _open_bus(self):
        if smbus2 is None:
            raise SensorReadError("smbus2 library not installed")
        try:
            self.bus = smbus2.SMBus(self.bus_num)
        except Exception as e:
            raise SensorReadError(f"Failed to open I2C bus {self.bus_num}: {e}")

    def read_vibration(self):
        if self.bus is None:
            self._open_bus()
        try:
            data = self.bus.read_i2c_block_data(self.address, 0x00, 6)
            x = (data[1] << 8) | data[0]
            y = (data[3] << 8) | data[2]
            z = (data[5] << 8) | data[4]
            x = x * self.scale_factor
            y = y * self.scale_factor
            z = z * self.scale_factor
            return x, y, z
        except Exception as e:
            logging.error(f"Error reading vibration sensor: {e}")
            self.close()
            raise SensorReadError(f"Failed to read vibration sensor: {e}")

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None


class CurrentSensor:
    def __init__(self, bus_num, address, shunt_resistance):
        self.bus_num = bus_num
        self.address = address
        self.shunt_resistance = shunt_resistance
        self.ina = None
        self._init_ina()

    def _init_ina(self):
        if INA219 is None:
