import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or is not supported on this platform.")
    sys.exit(1)

SERVO_PIN = 18
PWM_FREQ = 50
MIN_DUTY = 2.5
MAX_DUTY = 12.5

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def angle_from_hr(heart_rate):
    if heart_rate < 0:
        raise ValueError("Heart rate must be non-negative.")
    return int((heart_rate / 100.0) * 180)


def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    pwm = None
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(SERVO_PIN, GPIO.OUT)
        pwm = GPIO.PWM(SERVO_PIN, PWM_FREQ)
        pwm.start(0)

        heart_rates = [62, 75, 88, 110, 95]
        for heart_rate in heart_rates:
            if not _running:
                break

            try:
                angle = angle_from_hr(heart_rate)
            except ValueError as e:
                print(f"Error calculating angle for {heart_rate} bpm: {e}")
                continue

            duty = (angle / 180.0) * (MAX_DUTY - MIN_DUTY) + MIN_DUTY
            pwm.ChangeDutyCycle(duty)
            print(f"Heart Rate: {heart_rate} bpm, Servo Angle: {angle}°")
            time.sleep(0.8)

    except Exception as e:
        print(f"An error occurred: {e}")

    finally:
        if pwm is not None:
            try:
                pwm.stop()
            except Exception:
                pass
        try:
            GPIO.cleanup()
        except Exception:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

