import random
import time
import signal
import sys

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOUnavailableError, BadPinFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

# Configuration
LED_PIN = 18
THRESHOLD = 50
RETRY_DELAY = 2  # seconds
MAX_RETRIES = 1

# Global flag for graceful shutdown
_running = True

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def read_water_quality():
    """Simulates reading water quality data (0-100%).
    Includes a 10% chance of simulating a sensor read failure.
    """
    if random.random() < 0.1:
        raise IOError("Simulated sensor read failure")
    return random.randint(0, 100)

def validate_gpio_pin(pin):
    """Validates the GPIO pin number."""
    if not isinstance(pin, int) or pin < 0:
        raise ValueError(f"Invalid GPIO pin number: {pin}")

def control_led(led, quality_value):
    """Controls the LED based on the water quality reading."""
    if quality_value < THRESHOLD:
        led.on()
        print(f"LED ON: Water quality {quality_value}% below threshold {THRESHOLD}%")
    else:
        led.off()
        print(f"LED OFF: Water quality {quality_value}% at or above threshold {THRESHOLD}%")

def main():
    """Main function to simulate water quality monitoring."""
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    led = None
    try:
        # Validate GPIO pin before initialization
        validate_gpio_pin(LED_PIN)

        # Initialize LED with error handling
        try:
            led = LED(LED_PIN)
        except (GPIOUnavailableError, BadPinFactory) as e:
            print(f"GPIO initialization error: {e}")
            sys.exit(1)
        except Exception as e:
            print(f"Unexpected error initializing GPIO: {e}")
            sys.exit(1)

        print(f"Water Quality Monitoring System Started (LED on GPIO{LED_PIN})")

        while _running:
            try:
                water_quality = read_water_quality()
                print(f"Simulated Water Quality Reading: {water_quality}%")
                control_led(led, water_quality)

            except IOError as e:
                print(f"Sensor read error: {e}")
                print("Retrying...")
                time.sleep(RETRY_DELAY)
                if not _running:
                    break
                try:
                    water_quality = read_water_quality()
                    print(f"Retry successful: {water_quality}%")
                    control_led(led, water_quality)
                except IOError as retry_error:
                    print(f"Retry failed: {retry_error}")
                    print("Skipping this reading.")

            except Exception as e:
                print(f"An unexpected error occurred: {e}")

            if _running:
                time.sleep(RETRY_DELAY)

    except ValueError as e:
        print(f"Configuration error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Clean resource release on all exit paths
        if led is not None:
            try:
                led.close()
                print("GPIO cleanup completed.")
            except Exception as e:
                print(f"Error during GPIO cleanup: {e}")
        print("Program terminated.")

if __name__ == "__main__":
    main()

