import sys
import logging
from typing import Optional, Tuple

try:
    import serial
except ImportError:
    serial = None

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    stream=sys.stderr
)

SERVER_ADDRESS = '127.0.0.1'
SERVER_PORT = 9099
GPS_TIMEOUT = 2

_running = True
_gps_port: Optional[str] = None
_gps_baudrate: Optional[int] = None
_gps_serial: Optional["serial.Serial"] = None


def _signal_handler(signum, frame):
    global _running
    logging.info(f"Received signal {signum}, shutting down...")
    _running = False


def _cleanup():
    global _gps_serial
    if _gps_serial is not None:
        try:
            if _gps_serial.is_open:
                _gps_serial.close()
                logging.info("UART connection closed.")
        except Exception as e:
            logging.error(f"Error closing UART: {e}")
        _gps_serial = None


def initialize_gps(port: str, baudrate: int) -> bool:
    global _gps_serial
    if serial is None:
        logging.error("pyserial not installed; GPS disabled.")
        return False
    try:
        _gps_serial = serial.Serial(port, baudrate, timeout=GPS_TIMEOUT)
        logging.info(f"GPS initialized on {port} @ {baudrate} baud.")
        return True
    except serial.SerialException as e:
        logging.error(f"Failed to open GPS serial port {port}: {e}")
        _gps_serial = None
        return False
    except Exception as e:
        logging.error(f"Unexpected error initializing GPS: {e}")
        _gps_serial = None
        return False


def read_gps_position() -> Tuple[Optional[float], Optional[float]]:
    if _gps_serial is None:
        return None, None
    try:
        raw = _gps_serial.readline()
        if not raw:
            return None, None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None, None
        if not line.startswith('$GPRMC'):
            return None, None
        parts = line.split(',')
        if len(parts) < 7 or not parts[2] or not parts[4] or not parts[5]:
            return None, None
        lat = float(parts[3])
        lon = float(parts[5])
        return lat, lon
    except ValueError:
        logging.error("Invalid GPS data format.")
        return None, None
    except serial.SerialException as e:
        logging.error(f"Serial read error: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Unexpected error reading GPS: {e}")
        return None, None


def handle_command(command: str, state: dict) -> Optional[str]:
    if command == 'start':
        state['tracking'] = True
        logging.info("Tracking started.")
        return None
    elif command == 'stop':
        state['tracking'] = False
        logging.info("Tracking stopped.")
        return None
    elif command == 'report':
        lat, lon = read_gps_position()
        if lat is not None and lon is not None:
            return json.dumps({'lat': lat, 'lon': lon})
        else:
            logging.warning("No GPS data available; reporting simulated coordinates.")
            return json.dumps({'lat': 37.7749, 'lon': -122.4194})
    else:
        return json.dumps({'error': 'Invalid command'})


def main(gps_port: Optional[str] = None, gps_baudrate: Optional[int] = None):
    global _gps_port, _gps_baudrate
    _gps_port = gps_port
    _gps_baudrate = gps_baudrate

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    gps_ok = False
    if _gps_port is not None and _gps_baudrate is not None:
        gps_ok = initialize_gps(_gps_port, _gps_baudrate)
    elif _gps_port is not None:
        logging.warning(f"GPS port requested but baudrate missing; using {_gps_port} with default 9600.")
        gps_ok = initialize_gps(_gps_port, 9600)

    state = {'tracking': False}

    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as server_socket:
            server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            server_socket.bind((SERVER_ADDRESS, SERVER_PORT))
            server_socket.listen(1)
            logging.info(f"Listening on {SERVER_ADDRESS}:{SERVER_PORT}")

            while _running:
                try:
                    client_socket, client_address = server_socket.accept()
                except socket.timeout:
                    continue
                except OSError as e:
                    if _running:
                        logging.error(f"Accept error: {e}")
                    continue

                try:
                    with client_socket:
                        logging.info(f"Connection from {client_address}")
                        try:
                            data = client_socket.recv(1024)
                        except socket.timeout:
                            logging.warning("Client timed out during recv.")
                            continue
                        except OSError as e:
                            logging.error(f"Recv error: {e}")
                            continue

                        if not data:
                            continue

                        command = data.decode('ascii', errors='replace').strip().lower()
                        logging.info(f"Received command: {command}")

                        response = handle_command(command, state)
                        if response is not None:
                            try:
                                client_socket.sendall(response.encode('utf-8'))
                            except OSError as e:
                                logging.error(f"Send error: {e}")
                except Exception as e:
                    logging.error(f"Error handling client: {e}")
    finally:
        _cleanup()
        logging.info("Server stopped.")


if __name__ == '__main__':
    main(gps_port='/dev/ttyS0', gps_baudrate=9600)

