import random
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)

PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
NUM_READINGS = 5
DELAY_SECONDS = 2

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_moisture_level():
    return random.randint(0, 100)

def control_water_pump(moisture_level):
    if moisture_level < MOISTURE_THRESHOLD:
        GPIO.output(PUMP_PIN, GPIO.HIGH)
        print(f"Water Pump ON: Soil too dry ({moisture_level}%)")
    else:
        GPIO.output(PUMP_PIN, GPIO.LOW)
        print(f"Water Pump OFF: Soil moisture adequate ({moisture_level}%)")

def main():
    global _running
    _running = True
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PUMP_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        GPIO.cleanup()
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not _running:
                break
            moisture = read_moisture_level()
            print(f"Reading {i + 1}/{NUM_READINGS}: Soil Moisture = {moisture}%")
            control_water_pump(moisture)
            if i < NUM_READINGS - 1 and _running:
                time.sleep(DELAY_SECONDS)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        GPIO.output(PUMP_PIN, GPIO.LOW)
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

