import time
import random
import sys
from gpiozero import Buzzer

# BCM pin connected to the KY-006 passive buzzer driver
BUZZER_PIN = 17


def play_tone(buzzer, frequency, duration):
    """Play a single tone on the buzzer, then stop briefly."""
    buzzer.play(frequency)
    time.sleep(duration)
    buzzer.stop()
    time.sleep(0.01)


def play_pattern(buzzer, frequency, label):
    """Play the sound pattern corresponding to the distance label."""
    if label == "Far":
        play_tone(buzzer, frequency, 0.1)
        time.sleep(2)
    elif label == "Medium":
        play_tone(buzzer, frequency, 0.1)
        time.sleep(0.1)
        play_tone(buzzer, frequency, 0.1)
        time.sleep(1)
    elif label == "Close":
        play_tone(buzzer, frequency, 0.4)
        time.sleep(0.1)
    else:
        raise ValueError(f"Unknown distance label: {label}")


def main():
    buzzer = None
    try:
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as e:
        print(f"Error initializing buzzer on BCM pin {BUZZER_PIN}: {e}")
        sys.exit(1)

    try:
        while True:
            distance_label = random.choice(["Far", "Medium", "Close"])
            print(f"Simulated Distance: {distance_label}")
            play_pattern(buzzer, 440, distance_label)
            time.sleep(0.01)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if buzzer is not None:
            buzzer.stop()


if __name__ == "__main__":
    main()

