import random
import time
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

LED_PIN = 17
CYCLES = 5
DELAY_SECONDS = 2


def read_light_level() -> int:
    """Simulate a light sensor reading (0–100 percent)."""
    return random.randint(0, 100)


def control_led(led: LED, light_level: int) -> None:
    """Turn the LED on or off based on the light level and print status."""
    if light_level < 50:
        led.on()
        print(f"Light level: {light_level}% -> LED ON")
    else:
        led.off()
        print(f"Light level: {light_level}% -> LED OFF")


def main() -> None:
    """Run the simulated ambient-light monitoring loop."""
    try:
        led = LED(LED_PIN)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO pin {LED_PIN}: {exc}")
        return

    try:
        for cycle in range(1, CYCLES + 1):
            light_level = read_light_level()
            control_led(led, light_level)
            if cycle < CYCLES:
                time.sleep(DELAY_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        led.off()
        led.close()
        print("LED turned off and GPIO resources released.")


if __name__ == "__main__":
    main()

