import logging
from typing import Any, Dict, List, Optional, Tuple

try:
    import serial
    from pymodbus.client import ModbusSerialClient
    from pymodbus.exceptions import ModbusException
    from pymodbus.payload import BinaryPayloadDecoder
    from pymodbus.constants import Endian
except ImportError as e:
    logging.error(f"Missing required library: {e}. Install with: pip install pymodbus pyserial")
    raise

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class ServoController:
    """
    Modbus RTU servo motor controller abstraction for Raspberry Pi.

    Register maps are dictionaries of the form:
        {
            'name': {
                'R/W': 'R',
                'Register': 0x0000,
                'functioncode': 3,
                'unitid': 1,
                'datatype': '16uint',
            },
            ...
        }
    """

    def __init__(self, port: str = '/dev/serial0', baudrate: int = 115200, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.client: Optional[ModbusSerialClient] = None
        self._connected = False
        self._original_sigint = signal.getsignal(signal.SIGINT)
        self._original_sigterm = signal.getsignal(signal.SIGTERM)

    def connect(self) -> bool:
        """Open the serial port and establish a Modbus RTU connection."""
        try:
            self.client = ModbusSerialClient(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=8,
                parity='N',
                stopbits=1,
                timeout=self.timeout,
            )
            if not self.client.connect():
                logger.error(f"Failed to open serial port {self.port}")
                self.client = None
                return False
            self._connected = True
            signal.signal(signal.SIGINT, self._signal_handler)
            signal.signal(signal.SIGTERM, self._signal_handler)
            logger.info(f"Connected to servo controller on {self.port} @ {self.baudrate} baud")
            return True
        except serial.SerialException as e:
            logger.error(f"Serial port error on {self.port}: {e}")
            self.client = None
            return False
        except Exception as e:
            logger.error(f"Unexpected error connecting to {self.port}: {e}")
            self.client = None
            return False

    def _signal_handler(self, signum, frame):
        logger.info(f"Signal {signum} received, shutting down...")
        self.close()
        sys.exit(0)

    def close(self):
        """Release the Modbus connection and restore signal handlers."""
        if self._connected and self.client:
            try:
                self.client.close()
            except Exception as e:
                logger.error(f"Error closing serial port: {e}")
            finally:
                self._connected = False
                self.client = None
        signal.signal(signal.SIGINT, self._original_sigint)
        signal.signal(signal.SIGTERM, self._original_sigterm)

    def read_register(self, register_map: Dict[str, Any], unitid: int = 1) -> Optional[Any]:
        """Read a single holding register using FC3."""
        if not self._connected or not self.client:
            logger.warning("Not connected to servo controller; cannot read.")
            return None
        try:
            reg = register_map.get('Register')
            if reg is None:
                logger.error("Register map missing 'Register' key.")
                return None
            count = 1
            result = self.client.read_holding_registers(address=reg, count=count, slave=unitid)
            if result.isError():
                logger.error(f"Modbus error reading register 0x{reg:04X}: {result}")
                return None
            decoder = BinaryPayloadDecoder.fromRegisters(result.registers, byteorder=Endian.BIG, wordorder=Endian.LITTLE)
            return decoder.decode_16bit_uint()
        except ModbusException as e:
            logger.error(f"Modbus exception reading register 0x{reg:04X}: {e}")
            return None
        except Exception as e:
            logger.error(f"Unexpected error reading register 0x{reg:04X}: {e}")
            return None

    def write_register(self, register_map: Dict[str, Any], value: Any, unitid: int = 1) -> bool:
        """Write a single holding register using FC6."""
        if not self._connected or not self.client:
            logger.warning("Not connected to servo controller; cannot write.")
            return False
        try:
            reg = register_map.get('Register')
            if reg is None:
                logger.error("Register map missing 'Register' key.")
                return False
            result = self.client.write_register(address=reg, value=value, slave=unitid)
            if result.isError():
                logger.error(f"Modbus error writing register 0x{reg:04X}: {result}")
                return False
            return True
        except ModbusException as e:
            logger.error(f"Modbus exception writing register 0x{reg:04X}: {e}")
            return False
        except Exception as e:
            logger.error(f"Unexpected error writing register 0x{reg:04X}: {e}")
            return False

    def write_registers(self, register_map: Dict[str, Any], values: List[Any], unitid: int = 1) -> bool:
        """Write multiple holding registers using FC16."""
        if not self._connected or not self.client:
            logger.warning("Not connected to servo controller; cannot write.")
            return False
        try:
            reg = register_map.get('Register')
            if reg is None:
                logger.error("Register map missing 'Register' key.")
                return False
            count = len(values)
            result = self.client.write_registers(address=reg, values=values, slave=unitid)
            if result.isError():
                logger.error(f"Modbus error writing registers 0x{reg:04X}: {result}")
                return False
            return True
        except ModbusException as e:
            logger.error(f"Modbus exception writing registers 0x{reg:04X}: {e}")
            return False
        except Exception as e:
            logger.error(f"Unexpected error writing registers 0x{reg:04X}: {e}")
            return False

    def read_map(self, register_map: Dict[str, Dict[str, Any]], unitid: int = 1) -> Dict[str, Any]:
        """Read all registers in a given map."""
        values: Dict[str, Any] = {}
        for name, map_entry in register_map.items():
            if map_entry.get('R/W') == 'R':
                val = self.read_register(map_entry, unitid)
                values[name] = val
        return values

    def write_map(self, register_map: Dict[str, Dict[str, Any]], values: Dict[str, Any], unitid: int = 1) -> bool:
        """Write all writable registers in a given map."""
        success = True
        for name, map_entry in register_map.items():
            if map_entry.get('R/W') == 'W' and name in values:
                if not self.write_register(map_entry, values[name], unitid):
                    success = False
        return success


if __name__ == '__main__':
    controller = ServoController(port='/dev/serial0', baudrate=115200, timeout=1.0)
    if not controller.connect():
        logger.error("Failed to connect to servo controller. Exiting.")
        sys.exit(1)
    try:
        # Example usage placeholder — replace with actual register maps and logic.
        example_map = {
            'position': {'R/W': 'R', 'Register': 0x0000, 'functioncode': 3, 'unitid': 1, 'datatype': '16uint'},
            'speed':    {'R/W': 'W', 'Register': 0x0001, 'functioncode': 6, 'unitid': 1, 'datatype': '16uint'},
        }
        read_result = controller.read_map(example_map, unitid=1)
        logger.info(f"Read map result: {read_result}")
        if not controller.write_map(example_map, {'speed': 500}, unitid=1):
            logger.warning("Write failed; continuing to close cleanly.")
    finally:
        controller.close()

