import signal
import sys
import time
import logging
from typing import Optional

from src.lib.relay import Relay

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1

_running = True


def _handle_signal(signum: int, frame) -> None:
    global _running
    logging.info("Received signal %s, shutting down...", signum)
    _running = False


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    relay: Optional[Relay] = None
    try:
        relay = Relay(SERIAL_PORT, BAUD_RATE, TIMEOUT)
        relay.flush_input_buffer()
        logging.info("Connected to relay on %s at %d baud", SERIAL_PORT, BAUD_RATE)

        while _running:
            try:
                command = "RELAY1 ON"
                written = relay.send_command(command)
                if written != len(command):
                    logging.warning(
                        "Short write: %d/%d bytes for '%s'",
                        written,
                        len(command),
                        command,
                    )
                else:
                    logging.info("Sent command: %s", command)

                for _ in range(5):
                    if not _running:
                        break
                    time.sleep(1)

                if not _running:
                    break

                command = "RELAY1 OFF"
                written = relay.send_command(command)
                if written != len(command):
                    logging.warning(
                        "Short write: %d/%d bytes for '%s'",
                        written,
                        len(command),
                        command,
                    )
                else:
                    logging.info("Sent command: %s", command)

                for _ in range(5):
                    if not _running:
                        break
                    time.sleep(1)

            except OSError as e:
                logging.error("OS error during relay operation: %s", e)
                break
            except Exception as e:
                logging.error("Unexpected error during relay operation: %s", e)
                break

    except OSError as e:
        logging.error("Failed to open serial port %s: %s", SERIAL_PORT, e)
        return 1
    except Exception as e:
        logging.error("Unexpected initialization error: %s", e)
        return 1
    finally:
        if relay is not None:
            try:
                relay.close()
                logging.info("Serial port closed.")
            except Exception as e:
                logging.error("Error closing serial port: %s", e)

    return 0


if __name__ == "__main__":
    sys.exit(main())

