import time
import signal
import sys

try:
    from adafruit_servokit import ServoKit
except ImportError:
    print("Error: adafruit_servokit not installed. Install with: pip install adafruit-circuitpython-servokit")
    sys.exit(1)

# Constants
SERVO_CHANNEL = 0
GRAB_ANGLE = 90
RELEASE_ANGLE = 150
STEP_DEGREES = 5
STEP_DELAY = 0.04
MIN_ANGLE = 0
MAX_ANGLE = 180

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_servokit():
    """Initializes the ServoKit object on I2C bus 1 (default address 0x40)."""
    try:
        kit = ServoKit(channels=16, i2c=None, address=0x40)
        return kit
    except Exception as e:
        print(f"Error initializing ServoKit: {e}")
        return None

def validate_channel(channel):
    """Validates that the channel number is within the allowed range (0-15)."""
    if not isinstance(channel, int) or not (0 <= channel <= 15):
        print(f"Error: Invalid channel number: {channel}. Must be an integer between 0 and 15.")
        return False
    return True

def validate_angle(angle):
    """Validates that the angle is within the allowed range (0-180)."""
    if not isinstance(angle, (int, float)) or not (MIN_ANGLE <= angle <= MAX_ANGLE):
        print(f"Error: Invalid angle: {angle}. Must be a number between {MIN_ANGLE} and {MAX_ANGLE}.")
        return False
    return True

def move_servo(kit, channel, target_angle):
    """Moves a servo to a target angle in 5-degree steps with a 0.04s delay."""
    if kit is None:
        print("Error: ServoKit not initialized.")
        return False
    if not validate_channel(channel):
        return False
    if not validate_angle(target_angle):
        return False

    try:
        current_angle = kit.servo[channel].angle
        if current_angle is None:
            current_angle = 0

        step = STEP_DEGREES if target_angle > current_angle else -STEP_DEGREES

        # Generate range from current to target, inclusive of both ends
        angle_range = list(range(int(current_angle), int(target_angle), step))
        if not angle_range or angle_range[-1] != int(target_angle):
            angle_range.append(int(target_angle))

        for angle in angle_range:
            if not _running:
                print("Movement interrupted by user.")
                return False
            kit.servo[channel].angle = angle
            time.sleep(STEP_DELAY)
        return True
    except OSError as e:
        print(f"OSError moving servo on channel {channel}: {e}")
        return False
    except ValueError as e:
        print(f"ValueError moving servo on channel {channel}: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error moving servo on channel {channel}: {e}")
        return False

def grab_object(kit, channel=SERVO_CHANNEL):
    """Grabs an object by moving the servo to 90 degrees."""
    print("Grabbing object...")
    success = move_servo(kit, channel, GRAB_ANGLE)
    if success:
        print("Object grabbed.")
    return success

def release_object(kit, channel=SERVO_CHANNEL):
    """Releases an object by moving the servo to 150 degrees."""
    print("Releasing object...")
    success = move_servo(kit, channel, RELEASE_ANGLE)
    if success:
        print("Object released.")
    return success

def main():
    """Main function to demonstrate object manipulation."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    kit = initialize_servokit()
    if kit is None:
        print("Failed to initialize ServoKit. Exiting.")
        return

    try:
        if grab_object(kit):
            time.sleep(1)
            release_object(kit)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        # Clean up resources
        print("Cleaning up...")
        try:
            # Turn off all servos to save power
            for ch in range(16):
                kit.servo[ch].angle = None
        except Exception:
            pass
        print("Cleanup complete.")

if __name__ == "__main__":
    main()

