import logging
import signal
import sys
import time

import RPi.GPIO as GPIO

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)

SOLENOID_PIN = 24
PULSE_DURATION = 0.4
DELAY_BETWEEN_PULSES = 1.0
NUM_PULSES = 3


class SolenoidController:
    """Controls a solenoid via a relay module on a Raspberry Pi GPIO pin."""

    def __init__(self, pin: int) -> None:
        self.pin = pin
        self._active = False
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(self.pin, GPIO.OUT, initial=GPIO.LOW)
        except Exception as exc:
            logging.error("Failed to initialize GPIO pin %d: %s", pin, exc)
            raise

    def activate(self, duration: float) -> None:
        """Energize the relay for *duration* seconds, then de-energize it."""
        if self._active:
            logging.warning("Relay already active; ignoring activation request.")
            return
        self._active = True
        try:
            GPIO.output(self.pin, GPIO.HIGH)
            logging.info("Relay activated on pin %d for %.3f s.", self.pin, duration)
            time.sleep(duration)
        except Exception as exc:
            logging.error("Error during relay activation: %s", exc)
        finally:
            self.deactivate()

    def deactivate(self) -> None:
        """De-energize the relay and mark it as inactive."""
        try:
            GPIO.output(self.pin, GPIO.LOW)
            logging.info("Relay deactivated on pin %d.", self.pin)
        except Exception as exc:
            logging.error("Error during relay deactivation: %s", exc)
        finally:
            self._active = False

    def cleanup(self) -> None:
        """Ensure the relay is de-energized and release the GPIO pin."""
        if self._active:
            self.deactivate()
        try:
            GPIO.cleanup(self.pin)
            logging.info("GPIO cleanup completed for pin %d.", self.pin)
        except Exception as exc:
            logging.error("Error during GPIO cleanup: %s", exc)


def run_pulse_sequence(controller: SolenoidController, num_pulses: int) -> None:
    """Run *num_pulses* activation cycles with a 1 s delay between pulses."""
    for pulse_index in range(num_pulses):
        logging.info("Pulse %d/%d starting...", pulse_index + 1, num_pulses)
        controller.activate(PULSE_DURATION)
        if pulse_index < num_pulses - 1:
            time.sleep(DELAY_BETWEEN_PULSES)


def main() -> None:
    controller = None
    try:
        controller = SolenoidController(SOLENOID_PIN)
        run_pulse_sequence(controller, NUM_PULSES)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user (SIGINT).")
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
    finally:
        if controller is not None:
            controller.cleanup()


def _signal_handler(signum, frame) -> None:
    sig_name = signal.Signals(signum).name
    logging.info("Received %s; initiating graceful shutdown.", sig_name)
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    main()

