import signal
import sys
import threading
import time

import spidev
from gpiozero import DigitalOutputDevice


class EEPROM:
    """Thread-safe SPI EEPROM wrapper using spidev and gpiozero."""

    def __init__(self, spi, cs_pin, lock):
        self.spi = spi
        self.cs = DigitalOutputDevice(cs_pin, active_high=False, initial_value=True)
        self.lock = lock

    def write(self, address, data):
        with self.lock:
            self.cs.off()
            try:
                self.spi.xfer2([0x02, (address >> 8) & 0xFF, address & 0xFF] + list(data))
            finally:
                self.cs.on()

    def read(self, address, length):
        with self.lock:
            self.cs.off()
            try:
                tx = [0x03, (address >> 8) & 0xFF, address & 0xFF] + [0x00] * length
                rx = self.spi.xfer2(tx)
                return bytes(rx[3:])
            finally:
                self.cs.on()

    def close(self):
        try:
            self.cs.close()
        except Exception:
            pass


def main():
    spi = spidev.SpiDev()
    lock = threading.Lock()
    eeprom = None

    try:
        try:
            spi.open(0, 0)
            spi.max_speed_hz = 1000000
            spi.mode = 0
        except Exception as e:
            print(f"Failed to initialize SPI bus: {e}", file=sys.stderr)
            return 1

        eeprom = EEPROM(spi, 5, lock)

        data_to_write = b'1234567890ABCDEF'
        read_thread = None

        def write_eeprom():
            try:
                eeprom.write(0, data_to_write)
                print("Data written to EEPROM.")
            except Exception as e:
                print(f"Error writing to EEPROM: {e}", file=sys.stderr)

        write_thread = threading.Thread(target=write_eeprom, daemon=True)
        write_thread.start()
        write_thread.join()

        def read_eeprom():
            try:
                time.sleep(0.1)
                data = eeprom.read(0, 16)
                print(f"Data read from EEPROM: {data}")
            except Exception as e:
                print(f"Error reading from EEPROM: {e}", file=sys.stderr)

        read_thread = threading.Thread(target=read_eeprom, daemon=True)
        read_thread.start()
        read_thread.join()

    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        if eeprom is not None:
            eeprom.close()
        try:
            spi.close()
        except Exception:
            pass
        print("Resources cleaned up.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

