import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
READ_INTERVAL = 1
THRESHOLD = 50.0
ALERT_PIN = 18

running = True

def signal_handler(signum, frame):
    global running
    running = False

def cleanup(ser):
    try:
        if ser is not None and ser.is_open:
            ser.close()
    except Exception:
        pass
    try:
        import RPi.GPIO as GPIO
        GPIO.cleanup()
    except Exception:
        pass

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(ALERT_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        sys.exit(1)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        cleanup(ser)
        sys.exit(1)

    try:
        while running:
            try:
                raw = ser.readline()
                if not raw:
                    time.sleep(READ_INTERVAL)
                    continue

                line = raw.decode('ascii', errors='replace').strip()
                if not line:
                    time.sleep(READ_INTERVAL)
                    continue

                try:
                    radiation_level = float(line)
                except ValueError:
                    print(f"Warning: could not parse '{line}' as float", file=sys.stderr)
                    time.sleep(READ_INTERVAL)
                    continue

                print(f"Radiation Level: {radiation_level:.2f} µSv/h")

                try:
                    GPIO.output(ALERT_PIN, GPIO.HIGH if radiation_level > THRESHOLD else GPIO.LOW)
                except Exception as e:
                    print(f"Warning: failed to set GPIO18: {e}", file=sys.stderr)

            except serial.SerialException as e:
                print(f"Serial communication error: {e}", file=sys.stderr)
                time.sleep(READ_INTERVAL)
                continue

            time.sleep(READ_INTERVAL)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup(ser)

if __name__ == '__main__':
    main()

