import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
READ_INTERVAL = 1
LOG_FILE = 'water_flow_log.txt'

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_flow_rate(serial_connection):
    try:
        data = serial_connection.readline().decode('ascii', errors='replace').strip()
        if not data:
            return None
        return float(data)
    except ValueError:
        print("Warning: Invalid data received from sensor.", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None

def log_flow_rate(flow_rate, log_file):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Flow Rate: {flow_rate} L/min\n'
    try:
        with open(log_file, 'a') as file:
            file.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            flow_rate = read_flow_rate(serial_connection)
            if flow_rate is not None:
                print(f'Flow Rate: {flow_rate} L/min')
                log_flow_rate(flow_rate, LOG_FILE)
            time.sleep(READ_INTERVAL)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
