import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'health_readings_log.txt'
READ_INTERVAL = 5

running = True

def signal_handler(signum, frame):
    global running
    running = False

def log_reading(hr, spo2, log_file):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Heart Rate: {hr} bpm, SpO2: {spo2} %\n'
    try:
        with open(log_file, 'a', encoding='utf-8') as f:
            f.write(log_entry)
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)

def main():
    global running
    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f'Connected to {SERIAL_PORT} at {BAUD_RATE} baud.')
            while running:
                try:
                    raw_data = ser.readline()
                    if not raw_data:
                        print('No data received (timeout).', file=sys.stderr)
                    else:
                        data = raw_data.decode('ascii', errors='replace').strip()
                        if data:
                            parts = data.split(',')
                            if len(parts) != 2:
                                print(f'Invalid data format: {data}', file=sys.stderr)
                            else:
                                hr, spo2 = parts[0].strip(), parts[1].strip()
                                try:
                                    hr_int = int(hr)
                                    spo2_int = int(spo2)
                                    print(f'Heart Rate: {hr_int} bpm, SpO2: {spo2_int} %')
                                    log_reading(hr_int, spo2_int, LOG_FILE)
                                except ValueError as e:
                                    print(f'Error parsing data: {e} (raw: {data})', file=sys.stderr)
                except serial.SerialException as e:
                    print(f'Serial communication error: {e}', file=sys.stderr)
                except OSError as e:
                    print(f'I/O error: {e}', file=sys.stderr)

                for _ in range(READ_INTERVAL):
                    if not running:
                        break
                    time.sleep(1)
    except serial.SerialException as e:
        print(f'Failed to open serial port {SERIAL_PORT}: {e}', file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f'Failed to open serial port {SERIAL_PORT}: {e}', file=sys.stderr)
        sys.exit(1)
    finally:
        print('Program terminated.')

if __name__ == '__main__':
    main()

