import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)


@dataclass
class GPS_readings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellite_count: Optional[int] = None


class GPSReader:
    """Reads NMEA GPGGA sentences from a UART GPS module and parses them."""

    def __init__(self, port: str = '/dev/serial0', baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port: Optional[serial.Serial] = None

    def connect(self) -> bool:
        """Open the serial port; return True on success, False on failure."""
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout
            )
            logging.info(f"Connected to GPS on {self.port} @ {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to connect to GPS on {self.port}: {e}")
            self.serial_port = None
            return False
        except Exception as e:
            logging.error(f"Unexpected error opening {self.port}: {e}")
            self.serial_port = None
            return False

    def disconnect(self) -> None:
        """Close the serial port if open; never raises."""
        if self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                logging.info("GPS serial port closed.")
            except Exception as e:
                logging.error(f"Error closing serial port: {e}")
            finally:
                self.serial_port = None

    def _verify_checksum(self, sentence: str) -> bool:
        """Validate the NMEA checksum: *XX at end of data field after '*'."""
        if '*' not in sentence:
            return False
        body, _, csum = sentence.rpartition('*')
        if not body.startswith('$'):
            return False
        computed = 0
        for ch in body[1:]:
            computed ^= ord(ch)
        try:
            return computed == int(csum.strip(), 16)
        except ValueError:
            return False

    def _parse_gpgga(self, data: str) -> Optional[GPS_readings]:
        """Parse a GPGGA sentence; return None on any validation/parse failure."""
        if not data.startswith('$GPGGA'):
            return None
        if not self._verify_checksum(data):
            logging.warning(f"Checksum failed for GPGGA sentence: {data.strip()}")
            return None

        fields = data.split(',')
        if len(fields) < 15:
            logging.warning(f"GPGGA sentence has {len(fields)} fields, expected >= 15: {data.strip()}")
            return None

        try:
            lat_raw = fields[2]
            lon_raw = fields[4]
            lat_dir = fields[3]
            lon_dir = fields[5]
            sats = fields[7]
            alt_raw = fields[9]

            if not lat_raw or not lon_raw:
                logging.warning("GPGGA: latitude or longitude missing.")
                return None

            lat_deg = float(lat_raw[:2])
            lat_min = float(lat_raw[2:])
            latitude = lat_deg + (lat_min / 60.0)
            if lat_dir == 'S':
                latitude = -latitude

            lon_deg = float(lon_raw[:3])
            lon_min = float(lon_raw[3:])
            longitude = lon_deg + (lon_min / 60.0)
            if lon_dir == 'W':
                longitude = -longitude

            altitude = float(alt_raw) if alt_raw else None
            satellite_count = int(sats) if sats else None

            return GPS_readings(latitude, longitude, altitude, satellite_count)

        except ValueError as e:
            logging.error(f"Numeric conversion error in GPGGA: {e} | sentence: {data.strip()}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error parsing GPGGA: {e} | sentence: {data.strip()}")
            return None

    def read_gps_data(self) -> Optional[GPS_readings]:
        """Read one line from the serial port and parse it as GPGGA."""
        if self.serial_port is None or not self.serial_port.is_open:
            logging.error("Serial port not open; cannot read.")
            return None

        try:
            raw = self.serial_port.readline()
            if not raw:
                logging.warning("Serial read timeout: no data received.")
                return None

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                return None

            return self._parse_gpgga(line)

        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error reading GPS: {e}")
            return None


def main() -> None:
    gps = GPSReader(port='/dev/serial0', baudrate=9600, timeout=1.0)

    def _signal_handler(signum, frame):
        logging.info(f"Signal {signum} received; shutting down.")
        gps.disconnect()
        sys.exit(0)

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not gps.connect():
        logging.error("Failed to connect to GPS. Exiting.")
        sys.exit(1)

    try:
        while True:
            readings = gps.read_gps_data()
            if readings is not None:
                logging.info(
                    f"Lat: {readings.latitude}, Lon: {readings.longitude}, "
                    f"Alt: {readings.altitude}, Sats: {readings.satellite_count}"
                )
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received.")
    finally:
        gps.disconnect()


if __name__ == '__main__':
    main()

