    try:
        ser = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout,
        )
        if not ser.is_open:
            raise serial.SerialException(f"Failed to open {port}")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_pulse_oximeter_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        data = raw.decode('ascii', errors='replace').strip()
        if not data:
            return None
        return data
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None
    except OSError as e:
