BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'power_consumption.log'

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def log_power_data(power_value):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Power: {power_value} W\n'
    try:
        with open(LOG_FILE, 'a') as logfile:
            logfile.write(log_entry)
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f'Error opening serial port: {e}', file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f'Error reading from serial port: {e}', file=sys.stderr)
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                power = float(line)
            except ValueError:
                print(f'Invalid data received (not a number): {line!r}', file=sys.stderr)
                continue

            log_power_data(power)
    finally:
        if ser.is_open:
            ser.close()
        print('Serial port closed. Exiting.')

if __name__ == '__main__':
    main()

