import serial
import time
import json
from flask import Flask, Response, request, jsonify

app = Flask(__name__)

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1
SCPI_DELAY = 0.1

data_list = [
    {"id": 1, "name": "item1", "done": False},
    {"id": 2, "name": "item2", "done": False},
]


def get_serial_response(ser, query):
    """Send a query and return the decoded response, or None on error."""
    try:
        ser.reset_input_buffer()
        ser.write(query.encode('ascii'))
        time.sleep(SCPI_DELAY)
        raw = ser.read(ser.in_waiting or 1024)
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException:
        return None


@app.route('/version', methods=['GET'])
def version():
    """Query the connected SCPI instrument for its identification."""
    ser = None
    try:
        ser = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            timeout=SERIAL_TIMEOUT,
        )
        response = get_serial_response(ser, '*IDN?\n')
        if response is None:
            return Response(
                '<h1>Serial communication error</h1>',
                status=503,
                mimetype='text/html',
            )
        html = response.replace('\n', '<br>')
        return Response(html, mimetype='text/html')
    except serial.SerialException:
        return Response(
            '<h1>Serial port error</h1>',
            status=503,
            mimetype='text/html',
        )
    finally:
        if ser is not None and ser.is_open:
            ser.close()


@app.route('/getdata', methods=['GET'])
def get_data():
    return jsonify(data_list)


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_set_item(item_id):
    item = next((i for i in data_list if i['id'] == item_id), None)
    if item is None:
        return Response('<h1>Item not found</h1>', status=404, mimetype='text/html')
    return jsonify(item)


@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def get_post_item(item_id, name):
    new_item = {
        "id": item_id,
        "name": name,
        "done": False,
    }
    data_list.append(new_item)
    return jsonify(data_list)


@app.route('/postjson', methods=['POST', 'GET'])
def post_json():
    if request.method == 'POST':
        content_type = request.headers.get('Content-Type', '')
        if 'application/json' in content_type:
            try:
                data = request.get_json(silent=True)
                if data is None:
                    data = request.form
            except Exception:
                data = request.form
        else:
            data = request.form

        new_item = {
            "id": data_list[-1]['id'] + 1 if data_list else 1,
            "name": data.get('name', ''),
            "done": bool(data.get('done', False)),
        }
        data_list.append(new_item)
        return jsonify(data_list), 201
    return jsonify(data_list)


if __name__ == '__main__':
    app.run(host='0.0.0.0')

