import bluetooth
import time
import sys

BLUETOOTH_MAC_ADDRESS = "00:06:54:60:5B:B4"
RFCOMM_PORT = 4
RFCOMM_CHANNEL = 4
BAUD_RATE = 38400
TRANSMIT_DELAY = 0.1


def send_command(sock, command):
    """Send a command prefixed with 'X' and a newline over the Bluetooth socket."""
    message = f"X{command}\n"
    try:
        sock.sendall(message.encode("utf-8"))
    except bluetooth.BluetoothSocketError as exc:
        raise RuntimeError(f"Failed to send command '{command}': {exc}") from exc


def main():
    try:
        sock = bluetooth.BluetoothSocket(bluetooth.RFCOMM)
        sock.connect((BLUETOOTH_MAC_ADDRESS, RFCOMM_PORT))
        sock.settimeout(5.0)
        sock.setsockopt(bluetooth.SOL_RFCOMM, bluetooth.SO_RCVBUF, 4096)
    except bluetooth.BluetoothSocketError as exc:
        print(f"Error: could not connect to Bluetooth device "
              f"{BLUETOOTH_MAC_ADDRESS}:{RFCOMM_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: unexpected failure during connection: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            try:
                command = input("Enter command: ")
            except EOFError:
                print("\nEnd of input reached.")
                break

            if command.lower() == "exit":
                break

            try:
                send_command(sock, command)
            except RuntimeError as exc:
                print(exc, file=sys.stderr)
                break

            time.sleep(TRANSMIT_DELAY)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        try:
            sock.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

